const CHARTS = [
  { key: 'kayitz', name: 'שבת קיץ', columns: KAYITZ_COLUMNS, rules: KAYITZ_RULES, build: buildKayitzRow,
    note: 'Pesach to Sukkos. The early פלג minyanim run for part of it, which is why it has four מנחה columns the winter chart does not.' },
  { key: 'choref', name: 'שבת חורף', columns: CHOREF_COLUMNS, rules: CHOREF_RULES, build: buildChorefRow,
    note: 'Sukkos to Pesach. A page holding a week past the spring clock change prints as a full שבת קיץ chart instead, so the last page of a winter season can be a summer one.' },
  { key: 'weekday', name: 'Weekday', columns: WEEKDAY_COLUMNS, rules: WEEKDAY_RULES, build: buildWeekdayRow,
    note: 'One row per week, covering Sunday through Thursday. Every time on it has to work for all five days at once, which is what makes it the only chart whose times move themselves.' },
];

/** Printed order, left to right. The chart reverses the workbook's B..L so that reading
 *  right to left after the parsha follows the week forward; this lists them the way they
 *  appear across the page. */
const printedOrder = (columns) => [...columns].reverse();

/** A week to work the examples on: whichever the rest of the app is showing, if this
 *  chart covers it, and otherwise the nearest one that chart has. */
function exampleWeek(state, season, settings) {
  const sheets = (state.sheets || []).filter((s) => (season === 'weekday' ? s.season === 'weekday' : s.season === season));
  const weeks = sheets.flatMap((s) => s.weeks || []);
  if (!weeks.length) return null;
  const serial = currentSerial(weeks.map((w) => w.serial), settings, (s) => weekEndsMins(s, state, settings));
  const found = weeks.find((w) => w.serial === serial) || weeks[0];
  return { ...found, date: new Date(found.date) };
}

const fmtWeek = (week) =>
  new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', month: 'long', day: 'numeric', year: 'numeric' }).format(week.date);

function chartHtml(chart, state, settings) {
  const week = exampleWeek(state, chart.key, settings);
  let row = {};
  if (week) {
    try {
      row = chart.build(week, settings) || {};
    } catch {
      row = {};
    }
  }

  const entries = printedOrder(chart.columns)
    .map(({ key, header }) => {
      const rule = chart.rules[key];
      const worked = week && key in row
        ? `<div class="calc-worked"><span class="calc-worked-label">That week it comes out</span><span class="calc-worked-value">${cellHtml(row[key])}</span></div>`
        : '';
      return `
        <div class="calc-col">
          <div class="calc-col-head">
            <bdi class="calc-col-name">${calcEsc(String(header).replace(/\n/g, ' '))}</bdi>
            <span class="calc-col-key">column ${calcEsc(key)}</span>
          </div>
          <p class="calc-plain">${rule ? isolateHebrew(text(rule.plain, settings)) : 'Not written up yet.'}</p>
          ${worked}
          ${rule ? `<details class="calc-exact"><summary>The exact rule</summary><p>${isolateHebrew(text(rule.exact, settings))}</p></details>` : ''}
        </div>`;
    })
    .join('');

  const which = week
    ? `<p class="hint">Worked through on <strong>${calcEsc(fmtWeek(week))}</strong>, the week this chart is on now.</p>`
    : '<p class="hint">Generate a season and each column will show what it comes out to that week.</p>';

  return `
    <details class="panel calc-chart" data-chart="${chart.key}">
      <summary><bdi>${calcEsc(chart.name)}</bdi></summary>
      <div class="panel-body">
        <p class="hint">${isolateHebrew(chart.note)}</p>
        ${which}
        <div class="calc-cols">${entries}</div>
      </div>
    </details>`;
}

function renderCalculations(container, state, onOpenTab) {
  const settings = resolveSettings(state.settings);
  container.innerHTML = `
    <h2>Calculations</h2>
    <p class="hint">Every column on every chart, and how its times are worked out.</p>

    <div class="guide-lede">
      <p>Two answers for each one. The plain rule is what the column is, in the shul's terms. <strong>The exact rule</strong> under it is the formula as the program has it, down to the rounding, for checking against the workbook.</p>
      <p>The numbers beside each rule are not written here: they are produced by running the real formula on a real week, so a time on this page is the time on that board.</p>
    </div>

    <p class="hint calc-not-rules">This is not the <button type="button" class="linkish" id="calc-to-rules">Rules in Settings</button>. Those are the shul's own exceptions, the ones that add דרשה on שבת הגדול and mark ט באב, applied on top of everything below. What is here is the calculation underneath, which is the same every year and is not editable: it comes from the workbook the boards were always made from.</p>

    ${CHARTS.map((c) => chartHtml(c, state, settings)).join('')}

    <details class="panel">
      <summary>Things that are true of every column</summary>
      <div class="panel-body">
        <p><strong>Where the sun is</strong> comes from the שול's location, elevation and timezone in Settings, so moving those moves every time on every chart.</p>
        <p><strong>Underlined</strong> means the מנין davens בבית מדרש למטה. It is set by the formula, not typed, except where a cell has been typed over by hand.</p>
        <p><strong>Friday columns are worked on the Friday</strong>, not on the Shabbos the row is named for. The Shabbos columns are worked on the Shabbos.</p>
        <p><strong>ט באב</strong> is added automatically when the 9th of Av falls on that Shabbos, to the Shabbos מנחה and the motzei Shabbos מעריב. It is a fact of the calendar rather than a rule anyone set, so it is not in the rules list and cannot be switched off.</p>
        <p><strong>Then the rules, then anything typed.</strong> A rule from Settings is applied to the computed value, and a cell typed over by hand wins over both.</p>
      </div>
    </details>
  `;

  container.querySelector('#calc-to-rules')?.addEventListener('click', () => onOpenTab('settings'));
}

// ==== pagination.js ====
// Splits a generated week list across however many printable pages the user chooses
// (3, 4, or any other count), by user-chosen per-page counts.
function validatePageSizes(total, sizes) {
  const sum = sizes.reduce((a, b) => a + (Number(b) || 0), 0);
  if (sum !== total) return `Page sizes add up to ${sum}, but there are ${total} weeks. They must add up to exactly ${total}.`;
  if (sizes.some((s) => Number(s) < 0)) return 'Page sizes cannot be negative.';
  return null;
}

/** Even default split across `numPages` pages (earlier pages absorb the remainder one
 *  at a time), used to pre-fill the page-size inputs before the user adjusts them. */
function defaultPageSizes(total, numPages) {
  const base = Math.floor(total / numPages);
  const rem = total % numPages;
  return Array.from({ length: numPages }, (_, i) => base + (i < rem ? 1 : 0));
}

/** Per-page counts that break `targetWeeks` at the same dates `sourceSizes` breaks
 *  `sourceWeeks` - so a Weekday chart's page 1 covers the same stretch of the year as
 *  its Shabbos sheet's page 1, even though the two lists aren't the same length (the
 *  Weekday one also carries Yom Tov weeks that have no parsha). A target week falling in
 *  the gap between two source pages lands on the earlier one, matching how the season
 *  boundaries themselves are assigned in sheets/weeks.js. */
function alignPageSizesTo(sourceWeeks, sourceSizes, targetWeeks) {
  const cutoffs = []; // serial of the first source week on each page after the first
  let idx = 0;
  for (let i = 0; i < sourceSizes.length - 1; i++) {
    idx += Number(sourceSizes[i]) || 0;
    cutoffs.push(sourceWeeks[idx] ? sourceWeeks[idx].serial : Infinity);
  }
  const counts = new Array(sourceSizes.length).fill(0);
  for (const week of targetWeeks) {
    let page = 0;
    while (page < cutoffs.length && week.serial >= cutoffs[page]) page++;
    counts[page]++;
  }
  return counts;
}

function splitWeeksIntoPages(weeks, sizes) {
  const pages = [];
  let i = 0;
  for (const size of sizes) {
    pages.push(weeks.slice(i, i + size));
    i += size;
  }
  return pages;
}

// ==== ui/pdf-page.js ====
// Handing the chart over as a real PDF.
//
// Why this exists at all: an iPhone will not print these boards at the right size and
// there is no way to make it. Safari ignores @page's size descriptor, imposes margins that
// cannot be zeroed, and reports a width for print media queries that is the phone's own
// screen rather than the paper, so every route to "fit the page to the sheet" is guessing.
// Three rounds of that produced, in turn, a chart with its right columns sliced off, a
// chart printed at a third of the sheet, and a chart held at a safe but small 72%.
//
// A PDF ends the argument. Its page size is written into the file, so 11in x 8.5in
// landscape is a fact the phone reads rather than a request it can ignore, and the print
// sheet then has nothing left to decide. Open it, share it, print it, mail it to whoever
// prints the boards.
//
// This is additive and deliberately kept to one side. The Print button and the whole
// print.css path are untouched, so what a desktop puts on paper is exactly what it put on
// paper before: that output is checked pixel for pixel and is not something to put at risk
// for a phone's benefit.
//
// The page is rasterised rather than drawn as text. Redrawing the chart as PDF text would
// mean embedding the Hebrew faces and laying out every right-to-left run by hand, which is
// a second renderer to keep in step with the first, and the first is the one that has been
// checked against the workbook. Photographing what the browser already lays out cannot
// drift from it. At the scale below the result is about 300 dots per inch, which is more
// than a laser printer resolves.
//
// The two libraries this needs are vendored in /vendor and loaded only by the site, never
// by the offline build (build-offline.py strips the tags). Everything here therefore has
// to cope with them being absent, which is what pdfReady() is for: no libraries, no
// button, and the offline copy carries neither.

/** Whether the vendored libraries actually arrived. The offline build ships without them
 *  on purpose, and a slow network can lose them on the site too, so this is asked before
 *  the button is offered rather than assumed. */
function pdfReady() {
  return typeof window !== 'undefined' && !!window.html2canvas && !!(window.jspdf && window.jspdf.jsPDF);
}

function pdfButtonHtml(id = 'pdf-btn') {
  if (!pdfReady()) return '';
  // No btn-primary: Print is the one filled button on this screen and stays the one thing
  // worth pressing. This is the quiet alternative beside it, styled like Previous/Next.
  return `<button type="button" class="pdf-btn" id="${id}">PDF</button>`;
}

/** 11in x 8.5in at 300dpi is 3300 x 2550. The pages are laid out at 96dpi, so photograph
 *  them at 300/96 to land there. Higher makes a file too big to mail without making the
 *  print any better; lower starts to show on the thin rules. */
const PDF_DPI = 300;
const CSS_DPI = 96;

/** JPEG rather than PNG. The chart is mostly flat white with grey banding, which PNG does
 *  compress well, but at 3300px across a two page PDF still came out around 4MB, and these
 *  get sent to people. At this quality the difference is not visible on paper and the file
 *  is a fraction of the size. */
const JPEG_QUALITY = 0.92;

/** html2canvas is from 2022 and does not know the color() function, which it meets here
 *  and throws on: "Attempting to parse an unsupported color function". The striped body
 *  rows are a color-mix (see tbody tr:nth-child(even) in app.css), and a browser reports a
 *  color-mix back as color(srgb r g b), so the very banding that makes the chart readable
 *  is what stopped the PDF being made at all.
 *
 *  Not an engine quirk to shrug at either: color-mix resolves to color(srgb ...) in Safari
 *  as much as in Chromium, so without this there would be no PDF on the phone this is for.
 *
 *  srgb is the space the numbers are already in, so the conversion is a multiplication by
 *  255, not a colour-management problem. */
function srgbToRgb(value) {
  const m = /^color\(\s*srgb\s+([\d.eE+-]+)\s+([\d.eE+-]+)\s+([\d.eE+-]+)\s*(?:\/\s*([\d.eE+-]+)\s*)?\)$/.exec(String(value).trim());
  if (!m) return null;
  const [r, g, b] = [m[1], m[2], m[3]].map((n) => Math.round(Math.min(1, Math.max(0, parseFloat(n))) * 255));
  const a = m[4] === undefined ? 1 : parseFloat(m[4]);
  return a >= 1 ? `rgb(${r}, ${g}, ${b})` : `rgba(${r}, ${g}, ${b}, ${a})`;
}

/** Every colour property html2canvas reads off an element. */
const COLOUR_PROPS = [
  'color', 'backgroundColor', 'borderTopColor', 'borderRightColor',
  'borderBottomColor', 'borderLeftColor', 'outlineColor', 'textDecorationColor',
];

/** Everything the library needs helping with, done on its own clone.
 *
 *  html2canvas hands the copy it is about to photograph to onclone, so none of this
 *  touches the chart in front of the person: nothing flickers, and there is nothing to put
 *  back if it throws.
 *
 *  Two jobs. The colours, above. And the underlines, which mark an alternate time and are
 *  the whole point of half the times on the board: the library does not implement
 *  text-underline-offset, so it drew every one of them hard against the digits. Measured
 *  by scanning the rows of both renderings of the same cell, the browser leaves a clear
 *  band of paper between the bottom of the digits and the line, and the PDF ran the line
 *  straight on from them, which is what came back as "the underline is attached to the
 *  time".
 *
 *  A border stands in for the decoration, because a border it does implement, and a
 *  border on an inline box sits below the descender rather than tight under the baseline.
 *  It is not the browser's own placement to the pixel: measured, the gap comes out a
 *  little larger than print's. It is separated, which is what the line is for. */
function prepareClone(root) {
  const view = root.ownerDocument.defaultView;
  if (!view) return;
  const all = [root, ...root.querySelectorAll('*')];
  for (const el of all) {
    const cs = view.getComputedStyle(el);
    for (const prop of COLOUR_PROPS) {
      const plain = srgbToRgb(cs[prop]);
      if (plain) el.style[prop] = plain;
    }
    if (cs.textDecorationLine.includes('underline')) {
      el.style.textDecoration = 'none';
      el.style.borderBottom = `1px solid ${srgbToRgb(cs.color) || cs.color}`;
    }
  }
  redrawZoomAsScale(root, view);
}

/** html2canvas does not implement zoom, and the week card uses one inside itself.
 *
 *  .week-lines-inner is magnified by --fit-scale to fill the height of the card, which on
 *  a typical week is about 1.5. The library ignored it and drew that block at its
 *  unmagnified size, so the weekday times came out small, loosely spaced and sitting away
 *  from their labels: measured, the browser paints that block 197px wide where
 *  html2canvas rendered 131.
 *
 *  Clearing the zoom is not an option, because here it is not a fit-to-window that can be
 *  thrown away, it is how the card is laid out. So it is restated as the transform that
 *  means the same thing, which the library does implement. The catch is that the two size
 *  boxes differently: under zoom a percentage width resolves against the parent divided by
 *  the zoom, while under a transform it resolves against the parent itself and would come
 *  out magnified twice over. Pinning the element to the size it already computed to,
 *  before anything is changed, is what keeps the two equivalent.
 *
 *  Where it ends up then has to be put right, and no fixed transform-origin does that on
 *  its own. A zoomed box is laid out at its shrunken size and painted outwards from
 *  wherever that box sits, and where it sits depends on how its parent aligns it:
 *  .week-lines-inner is centred with margin-inline: auto, so scaling it from the top left
 *  walked it rightwards until the labels were clipped off the edge of the card. Rather
 *  than guess an origin per element, each one is measured against its own parent before
 *  and after and translated back by the difference, which is right however it is aligned.
 *
 *  Three passes, and the order matters: read every element before changing any, or
 *  resizing one moves another still to be read. Positions are taken relative to the
 *  parent rather than the viewport so that correcting an outer element does not
 *  invalidate the reading for something inside it. */
function redrawZoomAsScale(root, view) {
  const near = (el) => {
    const parent = el.parentElement;
    const r = el.getBoundingClientRect();
    if (!parent) return { x: r.left, y: r.top };
    const p = parent.getBoundingClientRect();
    return { x: r.left - p.left, y: r.top - p.top };
  };
  const found = [];
  for (const el of [root, ...root.querySelectorAll('*')]) {
    const z = parseFloat(view.getComputedStyle(el).zoom);
    if (z && Math.abs(z - 1) > 0.001) found.push({ el, z, w: el.offsetWidth, h: el.offsetHeight, was: near(el) });
  }
  for (const { el, z, w, h } of found) {
    el.style.zoom = '1';
    el.style.width = `${w}px`;
    el.style.height = `${h}px`;
    el.style.transformOrigin = 'top left';
    el.style.transform = `scale(${z})`;
  }
  for (const { el, z, was } of found) {
    const now = near(el);
    const dx = was.x - now.x;
    const dy = was.y - now.y;
    if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5) {
      el.style.transform = `translate(${dx}px, ${dy}px) scale(${z})`;
    }
  }
}

/** Undo whatever the screen has done to fit these sheets into a window, and give back a
 *  function that puts it all back.
 *
 *  The sheets are photographed where they stand, and html2canvas reads the scaling: with
 *  it left on, the first PDF came out with the chart a third of the size in the corner of
 *  the sheet, which is the very fault this file exists to fix.
 *
 *  Three fits are covered, because the screens shrink in three different ways and
 *  html2canvas is fooled by all of them. The chart browser puts a transform on .pages and
 *  sizes the wrapper round it (fitChartToWindow). The week cards set --page-zoom on their
 *  container and carry is-scaled (fitPagesToWindow). And the one-sheet week view puts an
 *  inline zoom on the .week-pair itself (fitSheetToWindow), which is the one that caught
 *  this out: clearing only the container left the sheet's own zoom in place, and since
 *  html2canvas does not implement zoom at all the PDF came back a third of the size in the
 *  corner of the page with the text piled on itself.
 *
 *  So any inline zoom anywhere inside is cleared, rather than the two places known about
 *  today. A rule-driven zoom is left alone deliberately: --fit-scale shrinks a long week's
 *  times to keep them on the card, and clearing that would not undo a fit, it would
 *  overflow the page. */
function unscale(hostEl) {
  const fit = hostEl.parentElement;
  const zoomed = [hostEl, ...hostEl.querySelectorAll('*')]
    .filter((el) => el.style && el.style.zoom)
    .map((el) => [el, el.style.zoom]);
  const held = {
    transform: hostEl.style.transform,
    width: hostEl.style.width,
    pageZoom: hostEl.style.getPropertyValue('--page-zoom'),
    scaled: hostEl.classList.contains('is-scaled'),
    fitHeight: fit ? fit.style.height : null,
    fitOverflow: fit ? fit.style.overflow : null,
  };
  for (const [el] of zoomed) el.style.removeProperty('zoom');
  hostEl.style.transform = 'none';
  hostEl.style.width = '';
  hostEl.style.removeProperty('--page-zoom');
  hostEl.classList.remove('is-scaled');
  if (fit) {
    fit.style.height = 'auto';
    fit.style.overflow = 'visible';
  }
  return () => {
    for (const [el, value] of zoomed) el.style.zoom = value;
    hostEl.style.transform = held.transform;
    hostEl.style.width = held.width;
    if (held.pageZoom) hostEl.style.setProperty('--page-zoom', held.pageZoom);
    if (held.scaled) hostEl.classList.add('is-scaled');
    if (fit) {
      fit.style.height = held.fitHeight;
      fit.style.overflow = held.fitOverflow;
    }
  };
}

/** Photograph each sheet inside hostEl and put one on each page of a letter PDF.
 *
 *  @param {object} opts
 *    - sheet: what counts as one sheet of paper. '.page' for the wall chart, '.week-card'
 *      or '.week-pair' for the week, since a paired sheet is one piece of paper holding
 *      two cards and must not be photographed as two.
 *    - orientation/size: the wall chart is landscape 11 x 8.5, the week portrait 8.5 x 11.
 *      They travel together and must agree, or the image is laid on a page turned the
 *      other way and everything this was built for is lost.
 *
 *  Whatever the screen did to fit the sheets is undone first and put back in a finally,
 *  including if anything throws. */
async function buildPdf(hostEl, opts = {}) {
  const { sheet = '.page', orientation = 'landscape', size = [11, 8.5], filename = 'zmanim.pdf' } = opts;
  if (!pdfReady()) throw new Error('PDF libraries are not loaded');
  const restore = unscale(hostEl);
  try {
    const sheets = [...hostEl.querySelectorAll(sheet)];
    if (!sheets.length) throw new Error('there is nothing on the screen to turn into a PDF');
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ orientation, unit: 'in', format: 'letter' });
    const scale = PDF_DPI / CSS_DPI;
    for (let i = 0; i < sheets.length; i++) {
      const canvas = await window.html2canvas(sheets[i], {
        scale,
        backgroundColor: '#ffffff',
        // The shot is of this element at its own size, not of a scrolled window. Left to
        // work it out, html2canvas measured the phone's viewport and cropped the page to
        // it, so the sheet came out with only the left-hand columns on it.
        width: sheets[i].offsetWidth,
        height: sheets[i].offsetHeight,
        windowWidth: sheets[i].offsetWidth,
        windowHeight: sheets[i].offsetHeight,
        scrollX: 0,
        scrollY: 0,
        useCORS: true,
        logging: false,
        onclone: (_doc, el) => prepareClone(el),
      });
      if (i > 0) doc.addPage('letter', orientation);
      // Corner to corner: the sheet on the screen is already letter and so is the PDF
      // page, so there is no fitting to do and no margin to add. Anything else would
      // reintroduce the shrink-to-fit this whole file exists to avoid.
      doc.addImage(canvas.toDataURL('image/jpeg', JPEG_QUALITY), 'JPEG', 0, 0, size[0], size[1], undefined, 'FAST');
    }
    return { doc, filename };
  } finally {
    restore();
  }
}

/** Hand the finished PDF to the person.
 *
 *  A tab is opened on the click itself, before any of the work, and pointed at the file
 *  afterwards. Opening it at the end instead is what a popup blocker stops: by then the
 *  tap that authorised it is long over, and on an iPhone this is exactly where it would be
 *  refused. If the tab was blocked anyway, or there never was one, it falls back to a
 *  download, which is the ordinary answer on a desktop. */
function deliver(doc, filename, tab) {
  const url = URL.createObjectURL(doc.output('blob'));
  if (tab && !tab.closed) {
    tab.location = url;
  } else {
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
  }
  // Long enough for the tab or the download to have taken hold. Revoking straight away
  // left an iPhone showing a blank viewer.
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}

/** @param {object} opts
 *    - host: () => Element, and a function rather than an element because both screens
 *      rebuild their container whenever the week or the spread changes, so anything held
 *      from when the button was wired would be pointing at markup already thrown away.
 *    - name: () => string, the filename. These get saved and mailed on, so they are named
 *      for what they cover.
 *    - sheet/orientation/size: handed straight to buildPdf. */
function wirePdfButton(root, opts = {}) {
  const { host, name, sheet, orientation, size, id = 'pdf-btn' } = opts;
  const btn = root.querySelector(`#${id}`);
  if (!btn) return;
  btn.addEventListener('click', async () => {
    const hostEl = host && host();
    if (!hostEl) return;
    // Opened now, while the tap is still what is happening. See deliver().
    const tab = window.open('', '_blank');
    const said = btn.textContent;
    btn.disabled = true;
    btn.textContent = 'Working...';
    try {
      const { doc, filename } = await buildPdf(hostEl, {
        sheet, orientation, size, filename: name ? name() : 'zmanim.pdf',
      });
      deliver(doc, filename, tab);
    } catch (err) {
      if (tab && !tab.closed) tab.close();
      console.error('PDF failed', err);
      // Said on the button rather than in an alert: the person is holding a phone and an
      // alert here would be one more thing to dismiss.
      btn.textContent = 'PDF failed';
      setTimeout(() => { btn.textContent = said; }, 2500);
      return;
    } finally {
      btn.disabled = false;
      if (btn.textContent === 'Working...') btn.textContent = said;
    }
  });
}

// ==== ui/print-page.js ====
// Printing.
//
// One button a screen, which opens the browser's own print dialog and lets the person
// choose there what they want: which pages, which printer, portrait or landscape. Each
// page used to carry its own "Print this page" as well, on top of a "Print all" at the
// top, which was two answers to one question in two places on the same screen.
//
// There was a printWith() here that put a class on the body for the length of a print
// run, so that both week cards could be laid out on one landscape sheet for the printer
// and taken apart again straight after. That sheet is a view you can sit on now (see
// pairView in ui/week-view.js), so there is nothing left that has to be assembled for the
// dialog and pulled down afterwards. Printing is printing what is on the screen.

/** The one print button a screen carries. Plain window.print(): everything on the screen
 *  is what goes to the dialog, and the choosing happens there. */
function printButtonHtml(id = 'print-btn') {
  return `<button type="button" class="btn-primary print-btn" id="${id}">Print</button>`;
}

function wirePrintButton(root, id = 'print-btn') {
  root.querySelector(`#${id}`)?.addEventListener('click', () => window.print());
}

// ==== ui/rich-text.js ====
// Shared formatting toolbar for the app's contenteditable fields - the sheet's own cells
// (ui/sheet-view.js) and the שחרית schedule editor in Settings (ui/settings-view.js).
// Underline goes through execCommand, which already handles the add/remove toggle and
// partial selections correctly; text size is a plain <span class="big"> wrap, so what's
// stored stays readable HTML rather than the <font size> tags execCommand would emit.

/** The modifier key as this machine's user would write it, for the shortcut hints. */
const MOD = /mac|iphone|ipad/i.test(navigator.userAgent) ? '⌘' : 'Ctrl';

/** Toolbar markup. `label` prefixes it (e.g. "Selected text:") when it needs to say what
 *  it acts on. Each button's tooltip names its keyboard shortcut - the toolbar is the
 *  only place they're discoverable. */
function richTextToolbarHtml(label = '') {
  return `<span class="rt-toolbar no-print">
    ${label ? `<span class="rt-label">${label}</span>` : ''}
    ${richTextButtonsHtml()}
  </span>`;
}

/** Just the buttons, for a container that supplies its own wrapper (the floating bar). */
function richTextButtonsHtml() {
  return `<button type="button" data-rt="underline" title="Underline / remove underline from the selected text  (${MOD}+U)"><u>U</u></button>
    <button type="button" data-rt="big" title="Make the selected text bigger  (${MOD}+Shift+&gt;)">A&plus;</button>
    <button type="button" data-rt="unbig" title="Put the selected text back to normal size  (${MOD}+Shift+&lt;)">A&minus;</button>`;
}

/** Ctrl+Shift+> / Ctrl+Shift+< for the size buttons, matching what Word and Google Docs
 *  use. Underline needs nothing: Ctrl+U is already built into contenteditable, and it
 *  fires an input event, so the edit saves the same way a toolbar click does.
 *
 *  One listener for the whole app, resolving the editor from whatever has focus - the
 *  sheet's cells and the Settings שחרית editor both qualify, and neither can be reached
 *  by a keystroke without being focused first. Registered once, since the views that use
 *  the toolbar re-render freely. */
let shortcutsWired = false;
function wireShortcutsOnce() {
  if (shortcutsWired) return;
  shortcutsWired = true;
  document.addEventListener('keydown', (e) => {
    const editor = document.activeElement;
    if (!editor?.isContentEditable || !(e.ctrlKey || e.metaKey) || !e.shiftKey) return;
    // Reading both the shifted character and the unshifted key, since which one arrives
    // depends on the keyboard layout.
    const cmd = ['>', '.'].includes(e.key) ? 'big' : ['<', ','].includes(e.key) ? 'unbig' : null;
    if (!cmd) return;
    e.preventDefault();
    applyRichTextCommand(cmd, editor);
    editor.dispatchEvent(new Event('input', { bubbles: true }));
  });
}

/** The same three buttons, following the selection.
 *
 *  The toolbar at the top of the sheet is a long way from the cell you're editing, and on
 *  a phone it can be off screen entirely. This puts the buttons right above whatever you
 *  just selected, and works for any editable field in the app, since it resolves the
 *  editor from the selection rather than from a particular view.
 *
 *  Built once and reused: it's a single element parked on <body> at position:fixed, so it
 *  sits above everything without caring what the page around it is doing. */
let floatEl = null;
function floatingToolbarOnce() {
  if (floatEl) return;
  floatEl = document.createElement('div');
  floatEl.className = 'rt-float rt-toolbar no-print';
  floatEl.hidden = true;
  floatEl.innerHTML = richTextButtonsHtml();
  document.body.appendChild(floatEl);
  // The editor is whichever editable field holds the selection, resolved at click time.
  wireRichTextToolbar(floatEl, editorOfSelection);

  const place = () => {
    const sel = window.getSelection();
    if (!sel || sel.isCollapsed || !sel.rangeCount || !editorOfSelection()) {
      floatEl.hidden = true;
      return;
    }
    const rect = sel.getRangeAt(0).getBoundingClientRect();
    if (!rect.width && !rect.height) {
      floatEl.hidden = true;
      return;
    }
    floatEl.hidden = false;
    // Measured after unhiding, since a hidden element has no size to centre on.
    const { width, height } = floatEl.getBoundingClientRect();
    const edge = 8;
    // Below the selection, not above: a phone puts its own Cut/Copy/Paste bar above the
    // text you just selected, and the two landed on top of each other. The gap clears the
    // drag handles that hang under the selection on a touch screen. Above only as a
    // fallback, when there is no room underneath.
    const BELOW_GAP = 26;
    const below = rect.bottom + BELOW_GAP;
    const fitsBelow = below + height <= window.innerHeight - edge;
    floatEl.style.top = `${fitsBelow ? below : Math.max(edge, rect.top - height - edge)}px`;
    floatEl.style.left = `${Math.max(edge, Math.min(window.innerWidth - width - edge, rect.left + rect.width / 2 - width / 2))}px`;
  };

  // selectionchange fires for every caret move, so the work is deferred and collapsed
  // into one update. A timeout rather than requestAnimationFrame: rAF doesn't run at all
  // while the page is considered hidden, which would leave the bar stuck wherever it was
  // when the window lost visibility.
  let queued = false;
  const schedule = () => {
    if (queued) return;
    queued = true;
    setTimeout(() => {
      queued = false;
      place();
    }, 0);
  };
  document.addEventListener('selectionchange', schedule);
  // Keep it against the text while the page moves under it.
  window.addEventListener('scroll', schedule, true);
  window.addEventListener('resize', schedule);
}

/** The editable field containing the current selection, or null if it isn't in one. */
function editorOfSelection() {
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return null;
  let node = sel.getRangeAt(0).commonAncestorContainer;
  if (node.nodeType === Node.TEXT_NODE) node = node.parentNode;
  const editor = node.closest?.('[contenteditable="true"]');
  return editor || null;
}

/** `getEditor()` is called per click so callers whose target moves (the sheet's toolbar
 *  acts on whichever cell was last focused) can resolve it late. */
function wireRichTextToolbar(root, getEditor) {
  wireShortcutsOnce();
  floatingToolbarOnce();
  root.querySelectorAll('[data-rt]').forEach((btn) => {
    // Without this the button steals focus on press, which collapses the selection in
    // the editor before the click handler ever runs - leaving nothing to format.
    btn.addEventListener('mousedown', (e) => e.preventDefault());
    btn.addEventListener('click', () => {
      const editor = getEditor();
      if (!editor) return;
      applyRichTextCommand(btn.dataset.rt, editor);
      editor.dispatchEvent(new Event('input', { bubbles: true }));
    });
  });
}

function applyRichTextCommand(cmd, editor) {
  if (cmd === 'underline') {
    document.execCommand('underline');
    return;
  }
  const sel = window.getSelection();
  if (!sel.rangeCount || sel.isCollapsed) return;
  const range = sel.getRangeAt(0);
  if (!editor.contains(range.commonAncestorContainer)) return;

  if (cmd === 'big') {
    const span = document.createElement('span');
    span.className = 'big';
    span.appendChild(range.extractContents());
    range.insertNode(span);
    reselect(sel, span);
    return;
  }
  if (cmd === 'unbig') {
    // Selection sitting *inside* one big span (the common case - you enlarged a line,
    // then selected part of it): unwrap that whole span rather than splitting it.
    let node = range.commonAncestorContainer;
    if (node.nodeType === Node.TEXT_NODE) node = node.parentNode;
    const enclosing = node.closest?.('span.big');
    if (enclosing && editor.contains(enclosing)) {
      enclosing.replaceWith(...enclosing.childNodes);
      return;
    }
    // Otherwise the selection spans several - strip any it fully contains.
    const frag = range.extractContents();
    frag.querySelectorAll('span.big').forEach((s) => s.replaceWith(...s.childNodes));
    range.insertNode(frag);
  }
}

/** Whether a run of text is nothing but times and the punctuation that separates them,
 *  so expanding bare digits in it is unambiguous.
 *
 *  Without this the expansion reaches into ordinary text: "10 דק׳" became "10:00 דק׳"
 *  and "TEST123" became "TEST1:23" - and because it runs on blur, merely clicking into
 *  a cell and back out was enough to rewrite it and save an override. Any letter in the
 *  run means it isn't a bare time list, so leave it alone. In a formatted field this is
 *  applied per text node, so times and words can still coexist there - a line of times
 *  is expanded even when a Hebrew line right above it isn't. */
function isBareTimeList(text) {
  return /\d/.test(text) && !/\p{L}/u.test(text);
}

/** Rewrites shorthand times in place inside a contenteditable ("1220 130" ->
 *  "12:20/1:30"). Call it on blur, not while typing, or it fights the caret.
 *
 *  With no markup in the field it can work on the text wholesale, separators included.
 *  Once part of the text is underlined or resized, it only expands digits within each
 *  text node and leaves separators alone: the spaces between times may then live in
 *  different nodes than the times themselves, and rewriting across that boundary would
 *  mean rebuilding the field's HTML - which would throw away exactly the formatting the
 *  user just applied. */
function applyTimeShorthand(editorEl) {
  if (!editorEl.children.length) {
    if (!isBareTimeList(editorEl.textContent)) return;
    const normalized = normalizeTimeList(editorEl.textContent);
    if (normalized !== editorEl.textContent) editorEl.textContent = normalized;
    return;
  }
  const walker = document.createTreeWalker(editorEl, NodeFilter.SHOW_TEXT);
  const textNodes = [];
  while (walker.nextNode()) textNodes.push(walker.currentNode);
  textNodes.forEach((node) => {
    if (!isBareTimeList(node.nodeValue)) return;
    const normalized = normalizeTimeShorthand(node.nodeValue);
    if (normalized !== node.nodeValue) node.nodeValue = normalized;
  });
}

function reselect(sel, node) {
  sel.removeAllRanges();
  const r = document.createRange();
  r.selectNodeContents(node);
  sel.addRange(r);
}

// ==== ui/sheet-view.js ====
/** You choose the page split for a שבת חורף sheet yourself (as usual, covering every
 *  week). Whichever page ends up containing at least one week past the spring DST
 *  cutover (2nd Sunday of March - not the fall one near Sukkos) prints as a real שבת
 *  קיץ chart for its *entire* page - same columns, same formulas, same rule-matching
 *  as an actual קיץ sheet - even for any earlier weeks sharing that page, which just
 *  come out with blank Plag columns (same as קיץ's own weeks outside its Plag window).
 *  A Weekday chart has no such split - it's always 'weekday'. */
function pageEffectiveSeason(sheet, pageWeeks, settings) {
  if (sheet.season !== 'choref') return sheet.season;
  return pageWeeks.some((w) => inSpringDstWindow(w.date, settings)) ? 'kayitz' : 'choref';
}
function columnsAndBuilderFor(effectiveSeason) {
  if (effectiveSeason === 'weekday') return { columns: WEEKDAY_COLUMNS, buildRow: buildWeekdayRow };
  return effectiveSeason === 'kayitz' ? { columns: KAYITZ_COLUMNS, buildRow: buildKayitzRow } : { columns: CHOREF_COLUMNS, buildRow: buildChorefRow };
}

const FONT_CHOICES = ['David', 'David Libre', 'Guttman Yad', 'Frank Ruehl', 'Times New Roman', 'Arial', 'Segoe UI'];

/** Which shipped webfont stands in for each choice when the real one isn't installed.
 *
 *  A phone has none of these fonts, so without a stand-in every Hebrew column falls back
 *  to the system sans - and with a single stand-in for all of them, picking Times New
 *  Roman still got you David's Hebrew, which looks nothing like it. Times New Roman and
 *  Frank Ruehl are both traditional high-contrast Hebrew serifs, so one covers the other
 *  closely; David is a lighter semi-serif and only matches itself.
 *
 *  Arial and Segoe UI are deliberately absent: they fall back to the device's own Hebrew
 *  sans (Noto on Android, Segoe on Windows), which is already the right shape - no point
 *  downloading a font to say the same thing. */
const HEBREW_STAND_IN = {
  'Times New Roman': 'Frank Ruhl Libre',
  'Frank Ruehl': 'Frank Ruhl Libre',
  'Guttman Yad': 'Frank Ruhl Libre',
  David: 'David Libre',
  'David Libre': 'David Libre',
};

/** The full CSS stack for a chosen font: the real font first (installed on the machines
 *  these sheets are printed from), then the shipped stand-in, then a generic. */
function fontStackFor(fontFamily) {
  const standIn = HEBREW_STAND_IN[fontFamily];
  const generic = fontFamily === 'Arial' || fontFamily === 'Segoe UI' ? 'sans-serif' : 'serif';
  return `"${fontFamily}"${standIn ? `, "${standIn}"` : ''}, ${generic}`;
}

// Undo/redo history per sheet, kept in memory only (module-level, keyed by sheet id) -
// intentionally not persisted to localStorage; it lives for as long as the app tab is
// open, same as undo history in most editors.
const histories = new Map();
function getHistory(sheetId) {
  if (!histories.has(sheetId)) histories.set(sheetId, { undo: [], redo: [] });
  return histories.get(sheetId);
}
function applyOverrideValue(sheet, serial, col, value) {
  if (value === undefined) clearOverride(sheet, serial, col);
  else setOverride(sheet, serial, col, value);
}

/** The printed pages of one sheet, built and styled but not yet in the document.
 *
 *  Exported because the congregation's page shows the same chart, and a second renderer
 *  for it would be a second thing to keep in step with the formulas. Pass readOnly for
 *  that use: it is the same markup with the cell editing taken off, rather than a
 *  different rendering path that could quietly diverge.
 *
 *  Row heights still need syncPageHeights() once the pages are in the document, since
 *  nothing can be measured before then. */
function buildSheetPages(sheet, state, onChange = () => {}, { readOnly = false } = {}) {
  if (!sheet) return [];
  const settings = resolveSettings(state.settings);
  if (!sheet.style) sheet.style = { ...state.settings.sheetStyle };
  if (!sheet.columnWidths) sheet.columnWidths = {};
  const wks = sheet.weeks.map((w) => ({ ...w, date: new Date(w.date) }));
  const split = splitWeeksIntoPages(wks, sheet.pageSizes).map((pw) => ({ weeks: pw, effectiveSeason: pageEffectiveSeason(sheet, pw, settings) }));
  return split.map(({ weeks: pw, effectiveSeason }, i) => {
    const { columns, buildRow } = columnsAndBuilderFor(effectiveSeason);
    const el = renderPage(pw, i, split.length, columns, buildRow, settings, sheet, state, onChange, effectiveSeason);
    el.dataset.sheetLabel = sheetLabel(sheet);
    el.dataset.pageIndex = i;
    applyStyle(el, sheet.style); // variables only - row heights need the page in the document
    if (readOnly) el.querySelectorAll('[contenteditable]').forEach((cell) => cell.removeAttribute('contenteditable'));
    return el;
  });
}

/** Makes every row on every page the same height. Must run with the pages in the
 *  document: heights read 0 on a detached element. */
function syncPageHeights(pagesEl) {
  syncHeaderRowHeight(pagesEl);
}

function renderSheet(container, state, sheet, onChange) {
  if (!sheet.style) sheet.style = { ...state.settings.sheetStyle };
  if (!sheet.style.accentColor) sheet.style.accentColor = state.settings.sheetStyle.accentColor || DEFAULT_ACCENT_COLOR; // sheets saved before this control existed
  if (!sheet.columnWidths) sheet.columnWidths = {};
  const settings = resolveSettings(state.settings);
  const weeks = sheet.weeks.map((w) => ({ ...w, date: new Date(w.date) }));
  const pages = splitWeeksIntoPages(weeks, sheet.pageSizes).map((pageWeeks) => ({ weeks: pageWeeks, effectiveSeason: pageEffectiveSeason(sheet, pageWeeks, settings) }));
  const anyKayitzPage = pages.some((p) => p.effectiveSeason === 'kayitz');
  const isEnglish = state.settings.language === 'en';

  // The Weekday chart generated alongside this one (or, from the Weekday chart itself,
  // the Shabbos sheet it was generated alongside) - generating both saves both, but only
  // one can be open at a time, so this link is how you actually get to see the other one
  // right after generating instead of having to dig it up from Saved Sheets.
  // linkedSheetId is the exact pairing recorded at generation time; the season+year
  // match after it is the fallback for pairs generated before that was stored.
  const companion =
    sheet.season === 'weekday'
      ? state.sheets.find((s) => s.id === sheet.linkedSheetId) ||
        state.sheets.filter((s) => s.season === sheet.linkedSeason && s.hebrewYear === sheet.hebrewYear).sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0]
      : state.sheets.find((s) => s.season === 'weekday' && s.linkedSheetId === sheet.id) ||
        state.sheets
          .filter((s) => s.season === 'weekday' && s.linkedSeason === sheet.season && s.hebrewYear === sheet.hebrewYear)
          .sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];

  const hist = getHistory(sheet.id);
  container.innerHTML = `
    <div class="sheet-toolbar no-print">
      <button id="back-btn">&larr; Back</button>
      <button id="print-btn" class="btn-primary" title="Opens the print dialog, where the destination can be a printer or Save as PDF">Print / Save as PDF</button>
      <button id="undo-btn" title="Undo last cell edit" ${hist.undo.length ? '' : 'disabled'}>&#8630; Undo</button>
      <button id="redo-btn" title="Redo" ${hist.redo.length ? '' : 'disabled'}>&#8631; Redo</button>
      ${companion ? `<button id="companion-btn">${sheet.season === 'weekday' ? '→ View שבת sheet' : '→ View Weekday chart'}</button>` : ''}
      ${companion ? '<button id="side-by-side-btn" type="button" title="Show both charts beside each other, scaled down">⇄ Side by side</button>' : ''}
      <button id="fit-btn" type="button" title="Scale the chart down until a whole page fits across the screen">&#9974; Fit to screen</button>
      ${richTextToolbarHtml('In the cell you\'re editing:')}
      <span class="hint">Click a cell to edit it, then select text and use the buttons above to underline it or change its size. Rule-affected cells show a light yellow background.${
        anyKayitzPage ? ' Pages holding a week past the spring DST cutover print as a full שבת קיץ chart.' : ''
      }</span>
    </div>
    <details class="panel no-print">
      <summary>Which pages to print or save</summary>
      <div class="panel-body">
        <p class="hint">Everything is included by default. Untick a page to leave it out of the next print or PDF. Excluded pages stay on screen, dimmed, so you can still read them.</p>
        <div class="page-picker" id="page-picker"></div>
        <div class="actions"><button type="button" id="pages-all">Include all</button></div>
      </div>
    </details>
    <details class="panel no-print">
      <summary>Layout &amp; style: font, sizes, colour</summary>
      <div class="panel-body">
        <div class="style-toolbar">
          <label>Font
            <select id="style-font">${FONT_CHOICES.map((f) => `<option value="${f}" ${f === sheet.style.fontFamily ? 'selected' : ''}>${f}</option>`).join('')}</select>
          </label>
          <label>Text size
            <input id="style-size" type="range" min="6" max="18" step="0.5" value="${sheet.style.fontSizePt}">
            <span id="style-size-label">${sheet.style.fontSizePt}pt</span>
          </label>
          <label>Logo size
            <input id="style-header" type="range" min="0.6" max="1.6" step="0.1" value="${sheet.style.headerScale}">
          </label>
          <label>Page color
            <input id="style-color" type="color" value="${sheet.style.accentColor}">
          </label>
          <button id="style-reset" type="button">Reset style</button>
        </div>
      </div>
    </details>
    <div id="sheet-stack">
      <div id="pages" class="pages"></div>
    </div>
  `;
  container.querySelector('#back-btn').addEventListener('click', () => onChange({ back: true }));
  container.querySelector('#print-btn').addEventListener('click', () => window.print());
  container.querySelector('#companion-btn')?.addEventListener('click', () => onChange({ openSheetId: companion.id }));
  container.querySelector('#side-by-side-btn')?.addEventListener('click', (e) => {
    const on = container.querySelector('#sheet-stack').classList.toggle('is-side-by-side');
    e.target.classList.toggle('is-active', on);
    if (fitOn) applyFit(container, true); // the scale to fit changes when two pages share the row
  });

  // A page is a landscape letter sheet - about 1056px across - so on a phone it can only
  // ever be read a column at a time by scrolling sideways. Fitting scales it down until
  // a whole page is on screen at once: too small to edit in, but the point is seeing the
  // page. It starts on whenever the page doesn't fit, which in practice means phones.
  const fitBtn = container.querySelector('#fit-btn');
  fitBtn.addEventListener('click', () => setFit(container, !fitOn));


  // The formatting buttons act on whichever cell was last being edited. Tracked on
  // focusin rather than read from document.activeElement at click time because the
  // buttons deliberately don't take focus (see wireRichTextToolbar) - but a click
  // elsewhere on the page in between should still leave them pointing at that cell.
  let lastFocusedCell = null;
  container.addEventListener('focusin', (e) => {
    if (e.target.classList?.contains('cell')) lastFocusedCell = e.target;
  });
  wireRichTextToolbar(container, () => lastFocusedCell);
  container.querySelector('#undo-btn').addEventListener('click', () => {
    const action = hist.undo.pop();
    if (!action) return;
    applyOverrideValue(sheet, action.serial, action.col, action.before);
    hist.redo.push(action);
    onChange({ save: true }); // app.js re-renders the whole sheet view on save
  });
  container.querySelector('#redo-btn').addEventListener('click', () => {
    const action = hist.redo.pop();
    if (!action) return;
    applyOverrideValue(sheet, action.serial, action.col, action.after);
    hist.undo.push(action);
    onChange({ save: true });
  });

  // Both charts go into one container, interleaved: שבת page 1, its Weekday page 1,
  // שבת page 2, Weekday page 2… The two are already page-aligned (see alignPageSizesTo),
  // so each pair covers the same weeks - which is the order you want to print in, and
  // also what makes the side-by-side view line up pair-per-row.
  //
  // Style variables are set per *page* rather than per container, because the two sheets
  // carry their own font/size/colour and they now share a parent.
  const pagesEl = container.querySelector('#pages');
  const buildPagesFor = (sh) => buildSheetPages(sh, state, onChange);
  const primaryPages = buildPagesFor(sheet);
  const companionPages = buildPagesFor(companion);
  for (let i = 0; i < Math.max(primaryPages.length, companionPages.length); i++) {
    if (primaryPages[i]) pagesEl.appendChild(primaryPages[i]);
    if (companionPages[i]) pagesEl.appendChild(companionPages[i]);
  }

  // Both of these need the pages in the document: the picker to count them, and the row
  // sync to measure them (heights read 0 on a detached element).
  syncHeaderRowHeight(pagesEl);
  buildPagePicker(container);
  autoFit(container);


  const restyleOwnPages = () => {
    pagesEl.querySelectorAll(`.page[data-sheet-label="${sheetLabel(sheet)}"]`).forEach((el) => applyStyle(el, sheet.style));
    syncHeaderRowHeight(pagesEl);
  };

  const fontSel = container.querySelector('#style-font');
  const sizeInput = container.querySelector('#style-size');
  const sizeLabel = container.querySelector('#style-size-label');
  const headerInput = container.querySelector('#style-header');
  // Persists sheet.style as the app's "last used" style too, so the next *newly
  // generated* sheet starts from it (see generate-view.js / settings.js sheetStyle).
  const commit = () => {
    state.settings.sheetStyle = { ...sheet.style };
    onChange({ save: true });
  };
  fontSel.addEventListener('change', () => {
    sheet.style.fontFamily = fontSel.value;
    restyleOwnPages();
    commit();
  });
  sizeInput.addEventListener('input', () => {
    sheet.style.fontSizePt = Number(sizeInput.value);
    sizeLabel.textContent = sheet.style.fontSizePt + 'pt';
    restyleOwnPages();
  });
  sizeInput.addEventListener('change', commit);
  headerInput.addEventListener('input', () => {
    sheet.style.headerScale = Number(headerInput.value);
    restyleOwnPages();
  });
  headerInput.addEventListener('change', commit);
  const colorInput = container.querySelector('#style-color');
  colorInput.addEventListener('input', () => {
    sheet.style.accentColor = colorInput.value;
    restyleOwnPages();
  });
  colorInput.addEventListener('change', commit);
  container.querySelector('#style-reset').addEventListener('click', () => {
    sheet.style = { fontFamily: 'Times New Roman', fontSizePt: 10, headerScale: 1, accentColor: DEFAULT_ACCENT_COLOR };
    commit(); // app.js re-renders the whole sheet view on save
  });
}

/** Tick-list of every rendered page. Unticking marks the page .page-excluded, which
 *  print.css drops from the output - the page stays visible on screen (dimmed) so you
 *  can still see what you left out. */
function buildPagePicker(container) {
  const picker = container.querySelector('#page-picker');
  if (!picker) return;
  const pages = [...container.querySelectorAll('#pages > .page')];
  picker.innerHTML = pages
    .map((p, i) => `<label class="page-chip"><input type="checkbox" checked data-i="${i}"> <bdi>${esc(p.dataset.sheetLabel)}</bdi> · page ${Number(p.dataset.pageIndex) + 1}</label>`)
    .join('');
  picker.querySelectorAll('input').forEach((cb) => {
    cb.addEventListener('change', () => pages[Number(cb.dataset.i)].classList.toggle('page-excluded', !cb.checked));
  });
  container.querySelector('#pages-all').addEventListener('click', () => {
    picker.querySelectorAll('input').forEach((cb) => {
      cb.checked = true;
      pages[Number(cb.dataset.i)].classList.remove('page-excluded');
    });
  });
}

const sheetLabel = (sh) => (sh.season === 'kayitz' ? 'שבת קיץ' : sh.season === 'choref' ? 'שבת חורף' : 'Weekday');


// --- Fit to screen -----------------------------------------------------------------
// Module-level, not per-render: the sheet view re-renders on every saved cell edit, and
// the view shouldn't snap back to full size underneath you each time.
let fitOn = false;
let fitChosenByUser = false;
let fitResizeHandler = null;

/** Scales #pages down until its widest row fits across the screen. Uses `zoom` rather
 *  than `transform: scale`, which only paints smaller and leaves the original footprint
 *  behind - the same reason side-by-side uses it. */
function applyFit(container, on) {
  const pagesEl = container.querySelector('#pages');
  if (!pagesEl) return;
  pagesEl.style.zoom = ''; // always measure unscaled
  if (!on) return;
  const avail = pagesEl.clientWidth;
  const content = pagesEl.scrollWidth;
  if (!avail || content <= avail) return;
  pagesEl.style.zoom = Math.max(0.15, avail / content);
}

function setFit(container, on) {
  fitOn = on;
  fitChosenByUser = true;
  const btn = container.querySelector('#fit-btn');
  btn?.classList.toggle('is-active', on);
  applyFit(container, on);
}

/** Turns fitting on by itself the first time a sheet is opened on a screen too narrow to
 *  show a page - otherwise a phone opens onto a wall of one column. Never overrides a
 *  choice already made with the button. */
function autoFit(container) {
  const pagesEl = container.querySelector('#pages');
  const decide = () => {
    if (!fitChosenByUser) {
      pagesEl.style.zoom = ''; // measure unscaled before asking whether it fits
      fitOn = pagesEl.scrollWidth > pagesEl.clientWidth;
      container.querySelector('#fit-btn')?.classList.toggle('is-active', fitOn);
    }
    applyFit(container, fitOn);
  };
  decide();

  // Rotating a phone changes what fits. One listener, replaced each render so it always
  // points at the container currently on screen.
  if (fitResizeHandler) window.removeEventListener('resize', fitResizeHandler);
  fitResizeHandler = () => {
    if (document.body.contains(pagesEl)) decide();
  };
  window.addEventListener('resize', fitResizeHandler);
}

/** Black or white, whichever the header row can actually be read in against the page
 *  colour. White on the dark grey the chart shipped with, black once the colour is light:
 *  without this, picking a light Page color left the header white on near-white and the
 *  column names simply vanished. Rec. 601 luma, which is the usual rule of thumb for
 *  this, with the threshold at the middle of the range. */
function headerInkFor(color) {
  const hex = String(color || '').replace('#', '');
  if (hex.length !== 6) return '#fff';
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
  return 0.299 * r + 0.587 * g + 0.114 * b > 140 ? '#1a1a1a' : '#fff';
}

function applyStyle(target, style) {
  target.style.setProperty('--sheet-font-family', fontStackFor(style.fontFamily));
  target.style.setProperty('--sheet-font-size', style.fontSizePt + 'pt');
  target.style.setProperty('--sheet-header-scale', style.headerScale);
  target.style.setProperty('--sheet-accent', style.accentColor);
  target.style.setProperty('--sheet-head-ink', headerInkFor(style.accentColor));
}

/** Makes every row in a table - header included - exactly the same height.
 *
 *  Left alone, the header always comes out shorter: the table stretches to fill the page
 *  (`.page` is a flex column, `table { flex: 1 }`), and the browser hands out that extra
 *  height in proportion to each row's *natural* content height, which for the header is
 *  a single short line. Simply pinning the header to a measured data-row height doesn't
 *  settle it either - the total is fixed, so growing the header shrinks the data rows it
 *  was just matched against.
 *
 *  So instead of measuring one against the other, this splits the table's total height
 *  evenly across all its rows, which is stable in one pass. The floor guards the case
 *  where there are enough rows that an even share would be tighter than the content
 *  actually needs - better to overflow the even split than to clip real text. Re-run on
 *  every applyStyle(), since the font/size controls invalidate the measurements. */
function syncHeaderRowHeight(pagesEl) {
  pagesEl.querySelectorAll('table').forEach((table) => {
    const headRow = table.querySelector('thead tr');
    const bodyRows = [...table.querySelectorAll('tbody tr')];
    if (!headRow || !bodyRows.length) return;
    const allRows = [headRow, ...bodyRows];
    allRows.forEach((r) => (r.style.height = '')); // drop previous pins so measurements are fresh

    // Every row gets an equal share of the table's height. Measuring the tallest row and
    // pinning to that instead doesn't work here: on the Weekday chart the merged שחרית
    // cell spans every row, so its height is what the browser divides between them, and
    // it hands a row with two lines of parsha a bigger slice. That slice is a *result* of
    // the distribution, not the row's own requirement - pinning to it inflated the whole
    // table past the 8.5in page. The even share is the real target; the row only stays
    // taller if its own content genuinely needs more, which the tightened parsha
    // line-height now avoids.
    // The header is never shorter than a body row, so there are two cases and the table
    // has to end up exactly its own height either way:
    //   header fits in an equal share  -> every row (header included) takes that share
    //   header needs more than a share -> it keeps its height, the rest split what's left
    // Using one formula for both overflowed the page: the first case pushed a tall header
    // down to a share it couldn't fit in, the second handed a short header a share bigger
    // than it needed.
    const tableHeight = table.getBoundingClientRect().height;
    const headNatural = headRow.getBoundingClientRect().height;
    const evenShare = tableHeight / allRows.length;
    const target = headNatural <= evenShare ? evenShare : (tableHeight - headNatural) / bodyRows.length;
    bodyRows.forEach((r) => (r.style.height = target + 'px'));
    // The header never comes out shorter than a body row, and keeps its own greater
    // height where its text needs it.
    headRow.style.height = Math.max(target, headNatural) + 'px';
  });
}


// Right-to-left reading order after the parsha column: the workbook's own B..L/B..I
// order is "latest event of the week first" (Motzei Shabbos Maariv is column B) -
// reversed here so reading right-to-left after the parsha actually follows the week
// chronologically (Friday's Mincha/candle-lighting first, Motzei Shabbos Maariv last).
function rtlOrdered(columns) {
  return [...columns].reverse();
}

function renderPage(pageWeeks, pageIndex, totalPages, columns, buildRow, settings, sheet, state, onChange, effectiveSeason) {
  const page = document.createElement('div');
  page.className = 'page';
  const isEnglish = state.settings.language === 'en';
  const dir = isEnglish ? 'ltr' : 'rtl';
  const footerNote = sheet.season === 'weekday' ? state.settings.weekdayFooterNote : state.settings.footerNote;
  const orderedColumns = isEnglish ? columns : rtlOrdered(columns);
  const isWeekday = effectiveSeason === 'weekday';

  const colDefs = isEnglish ? [...orderedColumns.map((c) => c.key), 'parsha'] : ['parsha', ...orderedColumns.map((c) => c.key)];
  const colgroup = '<colgroup>' + colDefs.map((key) => `<col data-colkey="${key}"${sheet.columnWidths[key] ? ` style="width:${sheet.columnWidths[key]}px"` : ''}>`).join('') + '</colgroup>';

  const theadCols = orderedColumns.map((c) => `<th${hebrewLang(c.header)}>${markHeaderRoom(nl2br(c.header))}</th>`).join('');
  // The Weekday chart titles its parsha column, matching the printed board; the Shabbos
  // charts leave that corner blank. (th is white-space: pre-line, so the \n is a break.)
  const parshaHeader = isWeekday ? 'Weekday\nזמנים' : isEnglish ? 'Parsha' : ' ';

  // On the Weekday chart, שחרית ("1 schedule for all days" - see settings-view.js) is
  // one shul-wide value straight from Settings, not per-week: instead of repeating it
  // in every row (which would make a multi-line schedule absurdly tall over many
  // weeks), it prints once as a single cell spanning the whole page's rows, matching
  // how it looks in the original printed chart. It's sourced live from Settings with
  // no per-cell override - change it in Settings and it updates everywhere at once.

  const rows = pageWeeks
    .map((week, rowIndex) => {
      // The Weekday chart's מנחה/מעריב are computed now (sheets/weekday.js), but the
      // Tisha B'Av note and the Rules engine still don't reach it: both are keyed to the
      // קיץ/חורף columns, and a rule's column key is season-qualified ("kayitz:C"), so
      // there is nothing for a Weekday column to match against.
      const computed = buildRow(week, settings);
      const appliedColumns = new Set();
      // effectiveSeason (not sheet.season) - a חורף page that prints as קיץ (see
      // pageEffectiveSeason above) should also match "kayitz:"-qualified rules, same
      // as a real קיץ sheet would for these weeks.
      const ruled = isWeekday ? computed : applyRules(computed, withHebrewDate(week, settings), state.rules, effectiveSeason, appliedColumns);
      const { row, overriddenKeys } = mergeRow(ruled, sheet, week.serial);
      const cellHtml = (c) => {
        // שחרית on the Weekday chart: a plain rowspan cell, only emitted on the page's
        // first row (browsers naturally leave that column slot filled on later rows).
        // Stored as real HTML straight from Settings' rich-text editor (see
        // settings-view.js), so it prints out as-is instead of through nl2br/esc.
        if (isWeekday && c.key === 'E') {
          if (rowIndex !== 0) return '';
          // Both schedules on the printed chart, rebuilt from the two fields with the
          // heading between them, so the wall chart looks exactly as it always has.
          const special = state.settings.weekdayShacharisSpecial;
          const html =
            (state.settings.weekdayShacharis || esc('(set שחרית schedule in Settings)')) +
            (special ? `

<u>${esc(SPECIAL_SHACHARIS_HEADING)}</u>
${special}` : '');
          return `<td class="shacharis-merged" rowspan="${pageWeeks.length}">${html}</td>`;
        }
        // מנחה/מעריב on the Weekday chart: computed from the shul's standing weekday
        // schedule (see sheets/weekday.js) and still editable on top, so typing over a
        // week stores an override the same as any other column. An override already
        // holds real HTML; a computed value is still sentinel/newline text and needs
        // nl2br, exactly like the Shabbos columns below.
        if (isWeekday && (c.key === 'B' || c.key === 'C')) {
          const html = overriddenKeys.has(c.key) ? row[c.key] ?? '' : nl2br(row[c.key] ?? '');
          return `<td><div class="cell" contenteditable="true" data-serial="${week.serial}" data-col="${c.key}" data-season="${effectiveSeason}">${html}</div></td>`;
        }
        const flagged = appliedColumns.has(c.key) && !overriddenKeys.has(c.key) ? 'ruled' : overriddenKeys.has(c.key) ? 'overridden' : '';
        // Overridden cells already hold real HTML (captured from the editable div,
        // possibly with manual <u> underlining); computed cells still need nl2br().
        const html = overriddenKeys.has(c.key) ? row[c.key] ?? '' : nl2br(row[c.key] ?? '');
        // data-season records which season this *page* rendered as, so a later edit
        // (see the blur handler below) recomputes its "did this really change?"
        // baseline the same way, without having to re-derive the page split.
        return `<td class="${flagged}"><div class="cell" contenteditable="true"${hebrewLang(html)} data-serial="${week.serial}" data-col="${c.key}" data-season="${effectiveSeason}">${html}</div></td>`;
      };
      const cells = orderedColumns.map(cellHtml).join('');
      // A week whose Shabbos is Yom Tov has no parsha, so it carries the Yom Tov's own
      // name (see weeks.js). Printed as it stands, "סוכות" reads as though this row held
      // the times for Yom Tov; it holds the ordinary weekdays around it, so it is named
      // for the week: "שבוע של סוכות". A parsha is left exactly as it is.
      const parshaCell = weekOfLabel(week.parsha, isEnglish) + (week.specialParsha ? '\n' + week.specialParsha : '');
      // An explicit width from the column-width panel has to beat the CSS min-width
      // floor on .parsha-cell (see app.css) - otherwise setting a narrower one there
      // would silently do nothing. Inline, so it outranks the stylesheet.
      const parshaWidth = sheet.columnWidths.parsha ? ` style="min-width:${sheet.columnWidths.parsha}px"` : '';
      const parshaTd = `<td class="parsha-cell"${parshaWidth}${hebrewLang(parshaCell)}>${nl2br(parshaCell)}</td>`;
      return `<tr>${isEnglish ? cells + parshaTd : parshaTd + cells}</tr>`;
    })
    .join('');
  const theadRow = isEnglish ? theadCols + `<th>${parshaHeader}</th>` : `<th>${parshaHeader}</th>` + theadCols;

  page.innerHTML = `
    <div class="page-header">
      <div class="header-row">
        <img class="header-icon" src="${state.settings.headerIconImage || 'assets/logo-building-icon.png'}" alt="">
        <div class="header-center">
          <img class="header-logo" src="assets/logo-text.png" alt="${esc(state.settings.shulName)}"${hebrewLang(state.settings.shulName)}>
          ${state.settings.headerSubtitle ? `<div class="header-subtitle"${hebrewLang(state.settings.headerSubtitle)}>${esc(state.settings.headerSubtitle)}</div>` : ''}
        </div>
        <div class="header-rabbi"${hebrewLang(state.settings.headerRabbiLine)}>${nl2br(esc(state.settings.headerRabbiLine))}</div>
      </div>
    </div>
    <table dir="${dir}" class="${isWeekday ? 'weekday-table' : ''}">
      ${colgroup}
      <thead><tr>${theadRow}</tr></thead>
      <tbody>${rows}</tbody>
    </table>
    <div class="page-footer">
      <span class="footer-line"></span>
      <div class="footer-text">
        ${footerNote ? nl2br(esc(footerNote)) + '<br>' : ''}
        <span class="footer-address">${esc(state.settings.footerAddress)}</span>
      </div>
      <span class="footer-line"></span>
    </div>
  `;

  /** What this cell would hold with no manual override - what an edit is diffed against
   *  to decide whether it's a real change worth storing. */
  const baselineHtmlFor = (cellEl) => {
    const col = cellEl.dataset.col;
    const weekSeason = cellEl.dataset.season;
    const week = sheet.weeks.find((w) => w.serial === Number(cellEl.dataset.serial));
    const settingsResolved = resolveSettings(state.settings);
    const builtRow = splitBuild(weekSeason)({ ...week, date: new Date(week.date) }, settingsResolved);
    const computed = builtRow;
    const ruled = weekSeason === 'weekday' ? computed : applyRules(computed, withHebrewDate({ ...week, date: new Date(week.date) }, settingsResolved), state.rules, weekSeason);
    const raw = ruled[col] ?? '';
    // Every column, Weekday included, is built as plain text with underline sentinels
    // that nl2br has to mark up first - or the comparison would see markup-vs-none and
    // store a bogus override on a cell nobody actually edited.
    return normalizeRichText(nl2br(raw));
  };

  const commitCell = (cellEl) => {
    const serial = Number(cellEl.dataset.serial);
    const col = cellEl.dataset.col;
    const newHtml = normalizeRichText(cellEl.innerHTML);
    const before = getOverride(sheet, serial, col); // undefined = "no override"
    const after = newHtml === baselineHtmlFor(cellEl) ? undefined : newHtml;
    if (before === after) return; // no real change (e.g. just clicked in and out)
    applyOverrideValue(sheet, serial, col, after);
    const hist = getHistory(sheet.id);
    hist.undo.push({ serial, col, before, after });
    hist.redo = []; // a fresh edit invalidates any redo history
    onChange({ save: true });
  };

  page.querySelectorAll('.cell').forEach((cellEl) => {
    cellEl.addEventListener('keydown', (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'u') {
        e.preventDefault();
        document.execCommand('underline');
      }
    });
    cellEl.addEventListener('blur', () => {
      applyTimeShorthand(cellEl); // "1220 130" -> "12:20/1:30"
      commitCell(cellEl);
    });
  });

  return page;
}

/** Attaches the week's Hebrew date so rules can match on it (see rules.js). Computed
 *  here rather than stored on the sheet, so it works for sheets saved before hebrewDate
 *  conditions existed. */
function withHebrewDate(week, settings) {
  return { ...week, hebrew: hebrewDateExtended(week.serial, settings.useGregorianBefore1582) };
}

function splitBuild(season) {
  if (season === 'weekday') return buildWeekdayRow;
  return season === 'kayitz' ? buildKayitzRow : buildChorefRow;
}

// Converts UL_START/UL_END sentinels (see format.js) into real <u> elements *after*
// HTML-escaping the rest of the text, and \n into <br>. Plain <u> rather than a styled
// <span> specifically so the underline toolbar (and Ctrl/Cmd+U) can *remove* it: those
// go through execCommand, which only recognizes its own native markup and silently
// no-ops on a class-based underline it doesn't know how to undo.
function nl2br(str) {
  // underlineTime writes its value as "<u> 6:42</u>". The space was meant as a lead-in
  // that would not show on a centred chart cell, and it does show: a cell holding several
  // times leaves 13.7px in front of an underlined one against 10.36px in front of a plain
  // one, and the rule itself starts a space before its own first digit. Dropped, so every
  // gap in a cell is the separator's width and nothing else. The character is a
  // non-breaking space rather than the plain one it looks like in the source, so it is
  // matched as whitespace rather than written out.
  const trimmed = esc(str).replace(new RegExp(UL_START + '\\s+', 'g'), UL_START);
  const escaped = trimmed.split(UL_START).join('<u>').split(UL_END).join('</u>');
  return escaped.replace(/\n/g, '<br>');
}
function esc(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ==== ui/chart-view.js ====
// Reading the wall chart on a screen: one stretch of it at a time, with Previous, Today
// and Next above it.
//
// A season chart runs to three pages and there can be two seasons in play at once.
// Showing all of them at once means finding the right one before reading a single time,
// so this opens on the stretch covering now and pages from there, exactly as the week
// view does. It is the same rendering the printed chart uses (buildSheetPages), read-only
// - a second renderer would be a second thing to keep in step with the formulas.
//
// Shared between the congregation's site and the admin's This week screen, so the two
// cannot drift apart.









/** Every stretch of chart there is to look at, in date order: one entry per page of each
 *  season, carrying the שבת page and the Weekday page that go together.
 *
 *  The page breaks of the two charts fall on the same dates (alignPageSizesTo at
 *  generation time), so one index picks the matching pair. Seasons are ordered by the
 *  week they start on, so paging forward runs קיץ into חורף the way the year does. */
function chartSpreads(state) {
  const spreads = [];
  for (const sheet of state.sheets.filter((s) => s.season !== 'weekday')) {
    const weekday = state.sheets.find((s) => s.season === 'weekday' && s.linkedSheetId === sheet.id) || null;
    splitWeeksIntoPages(sheet.weeks, sheet.pageSizes).forEach((weeks, index) => {
      if (!weeks.length) return;
      spreads.push({ sheet, weekday, index, serials: weeks.map((w) => w.serial) });
    });
  }
  return spreads.sort((a, b) => Math.min(...a.serials) - Math.min(...b.serials));
}

/** The spread covering now: the one holding the same week the week view opens on, so the
 *  two never disagree about which Shabbos is "this" one. */
function spreadIndexForNow(spreads, state, settings) {
  if (!spreads.length) return 0;
  const target = currentSerial(spreads.flatMap((s) => s.serials), settings, (s) => weekEndsMins(s, state, settings));
  const found = spreads.findIndex((s) => s.serials.includes(target));
  return found === -1 ? 0 : found;
}

/** What a spread covers, for the line above the buttons: the first and last Shabbos on
 *  it, in both calendars, the way the week view names its week.
 *
 *  The Hebrew pair goes on its own line in its own direction. Run into the English one it
 *  would be reordered against it, and inside a right-to-left line the earlier date sits
 *  on the right, which is the order it is read in. */
function spreadLabel(spread) {
  const ends = [Math.min(...spread.serials), Math.max(...spread.serials)];
  const english = ends.map((serial) =>
    new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', month: 'long', day: 'numeric', year: 'numeric' }).format(dateFromSerial(serial))
  );
  const hebrew = ends.map((serial) => jewishDateString(serial, false));
  return {
    english: english[0] === english[1] ? english[0] : `${english[0]} to ${english[1]}`,
    hebrew: hebrew[0] === hebrew[1] ? hebrew[0] : `${hebrew[0]} – ${hebrew[1]}`,
  };
}

/** A chart page is a fixed 11in wide, so on anything narrower it is scaled down rather
 *  than scrolled sideways: the whole page should be visible at once. Print resets it
 *  (see print.css), since paper has no such problem.
 *
 *  transform rather than zoom, and this is the one place in the app where that is the
 *  right way round. zoom will not paint a border thinner than a pixel however far it
 *  scales, so at 0.34 on a phone the grid's 1px rules stayed a full pixel wide while the
 *  cells around them shrank to a third, and the chart came out looking ruled in black.
 *  Fading the colour was tried first and reverted: it cannot reach the width, so it only
 *  turned a heavy line into a pale one of the same thickness, which reads worse. A
 *  transform scales the rule with everything else. Measured on a phone at this scale,
 *  reading the painted pixels: zoom draws 3 device pixels at contrast 91, transform draws
 *  2 at contrast 47, and the second is 94 units of ink against the 93 the design asks for.
 *
 *  What zoom gave for free was the layout: it shrinks the box as well as the paint, while
 *  a transform leaves the original footprint behind and would reserve 11in of width and
 *  the full height on a phone. So the wrapper is sized here instead, to what the transform
 *  actually covers, and clipped. Hence .pages-fit existing at all.
 *
 *  Measured once, this fits whatever the page happened to be at that instant. The Hebrew
 *  serifs are loaded with font-display: swap, so on a slow connection the first paint is
 *  in a fallback and the real font arrives afterwards at a different width - the fit was
 *  then a frame too early and stayed wrong. Re-fit when the fonts land, and once more on
 *  the next frame for anything else that settles late. Every pass starts by clearing what
 *  the last one set, so re-running it is not cumulative. */
function fitChartToWindow(pagesEl) {
  const fit = pagesEl.parentElement;
  const apply = () => {
    if (!document.body.contains(pagesEl)) return;
    pagesEl.style.transform = '';
    pagesEl.style.width = '';
    if (fit) { fit.style.height = ''; fit.style.overflow = ''; }
    const available = fit ? fit.clientWidth : pagesEl.clientWidth;
    const content = pagesEl.scrollWidth;
    if (!available || content <= available) return;
    const scale = available / content;
    // Held at its natural width, or the transform would scale a box that had already
    // shrunk to the window and the page would come out at the square of the scale.
    pagesEl.style.width = `${content}px`;
    pagesEl.style.transformOrigin = 'top left';
    pagesEl.style.transform = `scale(${scale.toFixed(4)})`;
    if (fit) {
      fit.style.height = `${Math.ceil(pagesEl.scrollHeight * scale)}px`;
      fit.style.overflow = 'hidden';
    }
  };
  apply();
  requestAnimationFrame(apply);
  document.fonts?.ready?.then(apply);
  window.addEventListener('resize', apply);
}

/** @param {object} opts
 *    - empty: what to say when there is no chart to show at all
 *    - swipe: false to leave the gesture off, for an embed sitting inside something that
 *      already swipes - two handlers on nested elements would both fire and the page
 *      would move twice at once.
 *    - confine: hold this to the one chart covering now, which is what the congregation's
 *      site asks for. A chart is a season's worth of weeks and the sheet on the wall is
 *      one of them; paging off it to a chart from two months ago is not what that page is
 *      for. There is exactly one chart to look at, so rather than leave Previous and Next
 *      sitting there permanently dead, the row goes: nothing on the screen is offering
 *      something it cannot do. Three taps on the chart itself opens it (navUnlocked). */
function renderChartBrowser(container, state, opts = {}) {
  const { empty = 'Nothing has been published yet.', swipe = true, confine = false } = opts;
  const spreads = chartSpreads(state);
  // Settings for the same reason the week view needs them: which Shabbos is "this" one
  // turns over 72 minutes after שקיעה, and that is not a question a date alone can answer.
  const settings = resolveSettings(state.settings);
  let at = spreadIndexForNow(spreads, state, settings);

  const draw = () => {
    // Asked every draw rather than once, so the redraw that follows the taps comes out
    // with the navigation on it.
    const held = confine && !navUnlocked();
    const spread = spreads[at];
    if (!spread) {
      container.innerHTML = `<p class="hint">${empty}</p>`;
      return;
    }
    const label = spreadLabel(spread);
    container.innerHTML = `
      <div class="week-nav no-print">
        <div class="week-nav-when">
          ${chartEsc(label.english)}
          <bdi class="week-nav-hebrew" lang="he">${chartEsc(label.hebrew)}</bdi>
        </div>
        ${held ? '' : `<div class="week-nav-row">
          <button type="button" class="chart-prev" ${at <= 0 ? 'disabled' : ''}>
            <span aria-hidden="true">&larr;</span><span class="week-nav-word">Previous</span>
          </button>
          <button type="button" class="chart-today">Today</button>
          <button type="button" class="chart-next" ${at >= spreads.length - 1 ? 'disabled' : ''}>
            <span class="week-nav-word">Next</span><span aria-hidden="true">&rarr;</span>
          </button>
        </div>`}
        <div class="week-nav-row week-nav-print-one">${printButtonHtml()}${pdfButtonHtml()}</div>
      </div>
      <div class="pages-fit"><div class="pages"></div></div>`;
    const pagesEl = container.querySelector('.pages');
    const shabbos = buildSheetPages(spread.sheet, state, () => {}, { readOnly: true });
    const chol = buildSheetPages(spread.weekday, state, () => {}, { readOnly: true });
    for (const page of [shabbos[spread.index], chol[spread.index]]) if (page) pagesEl.appendChild(page);
    syncPageHeights(pagesEl);
    fitChartToWindow(pagesEl);

    const go = (next) => {
      if (next < 0 || next >= spreads.length) return;
      at = next;
      draw();
    };
    wirePrintButton(container);
    // The container is rebuilt on every Previous/Next, so the pages are looked up when the
    // button is pressed rather than captured here. The file is named for the stretch it
    // covers, since these get saved and mailed on and "zmanim.pdf" twice over is no help.
    wirePdfButton(container, {
      host: () => container.querySelector('.pages'),
      name: () => pdfName(label.english),
      sheet: '.page',
      orientation: 'landscape',
      size: [11, 8.5],
    });
    container.querySelector('.chart-prev')?.addEventListener('click', () => go(at - 1));
    container.querySelector('.chart-next')?.addEventListener('click', () => go(at + 1));
    container.querySelector('.chart-today')?.addEventListener('click', () => go(spreadIndexForNow(spreads, state, settings)));
    // Swiping is the same journey as the buttons, so it goes with them.
    if (swipe && !held) wireSwipe(container, () => go(at - 1), () => go(at + 1));
    // Three taps on the chart itself lets the rest of the season out. On the pages rather
    // than the whole screen, so the buttons above are not part of the gesture, and the
    // redraw is what puts the navigation on the page.
    if (held) {
      wireSecretTaps(pagesEl, () => {
        unlockNav();
        draw();
      });
    }
  };
  draw();
}

/** A filename from the spread's own dates: "Zmanim July 25 2026 to September 19 2026.pdf".
 *  Everything a filesystem or a mail client might object to comes out, which on a date
 *  string is the commas. */
function pdfName(english) {
  const plain = String(english).replace(/[^A-Za-z0-9 ]+/g, '').replace(/\s+/g, ' ').trim();
  return `Zmanim ${plain}.pdf`;
}

function chartEsc(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// ==== sheets/weeks.js ====
// Season-boundary + week-list logic: auto-computes which Shabbosim belong on a
// Kayitz (summer) or Choref (winter) sheet for a given Hebrew year, mirroring the
// workbook's own P5 formula (SEQUENCE + FILTER on HAS_PARSHA<>"") but without
// requiring a manually-entered start date or week count.



const MAX_WEEKS = 60; // safety cap, well above any real season's length

/** Season(hebrewYear) date-range boundaries - Kayitz(Y): Pesach(Y) -> Sukkos(Y+1);
 *  Choref(Y): Sukkos(Y) -> Pesach(Y), both within AM year Y. Factored out of
 *  computeSeasonWeeks so the "which year is next" helpers below can use the same
 *  boundaries without needing a parsha table. */
function seasonStartSerial(season, hebrewYear) {
  return season === 'kayitz' ? dateFromHebrew(15, 1, hebrewYear) : dateFromHebrew(15, 7, hebrewYear);
}
function seasonEndSerial(season, hebrewYear) {
  return season === 'kayitz' ? dateFromHebrew(15, 7, hebrewYear + 1) : dateFromHebrew(15, 1, hebrewYear);
}

/**
 * @param {'kayitz'|'choref'} season
 * @param {number} hebrewYear AM year anchoring the season (see README for the exact
 *   convention: Kayitz(Y) runs Pesach(Y) -> Sukkos(Y+1); Choref(Y) runs Sukkos(Y) -> Pesach(Y), both within AM year Y)
 * @param {object} settings
 * @param {object} tables {parshaChutz, parshaEY, parshaNames}
 * @returns {{startSerial:number, endSerial:number, weeks: Array<{serial:number,date:Date,parsha:string,specialParsha:string}>}}
 */
function computeSeasonWeeks(season, hebrewYear, settings, tables) {
  const startSerial = seasonStartSerial(season, hebrewYear);
  const endSerial = seasonEndSerial(season, hebrewYear);

  let d = Math.ceil(startSerial);
  while (excelWeekday(d) !== 7) d++;

  const weeks = [];
  let guard = 0;
  while (d <= endSerial && guard < MAX_WEEKS) {
    const parsha = hasParsha(d, settings, tables);
    if (parsha) {
      weeks.push({ serial: d, date: dateFromSerial(d), parsha, specialParsha: hasSpecialParsha(d, settings) });
    }
    d += 7;
    guard++;
  }
  return { startSerial, endSerial, weeks };
}

function isCholHamoedAnchor(day, settings, specialDaysTable) {
  return /Chol Hamoed|חול המועד|Hoshana Rabbah|הושענה רבה/.test(hasYomTov(day, settings, specialDaysTable));
}

function anyRegularDay(fromSerial, toSerial, settings, specialDaysTable) {
  for (let day = fromSerial; day <= toSerial; day++) {
    if (!isYomTovOrCholHamoed(day, settings, specialDaysTable)) return true;
  }
  return false;
}

/** "Chol Hamoed Pesach" / "חול המועד סוכות" / "Hoshana Rabbah" -> the plain holiday
 *  name ("Pesach" / "סוכות" / "סוכות") - see the Chol Hamoed row below, which reuses
 *  whatever this Shabbos's own hasYomTov() name is but without the "Chol Hamoed"/
 *  "Hoshana Rabbah" framing, since the row is standing in for the holiday as a whole. */
function holidayNameFor(day, settings, specialDaysTable) {
  const name = hasYomTov(day, settings, specialDaysTable);
  if (/^(Hoshana Rabbah|הושענה רבה)$/.test(name)) return /[֐-׿]/.test(name) ? 'סוכות' : 'Succos';
  return name.replace(/^(Chol Hamoed |חול המועד )/, '');
}

/** Week list for a Weekday chart covering the same season date range as
 *  computeSeasonWeeks, but with a different inclusion rule: a week is included as long
 *  as at least one of its Sun-Fri days (the days a Weekday chart actually schedules) is
 *  a normal day - not Yom Tov, not Chol Hamoed. That's a superset of the Shabbos
 *  chart's own week list: a week whose Shabbos falls on Yom Tov (and so has no parsha,
 *  excluded from computeSeasonWeeks) can still need a Weekday-chart row if, say, only
 *  Thursday and Friday of that week are Yom Tov and the rest are regular days.
 *  Each week is still anchored to its Shabbos `serial` (Saturday) for consistency with
 *  the Shabbos weeks list; `parsha` falls back to that Shabbos's own Yom Tov name (e.g.
 *  "ראש השנה") when there's no regular parsha to label the row with.
 *
 *  Season boundaries (Pesach/Sukkos) essentially never line up with the fixed 7-day
 *  Saturday spacing this loop walks in, which leaves a "leftover" stretch of up to 6
 *  regular days between the last Saturday-anchored week and the boundary itself (e.g.
 *  the days between שבת הגדול and ליל פסח) - see the trailing-gap check after the main
 *  loop, which folds that stretch onto *this* (the outgoing/earlier) season as one more
 *  row, per "a week that falls between two charts belongs on the earlier one".
 *
 *  A Saturday that lands ON Chol Hamoed/Hoshana Rabbah (e.g. Shabbos Chol Hamoed Pesach)
 *  is excluded from becoming its own row in the *incoming* season's own loop above (its
 *  backward window would otherwise mix genuine pre-Yom-Tov regular days, already
 *  claimed by the outgoing chart's trailing row, together with actual Chol Hamoed days)
 *  - but it isn't dropped: the trailing-Chol-Hamoed check right after also folds it onto
 *  the *outgoing* chart as one more row, labeled with the holiday's plain name (Pesach's
 *  own Chol Hamoed row lands on the חורף chart; Sukkos's on the קיץ chart). */
function computeWeekdayWeeks(season, hebrewYear, settings, tables) {
  const startSerial = seasonStartSerial(season, hebrewYear);
  const endSerial = seasonEndSerial(season, hebrewYear);

  let d = Math.ceil(startSerial);
  while (excelWeekday(d) !== 7) d++;

  const weeks = [];
  let guard = 0;
  while (d <= endSerial && guard < MAX_WEEKS) {
    // d === startSerial: the season's own start boundary landed exactly on Shabbos
    // (e.g. Sukkos falling on a Saturday) - its backward-attached weekdays are still
    // within the *outgoing* season's territory, already covered by its own trailing-gap
    // row below. Without this, both seasons would independently print an identical row.
    const isOwnStartBoundary = d === startSerial;
    if (!isOwnStartBoundary && !isCholHamoedAnchor(d, settings, tables.specialDays) && anyRegularDay(d - 6, d - 1, settings, tables.specialDays)) {
      const parsha = hasParsha(d, settings, tables) || hasYomTov(d, settings, tables.specialDays);
      weeks.push({ serial: d, date: dateFromSerial(d), parsha, specialParsha: hasSpecialParsha(d, settings) });
    }
    d += 7;
    guard++;
  }

  // Trailing gap: the regular days (if any) between the last Saturday-anchored week
  // above and the season's own end boundary - see the function comment. Anchored at
  // endSerial itself (not a real Shabbos, just a stand-in date/key for this row) and
  // labeled with whatever Yom Tov starts there, same fallback as any other
  // Yom-Tov-only row above. When the boundary itself was exactly Shabbos, the main loop
  // already picked it up directly and this gap comes out empty - no double-counting.
  const gapStart = d - 7 + 1;
  const gapEnd = endSerial - 1;
  if (gapStart <= gapEnd && anyRegularDay(gapStart, gapEnd, settings, tables.specialDays)) {
    const parsha = hasParsha(endSerial, settings, tables) || hasYomTov(endSerial, settings, tables.specialDays);
    weeks.push({ serial: endSerial, date: dateFromSerial(endSerial), parsha, specialParsha: hasSpecialParsha(endSerial, settings) });
  }

  // `d` is now the first Saturday *after* the boundary (Saturdays fall on the same
  // fixed 7-day cadence no matter which season's math found them, so this is exactly
  // the same date the incoming season's own loop would land on as its own first
  // candidate) - see the function comment for why a Chol-Hamoed/Hoshana-Rabbah Shabbos
  // there becomes a row here instead of there. It's folded into the trailing-gap row
  // above rather than added separately whenever that row already carries the same
  // holiday's name: the two stretches are the run-up to, and the middle of, one single
  // Yom Tov, so the chart should carry one row for it, not a pair of identical ones.
  const cholHamoedName = isCholHamoedAnchor(d, settings, tables.specialDays) ? holidayNameFor(d, settings, tables.specialDays) : '';
  if (cholHamoedName && weeks[weeks.length - 1]?.parsha !== cholHamoedName) {
    weeks.push({ serial: d, date: dateFromSerial(d), parsha: cholHamoedName, specialParsha: '' });
  }

  return { startSerial, endSerial, weeks };
}

/** Where a שבת חורף season's weeks cross the *spring* DST cutover (2nd Sunday of
 *  March - not the fall one near Sukkos at the season's start). From that week on,
 *  the season needs an actual שבת קיץ chart (not just a couple of extra columns) -
 *  the shul still davens on a "summer" schedule through Pesach once the clock springs
 *  forward. Returns the index in `weeks` of the first week on/after the cutover
 *  (weeks.length if the whole season is still before it - shouldn't happen in
 *  practice, since Pesach always falls after the 2nd Sunday of March). */
function splitChorefAtSpringCutover(weeks, settings) {
  const idx = weeks.findIndex((w) => inSpringDstWindow(w.date, settings));
  return idx === -1 ? weeks.length : idx;
}

/** The smallest hebrewYear for `season` whose date range hasn't already fully elapsed
 *  (its end is still today or later) - i.e. the soonest occurrence of that season still
 *  worth preparing a schedule for. Used to keep the Generate form's year field from
 *  ever defaulting to an already-passed season. */
function nextAvailableYearFor(season, settings) {
  const today = excelSerial(new Date());
  let y = hebrewDateExtended(today, settings.useGregorianBefore1582).year - 1; // step back one to not overshoot a season that started in a lower-numbered year
  for (let i = 0; i < 6 && seasonEndSerial(season, y) < today; i++) y++;
  return y;
}

/** Which season+year the Generate form should default to: the *next* season
 *  chronologically after whichever one contains today - a schedule is always being
 *  prepared ahead of time for the upcoming season, not the one currently in progress.
 *  E.g. if today falls within a קיץ season, default to the חורף season right after it
 *  (never the קיץ season itself, and never a season that's already over). */
function defaultSeasonAndYear(settings) {
  const today = excelSerial(new Date());
  const y0 = hebrewDateExtended(today, settings.useGregorianBefore1582).year;
  const sukkosY0 = dateFromHebrew(15, 7, y0);
  const pesachY0 = dateFromHebrew(15, 1, y0);
  const sukkosY0plus1 = dateFromHebrew(15, 7, y0 + 1);

  let currentSeason, currentYear;
  if (today < sukkosY0) {
    currentSeason = 'kayitz';
    currentYear = y0 - 1; // still in last cycle's קיץ - Sukkos(y0) hasn't happened yet
  } else if (today < pesachY0) {
    currentSeason = 'choref';
    currentYear = y0;
  } else if (today < sukkosY0plus1) {
    currentSeason = 'kayitz';
    currentYear = y0;
  } else {
    currentSeason = 'choref';
    currentYear = y0 + 1;
  }

  return currentSeason === 'choref' ? { season: 'kayitz', hebrewYear: currentYear } : { season: 'choref', hebrewYear: currentYear + 1 };
}

// ==== ui/generate-view.js ====
function renderGenerate(container, state, tables, onGenerate, onOpenTab) {
  const settings = resolveSettings(state.settings);
  const { season: defaultSeason, hebrewYear: defaultYear } = defaultSeasonAndYear(settings);
  // Generate is where the app opens, so it's where someone who has never seen it lands.
  // The pointer shows only until there's a saved sheet - by then they've done it once.
  const firstRun = !state.sheets.length;
  // Held to a column rather than the full width of a desktop screen: this is a short
  // form of small controls, and stretched across a wide monitor it read as a mostly
  // empty page with a stray year field marooned on the right.
  container.innerHTML = `
    <div class="gen-column">
    <h2>Generate a sheet</h2>
    <p class="hint">Pick the season and year, then choose how the weeks split across printable pages.</p>
    ${firstRun ? '<p class="guide-nudge">First time here? <button type="button" id="open-guide" class="linkish">Read the guide</button>. What this site does, and how to print a board.</p>' : ''}
    ${stepsBar(1)}
    <div id="step-one"></div>
    <form id="gen-form" class="form-grid">
      <fieldset>
        <legend>Season</legend>
        <div class="season-picker">
          <input type="radio" id="season-kayitz" class="season-radio" name="season" value="kayitz" ${defaultSeason === 'kayitz' ? 'checked' : ''}>
          <label class="season-option" for="season-kayitz">
            ${SEASON_ICON.kayitz}
            <span class="season-text">
              <span class="season-name">שבת קיץ</span>
              <span class="season-range">Pesach → Sukkos</span>
            </span>
          </label>
          <input type="radio" id="season-choref" class="season-radio" name="season" value="choref" ${defaultSeason === 'choref' ? 'checked' : ''}>
          <label class="season-option" for="season-choref">
            ${SEASON_ICON.choref}
            <span class="season-text">
              <span class="season-name">שבת חורף</span>
              <span class="season-range">Sukkos → Pesach</span>
            </span>
          </label>
        </div>
        <label class="year-row" for="step-hebrewYear"><span class="year-label">Hebrew Year</span>${stepper('hebrewYear', defaultYear)}<span></span></label>
        <div class="actions"><button type="submit" class="btn-primary">Continue <span aria-hidden="true">→</span></button></div>
      </fieldset>
    </form>
    <div id="gen-preview"></div>
    </div>
  `;
  wireSteppers(container);
  container.querySelector('#open-guide')?.addEventListener('click', () => onOpenTab('guide'));

  // Which season card reads as selected. The CSS also has a :checked + label rule, but
  // it was observed not re-evaluating when the checked state changed - leaving the
  // highlight on the previously chosen card - so the class is set explicitly here and
  // is what the styling actually keys off.
  const syncSeasonCards = () => {
    container.querySelectorAll('.season-radio').forEach((radio) => {
      container.querySelector(`label[for="${radio.id}"]`).classList.toggle('is-selected', radio.checked);
    });
  };
  syncSeasonCards();

  // Switching season re-defaults the year to the soonest occurrence of *that* season
  // that hasn't already fully elapsed - e.g. picking חורף after its date range for the
  // current cycle already passed jumps straight to next year's, never a past one.
  //
  // Only while the year is still the app's own default, though. Setting a year and then
  // picking a season is a perfectly normal order to work in, and it used to throw the
  // year away: an answer you gave being overwritten by one you didn't.
  const yearInput = container.querySelector('input[name=hebrewYear]');
  let yearChosenByUser = false;
  yearInput.addEventListener('change', () => (yearChosenByUser = true));
  yearInput.addEventListener('input', () => (yearChosenByUser = true));
  container.querySelectorAll('input[name=season]').forEach((radio) => {
    radio.addEventListener('change', () => {
      syncSeasonCards();
      if (!radio.checked || yearChosenByUser) return;
      yearInput.value = nextAvailableYearFor(radio.value, settings);
    });
  });

  container.querySelector('#gen-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const fd = new FormData(e.target);
    const season = fd.get('season');
    const hebrewYear = Number(fd.get('hebrewYear'));
    const { weeks } = computeSeasonWeeks(season, hebrewYear, settings, tables);

    // Step one folds into a one-line summary once it's answered, so step two isn't
    // competing with a form you've already finished - the page used to just keep
    // growing downward with everything still on screen at once.
    container.querySelector('#gen-form').hidden = true;
    container.querySelector('#step-one').innerHTML = `
      <div class="step-summary">
        <span dir="ltr"><bdi><strong>${seasonLabel(season)}</strong></bdi> · ${hebrewYear} · ${weeks.length} weeks</span>
        <button type="button" id="change-sheet">Change</button>
      </div>`;
    container.querySelector('#gen-steps').outerHTML = stepsBar(2);
    container.querySelector('#change-sheet').addEventListener('click', () => renderGenerate(container, state, tables, onGenerate));

    // No scrolling into view: collapsing step one keeps step two roughly where step one
    // was, and scrolling to it pushed the step indicator off the top of the screen.
    renderPreview(container.querySelector('#gen-preview'), season, hebrewYear, weeks, settings, state, tables, onGenerate);
  });
}

const seasonLabel = (season) => (season === 'kayitz' ? 'שבת קיץ' : 'שבת חורף');

// Sun and snowflake, so the two cards are told apart at a glance rather than by reading.
// Inline SVG in currentColor's place with their own colours, for the same reason the nav
// icons are inline: the offline copy stays one self-contained folder.
const SEASON_ICON = {
  kayitz: `<svg class="season-icon is-summer" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true">
    <circle cx="12" cy="12" r="4.2"/><path d="M12 2.4v2.2M12 19.4v2.2M2.4 12h2.2M19.4 12h2.2M5.2 5.2l1.6 1.6M17.2 17.2l1.6 1.6M18.8 5.2l-1.6 1.6M6.8 17.2l-1.6 1.6"/></svg>`,
  // One arm (the spine plus a V at each end) drawn three times, rotated 60 degrees apart,
  // which is what makes it come out as an even six-pointed flake. Built by hand the first
  // time and it showed: the barbs were at different angles on every arm.
  choref: `<svg class="season-icon is-winter" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
    <g><path d="M12 2.8v18.4M9.7 5.3 12 3l2.3 2.3M9.7 18.7 12 21l2.3-2.3"/></g>
    <g transform="rotate(60 12 12)"><path d="M12 2.8v18.4M9.7 5.3 12 3l2.3 2.3M9.7 18.7 12 21l2.3-2.3"/></g>
    <g transform="rotate(120 12 12)"><path d="M12 2.8v18.4M9.7 5.3 12 3l2.3 2.3M9.7 18.7 12 21l2.3-2.3"/></g></svg>`,
};

/** Two-step progress header, so it's clear up front that this is a short sequence and
 *  which part you're on - previously the second half simply appeared below the first
 *  with nothing marking it as a separate step. */
function stepsBar(current) {
  const step = (n, label) => {
    const state = n === current ? 'is-current' : n < current ? 'is-done' : '';
    return `<li class="${state}"><span class="step-num">${n < current ? '✓' : n}</span>${label}</li>`;
  };
  return `<ol class="steps" id="gen-steps">${step(1, 'Sheet setup')}${step(2, 'Pages')}</ol>`;
}

function renderPreview(el, season, hebrewYear, weeks, settings, state, tables, onGenerate) {
  if (weeks.length === 0) {
    el.innerHTML = `<p class="hint">No qualifying Shabbosim found for that range. Double check the Hebrew year.</p>`;
    return;
  }

  // A שבת חורף season that reaches the spring DST cutover (2nd Sunday of March) needs
  // its tail weeks to be an actual שבת קיץ chart, not just plain חורף - the shul really
  // is on the summer schedule from the clock change through Pesach. You choose the page
  // split yourself below (covering all the weeks, as usual); at render time, any page
  // that ends up containing at least one of these weeks prints as a real קיץ chart -
  // the other, earlier weeks on that same page just show blank Plag columns.
  const springSplitIndex = season === 'choref' ? splitChorefAtSpringCutover(weeks, settings) : weeks.length;
  const kayitzWeekCount = weeks.length - springSplitIndex;

  // The Weekday chart's own week list can include weeks the Shabbos list skips (a Yom
  // Tov Shabbos whose week still has a regular weekday), so it's computed and paginated
  // completely separately - see the "Also generate a Weekday chart" section below.
  const weekdayWeeks = computeWeekdayWeeks(season, hebrewYear, settings, tables).weeks;

  el.innerHTML = `
    <details class="panel">
      <summary>Show all ${weeks.length} weeks (${fmtDate(weeks[0].date)} – ${fmtDate(weeks[weeks.length - 1].date)})</summary>
      <ol class="week-list">${weeks.map((w, i) => `${i === springSplitIndex ? '<li class="week-marker"><strong>Spring DST cutover: any page from here on prints as שבת קיץ</strong></li>' : ''}<li>${w.date.toISOString().slice(0, 10)}: ${esc(w.parsha)}${w.specialParsha ? ' (' + esc(w.specialParsha) + ')' : ''}</li>`).join('')}</ol>
    </details>
    ${
      kayitzWeekCount > 0
        ? `<p class="hint"><strong>${kayitzWeekCount} of these ${weeks.length} weeks</strong> (from ${fmtDate(weeks[springSplitIndex].date)} onward) are past the spring DST cutover and need the שבת קיץ layout. Keep that in mind when you split into pages below: whichever page ends up holding the first of them will print as a full שבת קיץ chart.</p>`
        : ''
    }
    <form id="page-form" class="form-grid">
      <fieldset>
        <legend>How many printable pages?</legend>
        <label for="step-numPages" style="max-width:160px">Number of pages${stepper('numPages', 3, { min: 1, max: 8 })}</label>
      </fieldset>
      <fieldset>
        <legend>Weeks per page (must add up to ${weeks.length})</legend>
        <div id="page-size-inputs"></div>
        <div class="alloc" id="alloc">
          <div class="alloc-bar" id="alloc-bar"></div>
          <p class="alloc-msg" id="alloc-msg"></p>
        </div>
        <div id="page-error" class="error"></div>
      </fieldset>
      <fieldset>
        <legend>Weekday chart</legend>
        <label><input type="checkbox" id="include-weekday" checked> Also generate a Weekday chart (separate file) for these weeks</label>
        <p class="hint">Covers ${weekdayWeeks.length} weeks, a little more than the ${weeks.length} above when a Yom Tov Shabbos week still has a regular weekday in it. It uses the same weeks and the same page breaks as the sheet above, so page 1 of each covers the same stretch of the year.</p>
        <details class="panel">
          <summary>Show the ${weekdayWeeks.length} weekday weeks</summary>
          <ol class="week-list">${weekdayWeeks.map((w) => `<li>${w.date.toISOString().slice(0, 10)}: ${esc(w.parsha)}</li>`).join('')}</ol>
        </details>
      </fieldset>
      <div class="actions"><button type="submit" class="btn-primary">Generate sheet</button></div>
    </form>
  `;

  const inputsEl = el.querySelector('#page-size-inputs');
  const numPagesInput = el.querySelector('input[name=numPages]');
  function renderSizeInputs(numPages) {
    const defaults = defaultPageSizes(weeks.length, numPages);
    inputsEl.innerHTML = defaults.map((size, i) => `<label for="step-pageSize${i}">Page ${i + 1} weeks${stepper(`pageSize${i}`, size, { min: 0, className: 'page-size' })}</label>`).join('');
    wireSteppers(inputsEl);
  }
  // Live picture of the split: one block per page, sized to its share, plus what's left
  // over or overflowing. The numbers alone made you add them up in your head to find out
  // whether you were three weeks short.
  const barEl = el.querySelector('#alloc-bar');
  const msgEl = el.querySelector('#alloc-msg');
  function renderAlloc() {
    const sizes = [...el.querySelectorAll('.page-size')].map((i) => Number(i.value) || 0);
    const placed = sizes.reduce((a, b) => a + b, 0);
    const total = weeks.length;
    const short = Math.max(0, total - placed);
    const over = Math.max(0, placed - total);
    // Widths are shares of the wider of the two, so going over pushes the pages along
    // instead of the overflow appearing out of nowhere.
    const scale = Math.max(total, placed) || 1;
    const pct = (n) => (n / scale) * 100;
    barEl.innerHTML = [
      ...sizes.map((n, i) => `<span class="alloc-seg" style="width:${pct(n)}%" title="Page ${i + 1}: ${n} week${n === 1 ? '' : 's'}">${n || ''}</span>`),
      short ? `<span class="alloc-seg is-short" style="width:${pct(short)}%" title="${short} not on any page yet">${short}</span>` : '',
      over ? `<span class="alloc-seg is-over" style="width:${pct(over)}%" title="${over} more than there are weeks">+${over}</span>` : '',
    ].join('');
    msgEl.classList.toggle('is-bad', placed !== total);
    msgEl.textContent = short
      ? `${placed} of ${total} weeks placed, ${short} still to go.`
      : over
        ? `${placed} placed, ${over} more than the ${total} weeks there are.`
        : `All ${total} weeks placed.`;
  }

  renderSizeInputs(3);
  renderAlloc();
  numPagesInput.addEventListener('change', () => {
    const n = Math.max(1, Math.min(8, Number(numPagesInput.value) || 1));
    numPagesInput.value = n;
    renderSizeInputs(n);
    renderAlloc();
  });
  // 'change' covers the stepper buttons (they dispatch it) and 'input' catches typing as
  // it happens, so the bar never lags behind the numbers.
  inputsEl.addEventListener('change', renderAlloc);
  inputsEl.addEventListener('input', renderAlloc);

  wireSteppers(el);

  el.querySelector('#page-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const sizes = [...el.querySelectorAll('.page-size')].map((input) => Number(input.value));
    const err = validatePageSizes(weeks.length, sizes);
    const errEl = el.querySelector('#page-error');
    if (err) {
      errEl.textContent = err;
      return;
    }
    errEl.textContent = '';

    const includeWeekday = el.querySelector('#include-weekday').checked;
    const shabbosSheetId = newId('sheet');

    if (includeWeekday) {
      onGenerate({
        id: newId('sheet'),
        season: 'weekday',
        hebrewYear,
        linkedSeason: season, // which Shabbos season this was generated alongside
        linkedSheetId: shabbosSheetId, // the exact sheet below, for the "View שבת sheet" link
        createdAt: new Date().toISOString(),
        weeks: weekdayWeeks.map((w) => ({ serial: w.serial, date: w.date.toISOString(), parsha: w.parsha, specialParsha: w.specialParsha })),
        // Page breaks fall on the same dates as the Shabbos sheet's, rather than being
        // chosen separately - see alignPageSizesTo().
        pageSizes: alignPageSizesTo(weeks, sizes, weekdayWeeks),
        overrides: {},
        style: { ...state.settings.sheetStyle },
      });
    }
    onGenerate({
      id: shabbosSheetId,
      season,
      hebrewYear,
      createdAt: new Date().toISOString(),
      weeks: weeks.map((w) => ({ serial: w.serial, date: w.date.toISOString(), parsha: w.parsha, specialParsha: w.specialParsha })),
      pageSizes: sizes,
      overrides: {},
      style: { ...state.settings.sheetStyle }, // remembers whatever style was last used
    });
  });
}

/** A number input paired with clear − / + buttons instead of relying on the browser's
 *  tiny native spinner (or worse, the scroll wheel). `opts.className` lets callers
 *  (e.g. the per-page week-count fields) still find the underlying input the same way
 *  a plain <input class="page-size"> would have been found before. */
function stepper(name, value, opts = {}) {
  const { min, max, className = '' } = opts;
  // The input carries an id and every wrapping <label> points at it with for= - without
  // that, a label associates with its *first* form control, which here is the − button,
  // and Chrome then mirrors the label's hover/pressed state onto it: pressing + lit −
  // up as well, and clicking the label's text acted like pressing −.
  return `
    <span class="stepper">
      <button type="button" class="step-btn step-down" aria-label="Decrease" tabindex="-1">−</button>
      <input type="number" id="step-${name}" name="${name}" class="step-input ${className}" value="${value}" ${min !== undefined ? `min="${min}"` : ''} ${max !== undefined ? `max="${max}"` : ''}>
      <button type="button" class="step-btn step-up" aria-label="Increase" tabindex="-1">+</button>
    </span>`;
}

/** Wires every .stepper's −/+ buttons found within `root` to nudge their input by 1
 *  (clamped to its own min/max, if set) and fire a real 'change' event, so any existing
 *  listener on the input (e.g. the "Number of pages" handler above) reacts exactly as
 *  if the number had been typed in directly. */
function wireSteppers(root) {
  root.querySelectorAll('.stepper').forEach((wrap) => {
    // Guard against double-wiring: the page-size steppers sit inside the preview, so
    // they were reached both by their own renderSizeInputs() call and by the later
    // wireSteppers(el) over the whole preview - two listeners, and every click moved
    // the number by 2.
    if (wrap.dataset.wired) return;
    wrap.dataset.wired = '1';
    const input = wrap.querySelector('.step-input');
    const min = input.min !== '' ? Number(input.min) : -Infinity;
    const max = input.max !== '' ? Number(input.max) : Infinity;
    const nudge = (delta) => {
      input.value = Math.min(max, Math.max(min, (Number(input.value) || 0) + delta));
      input.dispatchEvent(new Event('change', { bubbles: true }));
    };
    wrap.querySelector('.step-down').addEventListener('click', () => nudge(-1));
    wrap.querySelector('.step-up').addEventListener('click', () => nudge(1));
  });
}

// dateFromSerial (zmanim/solar.js) returns a UTC-midnight Date; formatting it with
// .toDateString() would run it through the *local* timezone instead, which for any
// timezone behind UTC (e.g. US Eastern) rolls the displayed calendar day back by one.
// This keeps the "weeks found" summary matching the actual dates in the list below.
function fmtDate(date) {
  return new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }).format(date);
}

function esc(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ==== ui/guide-view.js ====
// The "what is this and how do I use it" page, written for someone opening the site for
// the first time with no idea what it does. Lives inside the app rather than in a README
// so it travels with the offline/USB copy and is there at the moment it's needed.

/** @param {(tab: string) => void} onOpenTab  jumps to another screen from a link here. */
function renderGuide(container, onOpenTab) {
  container.innerHTML = `
    <h2>Guide</h2>
    <p class="hint">What this site is, and how to get a printed board out of it.</p>

    <div class="guide-lede">
      <p>This generates the printed <strong>zmanim boards</strong> for קהל לב מנחם: the שבת קיץ and שבת חורף charts and the matching Weekday chart. Every time in them is calculated for the shul's exact location, so a new year's board takes a minute instead of an afternoon of editing last year's.</p>
      <p>Everything happens in this browser. There's no login and nothing to install, and no one else sees what you do here.</p>
    </div>

    <details class="panel" open>
      <summary>Make your first board in 3 steps</summary>
      <div class="panel-body">
        <ol class="guide-steps">
          <li>
            <strong>Generate → pick the season and year.</strong>
            <span class="hint">שבת קיץ runs Pesach → Sukkos, שבת חורף runs Sukkos → Pesach. The year and season start on whichever one is coming up next, so usually you can just press Continue. The app works out which Shabbosim belong to that season by itself, skipping the ones with no parsha.</span>
          </li>
          <li>
            <strong>Choose how the weeks split across pages.</strong>
            <span class="hint">It tells you how many weeks the season has and suggests an even split. Change the number on any page and the rest adjust. A Weekday chart is generated alongside, covering the same weeks.</span>
          </li>
          <li>
            <strong>Press Generate.</strong>
            <span class="hint">The finished board opens straight away, and is saved automatically, so you never have to remember to save.</span>
          </li>
        </ol>
      </div>
    </details>

    <details class="panel">
      <summary>Working on a board</summary>
      <div class="panel-body">
        <p><strong>Any cell can be edited.</strong> Click it and type. Typing <code>300</code> becomes <code>3:00</code>, so you can enter a whole row of times as bare numbers and let it space them out. Edits stick to that one board and never touch next year's.</p>
        <p><strong>Formatting.</strong> Select text inside a cell, then use the buttons in the toolbar: <u>U</u> underlines (that's how the board marks a minyan that's downstairs), A+ and A− change its size. Keyboard: <kbd>Ctrl</kbd>+<kbd>U</kbd>, <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>&gt;</kbd>, <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>&lt;</kbd>.</p>
        <p><strong>Undo / Redo</strong> covers cell edits, for as long as the board stays open.</p>
        <p><strong>Layout &amp; style</strong> changes the font, the text size, the logo size and the heading colour for the whole board.</p>
        <p><strong>Side by side</strong> shows the Shabbos and Weekday charts next to each other, shrunk, to compare them. <strong>Fit to screen</strong> scales a page down until it fits across the screen. It turns itself on automatically on a phone, where a full-width page otherwise can't be seen at all.</p>
      </div>
    </details>

    <details class="panel">
      <summary>Printing and PDFs</summary>
      <div class="panel-body">
        <p><strong>Print / Save as PDF</strong> opens your browser's print dialog. Saving a PDF is the same button: choose "Save as PDF" as the destination instead of a printer.</p>
        <p>Set the paper to <strong>Letter, landscape</strong>, and turn on <strong>background graphics</strong> so the shaded header row prints.</p>
        <p>The Shabbos and Weekday pages come out interleaved (שבת, its Weekday chart, שבת, its Weekday chart), so the pair for a run of weeks stays together.</p>
        <p>Under <strong>Which pages to print or save</strong> you can untick individual pages. Unticked pages stay on screen, dimmed, and are left out of the print.</p>
      </div>
    </details>

    <details class="panel">
      <summary>The luach for the congregation</summary>
      <div class="panel-body">
        <p><strong>lczmanim.cjaffa.com/?luach</strong> shows one week at a time to anyone who opens it. No login, nothing to install, and it moves to the next week by itself once Shabbos is over. Previous and next week are there too.</p>
        <p>It does not read your saved sheets, because a visitor's browser has none of them. It reads a published copy of the season, so it only shows what you have published.</p>
        <p><strong>To publish:</strong> open <strong>This week</strong>, expand <em>Publish for the congregation</em>, and press the button. A minute later the congregation's page is showing it. Publish once per season, and again whenever you change a time so they see the correction.</p>
        <p>Publishing needs a one-time setup: a token that allows the site to be written to. <strong>Settings → Publishing</strong> has step-by-step instructions for making one, and until it is set the publish button explains that rather than appearing broken.</p>
        <p>Publishing a season leaves any other published season in place, so קיץ and חורף can both be live and the changeover between them happens on its own. A new year's chart does not remove last year's. Each published season also has an <strong>Unpublish</strong> button, and <strong>Saved sheets</strong> marks which sheet the congregation is currently looking at.</p>
      </div>
    </details>

    <details class="panel">
      <summary>Sending a chart to someone else</summary>
      <div class="panel-body">
        <p>Send a PDF. Press <strong>Print / Save as PDF</strong> and choose Save as PDF as the destination instead of a printer.</p>
        <p>Whoever receives it can open and print it without this site, an account, or an internet connection, which matters on a computer where the browser is blocked but a PDF reader isn't.</p>
      </div>
    </details>

    <details class="panel">
      <summary>Rules: the difference between a one-off and every year</summary>
      <div class="panel-body">
        <p>Editing a cell changes <em>that board</em>. A <strong>rule</strong> changes <em>every board you generate from now on</em>, which is what you want for something that comes back every year.</p>
        <p>Three are built in: שבת הגדול and שבת שובה add "דרשה" to the Mincha column, and ט באב marks the Shabbos when the fast starts מוצאי שבת. A rule can match on a special-Shabbos name (שובה, הגדול), a parsha name, a Hebrew date (recurring every year), or every week.</p>
        <p>One rule can cover both charts at once: tick the matching column on קיץ and on חורף. Rules can be switched off without deleting them, and <strong>Duplicate</strong> starts a new one from an existing one.</p>
        <p>Cells a rule has touched show a light yellow background on the board.</p>
      </div>
    </details>

    <details class="panel">
      <summary>Saved sheets</summary>
      <div class="panel-body">
        <p>Every board you generate is saved here automatically. A Shabbos board and the Weekday chart made with it are one entry. Open either from the same row.</p>
        <p><strong>Lock</strong> protects a board from being deleted until you unlock it. <strong>Folders</strong> are for keeping the list tidy: a folder appears as soon as you put something in it and disappears when the last thing leaves.</p>
      </div>
    </details>

    <details class="panel">
      <summary>Settings</summary>
      <div class="panel-body">
        <p>The shul's location, elevation, timezone and the offsets the calculations use (candle lighting, the various Tzais and Plag opinions), plus the shul name, the rabbi's line and the daily שחרית schedule printed on the Weekday chart. It's already set up for 44 Coles Way, so you shouldn't need to touch it unless something moves.</p>
      </div>
    </details>

    <details class="panel">
      <summary>Where your work is kept (read this one)</summary>
      <div class="panel-body">
        <p>Boards, rules and settings are stored <strong>in this browser on this device</strong>. That means:</p>
        <ul>
          <li>Your phone and your computer each have their own boards. They don't sync.</li>
          <li>Clearing the browser's site data erases them.</li>
          <li>Nobody else visiting the site sees your work, and you don't see theirs.</li>
        </ul>
        <p>To move everything between devices, or to keep a backup: <strong>Settings → Backup → Export</strong> writes one file, and <strong>Import</strong> reads it back on the other device.</p>
        <p><strong>Offline:</strong> the site also ships as a folder you can copy to a USB stick and open on a computer with no internet. Open <code>index.html</code> inside it and it behaves exactly the same.</p>
      </div>
    </details>

    <div class="actions"><button type="button" id="guide-start" class="btn-primary">Make a board →</button></div>
  `;

  container.querySelector('#guide-start').addEventListener('click', () => onOpenTab('generate'));
}

// ==== erev-text.js ====
// The Erev Shabbos message, as a line of text somebody can paste into a chat.
//
// Somebody sends this out every Friday, typed out by hand off the board. All of it is on
// the board already, so it can be built from the same row the שבת card is built from, and
// then there is one place the times come from rather than two.
//
// A worked example, checked against a real message for כי תבוא:
//
//   Erev P' Ki Savo
//   Mincha 1:35d, 1:50m, 2:15m, 3:00m
//   Mincha 5:57m & ns, Plag Gra 6:12
//   Mincha 6:33d, Plag MA 6:48
//   Mincha 6:53en Plag 7:08
//   Hadlakas Neiros 7:16
//   Mincha 7:19m & ns
//   Have a great Shabbos!
//
// Where each piece comes from:
//
//   Erev P'          the parsha, in English, out of data/parsha_names.json, which already
//                    carries "Ki Savo" beside כי תבוא for the chart's own use.
//   d                the time is underlined on the board. The printed footer already says
//                    "All underlined מנינים will be למטה", so underlined is downstairs and
//                    d is what the message calls it.
//   m                not underlined, so the main בית מדרש.
//   en               the מנחה (בעזר״נ) column, which says where it davens in its own
//                    heading. It is the room, like d, so it does not depend on the
//                    underline.
//   Plag Gra / MA    the פלג on the second line of those two columns, named for whichever
//                    the column is headed with.
//   & ns             NOT on the board. The פלג גר"א מנחה and the מנחה מעריב also daven in
//                    the עזרת נשים, which is something the sender knows and the chart does
//                    not say. Fixed to those two columns, on instruction.
//
// Winter has none of the פלג columns (CHOREF_COLUMNS is eight wide against קיץ's twelve),
// so those three lines simply do not appear. Nothing here asks for a column by name: each
// one is recognised by its own heading and skipped when the season has not got it.


/** The closing line, and the only words here that are not read off the board. */
const EREV_SIGN_OFF = 'Have a great Shabbos!';

/** Which columns get "& ns" bolted on. Named by what their heading says rather than by
 *  column key, since the keys differ between the two seasons. */
const EREV_ALSO_NASHIM = ['plagGra', 'minchaMaariv'];

/** A cell as it is stored is plain text carrying the underline sentinels, but an override
 *  typed by hand is real HTML. Both are flattened to the same thing here: text, newlines,
 *  and the sentinels marking what is underlined.
 *
 *  Exported because the שבת שובה poster reads the same cells. One reader for both, or the
 *  poster would drift from the board it is supposed to be quoting. */
function erevPlain(value) {
  return String(value ?? '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/?u\b[^>]*>/gi, (tag) => (tag[1] === '/' ? UL_END : UL_START))
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

/** Every clock time in a cell, in order, each with whether it was underlined and which
 *  line of the cell it sat on. The line matters because the פלג of a column is written
 *  under its מנחה rather than beside it. */
function erevTimes(value) {
  const text = erevPlain(value);
  const out = [];
  let line = 0;
  let underlined = false;
  // Walked character by character rather than by one regex, so that a sentinel opening
  // before a time and closing after it is tracked across the whole cell.
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '\n') { line++; continue; }
    if (ch === UL_START) { underlined = true; continue; }
    if (ch === UL_END) { underlined = false; continue; }
    const m = /^\d{1,2}:\d{2}/.exec(text.slice(i));
    if (m) {
      out.push({ text: m[0], underlined, line, before: text.slice(0, i) });
      i += m[0].length - 1;
    }
  }
  return out;
}

/** What a column is, by what its heading says. Headings carry newlines and quote marks of
 *  several kinds, so this asks only for the words that tell the columns apart. */
function erevKindOf(header) {
  const h = String(header ?? '').replace(/\s+/g, ' ');
  if (h.includes('ערב שבת')) return 'erevShabbos';
  if (h.includes('הדלקת')) return 'candles';
  if (h.includes('בעזר')) return 'ezrasNashim';
  if (h.includes('למטה')) return 'lmata';
  if (h.includes('פלג גר')) return 'plagGra';
  if (h.includes('מנחה') && h.includes('מעריב')) return 'minchaMaariv';
  return null;
}

/** Which פלג a column's second line is, said the way the message says it. */
function erevPlagLabel(kind) {
  if (kind === 'plagGra') return 'Plag Gra';
  if (kind === 'lmata') return 'Plag MA';
  return 'Plag';
}

/** d, m or en: where this מנין davens. */
function erevWhere(kind, time) {
  if (kind === 'ezrasNashim') return 'en';
  return time.underlined ? 'd' : 'm';
}

/** The message for one week.
 *
 *  @param columns/row - straight from rowFor(), so this reads exactly what the card and
 *    the chart read and cannot drift from them.
 *  @param parshaEnglish - "Ki Savo". Left to the caller because looking it up needs the
 *    tables, which are loaded asynchronously, and this stays a plain function.
 *
 *  The order is the order the message is written in, which is the order the evening
 *  happens in, and that is the printed order of the columns reversed. */
function erevShabbosText(columns, row, parshaEnglish) {
  const lines = [];
  lines.push(`Erev P' ${parshaEnglish}`);

  for (const col of [...columns].reverse()) {
    const kind = erevKindOf(col.header);
    if (!kind) continue;
    const times = erevTimes(row[col.key]);
    if (!times.length) continue;

    if (kind === 'erevShabbos') {
      // The whole row, every time with where it davens, which is the one column that
      // lists more than one מנין.
      lines.push('Mincha ' + times.map((t) => t.text + erevWhere(kind, t)).join(', '));
      continue;
    }
    if (kind === 'candles') {
      // The first time only. The second is שקיעה, which the message does not carry.
      lines.push(`Hadlakas Neiros ${times[0].text}`);
      continue;
    }

    const first = times[0];
    const alsoNashim = EREV_ALSO_NASHIM.includes(kind) ? ' & ns' : '';
    // The פלג is the time written under the מנין, so anything on a later line of the cell.
    const plag = times.find((t) => t.line > first.line);
    let line = `Mincha ${first.text}${erevWhere(kind, first)}${alsoNashim}`;
    if (plag) {
      // No comma on the בעזר״נ line, which is how the message is written. The others take
      // one.
      line += kind === 'ezrasNashim'
        ? ` ${erevPlagLabel(kind)} ${plag.text}`
        : `, ${erevPlagLabel(kind)} ${plag.text}`;
    }
    lines.push(line);
  }

  lines.push(EREV_SIGN_OFF);
  return lines.join('\n');
}

/** "Ki Savo" for כי תבוא, out of the table the chart already uses. Falls back to the Hebrew
 *  rather than to nothing: a message naming the parsha in Hebrew is still usable, one
 *  naming no parsha at all is not. */
function erevParshaEnglish(hebrewParsha, parshaNames) {
  const want = String(hebrewParsha ?? '').trim();
  const row = parshaNames?.rows?.find((r) => String(r[0]).trim() === want);
  return (row && row[1]) || want;
}

// ==== posters/shuva.js ====
// The שבת שובה poster, read off the board rather than typed out.
//
// The shul hangs a sheet on שבת שובה saying when the דרשה is and when מנחה is. Until now
// it was a Word file, retyped every year from whatever the chart said, which is two places
// for one set of times and one of them always a year behind.
//
// Everything here comes out of the chart's own מנחה cell for that week, through the same
// rowFor() the sheet is drawn with. So it carries the rules, and it carries a per-cell
// override too: if somebody edits that cell on the sheet, the poster says what the sheet
// says. That is the point of reading the cell rather than recomputing the times beside it.
//
// The old posters marked where a minyan was with asterisks, ** for למטה. The boards use a
// different system now and the poster follows them: plain is the main bais medrash,
// underlined is למטה, * is בעזרת נשים. The note at the foot is built from whichever of
// those actually appear, so a poster never explains a mark it does not carry.



/** The lines that are the poster rather than the times: what it is, and who is speaking.
 *
 *  In one place and not in settings, for now. They have not changed in the years of posters
 *  we have, and a settings field nobody edits is a field to keep working. When a second
 *  poster wants its own wording this is where they both come from. */
const SHUVA_TEXT = {
  title: 'שבת שובה דרשה',
  lines: ['בעזהשי"ת הרב שליט"א', 'ידרוש בהלכה ובאגדה'],
  at: 'בשעה',
  minchaLabel: 'מנחה',
};

/** Which of the sheet's weeks is שבת שובה, or nothing if this sheet does not cover it.
 *
 *  Asked of the week's own specialParsha, which the calendar has already worked out, so
 *  this does not need its own idea of when שבת שובה falls. */
function shuvaWeekOf(sheet) {
  if (!sheet || !Array.isArray(sheet.weeks)) return null;
  // A Weekday chart covers the same dates and has no מנחה column of this kind to read, so
  // it is not a sheet this poster can come from even though שבת שובה falls inside it.
  if (sheet.season === 'weekday') return null;
  return sheet.weeks.find((w) => SHUVA_NAMES.includes(w.specialParsha)) || null;
}

/** The poster's content for a sheet, or null when that sheet has no שבת שובה in it.
 *
 *  Returns the דרשה's time and the מנחה times as they stand on the board, each knowing
 *  whether it was underlined and whether it carried a *, so the view can draw them the way
 *  the chart draws them and the foot can say only what is needed.
 */
function buildShuvaPoster(sheet, state, settings) {
  const week = shuvaWeekOf(sheet);
  if (!week) return null;
  const { row } = rowFor({ ...week, date: new Date(week.date) }, sheet, state, settings);
  const cell = row.C;
  const found = erevTimes(cell);

  // The דרשה is the time whose own line says דרשה. Asked of the text in front of it rather
  // than of its position, since a hand-edited cell can put it anywhere, and asked of the
  // line rather than of the whole cell so a second time on that line is not mistaken for it.
  const isDrasha = (t) => /דרשה[^\n]*$/.test(t.before);
  const drasha = found.find(isDrasha) || null;

  // A time is בעזרת נשים if a * is stuck to it. The boards write the star after the digits
  // (see the Weekday chart), so that is where this looks. Measured against erevPlain's own
  // output, because that is what erevTimes counted its offsets against: flattening any
  // other way puts the offsets somewhere else in the string.
  const flat = erevPlain(cell);
  const starred = (t) => /^\s*\*/.test(flat.slice(t.before.length + t.text.length));

  // mark is the same field the סליחות poster carries, so one renderer draws both: '' is
  // the main בית מדרש, '*' is בעזרת נשים, '**' is באולם השמחות, and למטה is the underline.
  const mincha = found
    .filter((t) => !isDrasha(t))
    .map((t) => ({ text: t.text, underlined: t.underlined, mark: starred(t) ? '*' : '' }));

  return {
    week,
    drasha: drasha ? drasha.text : null,
    mincha,
    // Only the marks that are actually on this poster get explained. Each line says which
    // direction it has to be set in: the underline line is an English sentence carrying
    // Hebrew and reads left to right, the star line is Hebrew and reads right to left, and
    // setting that one the wrong way puts the star at the far end of the line instead of
    // against the words it marks. Same split as the week card's legend.
    legend: [
      mincha.some((t) => t.underlined)
        ? { dir: 'ltr', text: 'All underlined מנינים will be בבית מדרש למטה' } : null,
      mincha.some((t) => t.mark === '*') ? { dir: 'rtl', text: '*בעזרת נשים' } : null,
    ].filter(Boolean),
  };
}

// ==== posters/slichos.js ====
// The סליחות poster: the yomim noraim minyan schedule the shul hangs before ר"ה.
//
// The times on it are the shul's own minyan slots and are not on the zmanim board, so
// unlike the שבת שובה poster there is no cell to read them out of. They are the table
// below. What is worked out here is the part that was wrong every few years when this was
// a Word file: which days each line actually covers.
//
// Two lines carry a note that the first מנין is five minutes earlier on the days there is
// קריאת התורה, because the davening runs longer. On the hand-made posters that note was
// typed as "יום ב' וה'" or "יום ב'" and left alone the next year, and the days it names
// change with the day ר"ה falls on. So it is computed.
//
// The marks are the boards' marks, not the old poster's. The Word posters used * for
// בעזרת נשים, ** for למטה and *** for אולם השמחות; the app writes plain for the main בית
// מדרש, an underline for למטה, * for בעזרת נשים and ** for אולם השמחות. Everything below
// is written in the app's system, so somebody holding the poster and the chart is reading
// one set of marks.

/** Excel WEEKDAY numbering, which is what excelWeekday returns: 1 is Sunday. */
const DOW_SUNDAY = 1;
const DOW_MONDAY = 2;
const DOW_THURSDAY = 5;
const DOW_SHABBOS = 7;

/** The days the Torah is read at shacharis, which is why those mornings start earlier.
 *  Named in the order the note says them. */
const KRIAS_HATORAH = [
  { dow: DOW_MONDAY, he: "יום ב'", both: "יום ב'" },
  { dow: DOW_THURSDAY, he: "יום ה'", both: "וה'" },
];

/** ר"ה of a Hebrew year, as an Excel serial. roshHashana() takes the year with the 3761
 *  taken off it, which is how the workbook's own defined name is written. */
const roshHashanaSerial = (hebrewYearNum) => roshHashana(hebrewYearNum - 3761);

/** The first morning of סליחות.
 *
 *  They begin on a Sunday (the מוצ"ש before it is the first night), and if the Sunday
 *  before ר"ה would leave fewer than four days they begin the Sunday before that. Which
 *  is why the run is four days in some years and nine in others. */
function slichosStart(hebrewYearNum) {
  const erev = roshHashanaSerial(hebrewYearNum) - 1; // 29 אלול
  let start = erev - (excelWeekday(erev) - DOW_SUNDAY); // the Sunday on or before it
  if (erev - start + 1 < 4) start -= 7;
  return start;
}

/** צום גדליה: 3 תשרי, pushed to the 4th when the 3rd is Shabbos. Returned as a day of
 *  תשרי rather than a serial, since that is how the days around it are counted here. */
function tzomGedaliaDay(rh) {
  return excelWeekday(rh + 2) === DOW_SHABBOS ? 4 : 3;
}

/** The mornings each of the two multi-day lines covers, as Excel weekdays.
 *
 *  סליחות is every סליחות morning after that first Sunday, up to but not including ערב ר"ה,
 *  which has a line of its own. עשי"ת is 3 to 8 תשרי, less Shabbos and less צום גדליה,
 *  which also have their own lines, and less ערב יו"כ on the 9th.
 *
 *  Both skip Shabbos, which has no weekday shacharis to print. */
function posterDays(hebrewYearNum) {
  const rh = roshHashanaSerial(hebrewYearNum);
  const erev = rh - 1;
  const start = slichosStart(hebrewYearNum);

  const slichos = [];
  for (let d = start + 1; d < erev; d++) if (excelWeekday(d) !== DOW_SHABBOS) slichos.push(excelWeekday(d));

  const tzom = tzomGedaliaDay(rh);
  const aseres = [];
  for (let n = 3; n <= 8; n++) {
    const d = rh + n - 1;
    if (excelWeekday(d) === DOW_SHABBOS || n === tzom) continue;
    aseres.push(excelWeekday(d));
  }
  return { slichos, aseres };
}

/** The note in brackets at the end of a line: which of יום ב' and יום ה' fall inside it,
 *  and what time the first מנין is on them.
 *
 *  Nothing at all if neither falls in the range, which does happen: the four-day סליחות of
 *  a year ר"ה is on Thursday runs Sunday to Wednesday and never reaches a Thursday, and the
 *  עשי"ת of a year ר"ה is on Shabbos runs Tuesday to Friday and never reaches a Monday. */
function kriasHatorahNote(days, time) {
  if (!time) return '';
  const hit = KRIAS_HATORAH.filter((d) => days.includes(d.dow));
  if (!hit.length) return '';
  // "יום ב' וה'" when both, and each on its own reads as itself.
  const named = hit.length === 2 ? `${hit[0].both} ${hit[1].both}` : hit[0].he;
  return `(${named} ${time})`;
}

/** The poster, line by line, in the order it is hung.
 *
 *  `times` is written the way a chart cell is: a plain time is the main בית מדרש, <u> is
 *  למטה, a trailing * is בעזרת נשים and ** is באולם השמחות. `earlier` is the five-minutes-
 *  earlier first מנין on a קריאת התורה morning, and `days` says which range decides which
 *  of those mornings the line actually has.
 *
 *  Here rather than in settings, the same as the שבת שובה wording: these are the shul's
 *  fixed מנין slots and they have not moved in the posters we have. The year's worth of
 *  it that does change is computed above. */
const SLICHOS_ROWS = [
  { label: 'דרשה מאת הרב שליט"א', times: '12:30' },
  { label: 'סליחות מוצ"ש', times: '12:55' },
  { label: "שחרית יום א' (no סליחות)", times: '7:00, 7:20*, <u>7:35</u>, 8:00, 8:20*, <u>8:40</u>' },
  { label: 'סליחות', times: '6:40, 7:00*, <u>7:15</u>, 7:35**, 8:00, 8:30*', earlier: '6:35', days: 'slichos' },
  { label: 'ערב ר"ה', times: '6:30, <u>7:10</u>' },
  { label: 'צום גדליה', times: '6:20, 6:40*, <u>7:00</u>, 7:35**, 8:00' },
  { label: 'עשי"ת', times: '6:25, 6:45*, <u>7:00</u>, 7:35**, 8:00, 8:30*', earlier: '6:20', days: 'aseres' },
  { label: 'ערב יו"כ', times: '7:00, 7:20*, <u>7:35</u>, 8:00**, 8:20' },
];

const SLICHOS_TEXT = { title: 'סליחות' };

/** One line's times, split into the pieces the poster draws.
 *
 *  Reads the same notation a chart cell uses, so a row above can be written the way the
 *  board writes it: <u> for למטה, a trailing * for בעזרת נשים and ** for באולם השמחות.
 *  The marks come off the text and become flags, so the view decides how to draw them and
 *  the foot can count which ones are actually on the sheet. */
function parseTimes(str) {
  return String(str ?? '')
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => {
      const underlined = /^<u>.*<\/u>\**$/.test(part);
      const bare = part.replace(/<\/?u>/g, '');
      const stars = (bare.match(/\*+$/) || [''])[0];
      return { text: bare.slice(0, bare.length - stars.length), underlined, mark: stars };
    });
}

/** The finished poster for one Hebrew year.
 *
 *  The year is the שבת קיץ / שבת חורף year the sheet was generated for. סליחות and עשי"ת
 *  both sit at the very start of a Hebrew year, so this is the year they belong to. */
function buildSlichosPoster(hebrewYearNum) {
  if (!hebrewYearNum) return null;
  const days = posterDays(hebrewYearNum);
  const rows = SLICHOS_ROWS.map((row) => ({
    label: row.label,
    times: parseTimes(row.times),
    note: row.days ? kriasHatorahNote(days[row.days], row.earlier) : '',
  }));
  const all = rows.flatMap((r) => r.times);

  // Only the marks that are actually on this poster get explained, same as שבת שובה. The
  // two star notes share a line and sit in the order the printed chart's footer has them.
  //
  // Each line carries the direction it has to be set in, because they do not agree. The
  // underline line is an English sentence with Hebrew in it and is left to right; the star
  // line is Hebrew and is right to left, and setting it the other way puts the star on the
  // far side of the phrase instead of against the word it belongs to. Same split as the
  // week card's legend in week-view.js, and the same as the printed chart's own footer.
  const stars = [];
  if (all.some((t) => t.mark === '*')) stars.push('*בעזרת נשים');
  if (all.some((t) => t.mark === '**')) stars.push('**באולם השמחות');
  return {
    hebrewYear: hebrewYearNum,
    rows,
    days,
    legend: [
      all.some((t) => t.underlined)
        ? { dir: 'ltr', text: 'All underlined מנינים will be בבית מדרש למטה' } : null,
      stars.length ? { dir: 'rtl', text: stars.join(' ') } : null,
    ].filter(Boolean),
  };
}

// ==== ui/posters-view.js ====
// Posters: the sheets the shul hangs that are not the zmanim board.
//
// Two so far, שבת שובה and סליחות, and the tab is shaped for the others to follow rather
// than built around either: pick a poster, pick what it should be built from, and Print
// sends what is on the screen. Announcements and the Yom Tov schedules land here next.
//
// What a poster is built from differs, so a poster says for itself. שבת שובה comes from a
// generated sheet, because it reads its times out of that sheet's מנחה cell; סליחות comes
// from a Hebrew year, because its times are the shul's own fixed מנין slots and what the
// calendar decides is which days each line covers. Both answer sources(), so the picker
// does not need to know which kind it is looking at.
//
// A poster is a real 8.5in by 11in page in the document, the same way a chart page is, so
// what is on the screen is what comes out of the printer and there is no second layout to
// keep in step. See .poster in app.css and the @page rule in print.css.








/** Times New Roman, the face the Word posters the shul already hangs were set in. Fixed
 *  rather than taken from the sheet style: a poster is its own document and does not
 *  change when somebody picks a different font for the board. fontStackFor() adds the
 *  shipped stand-in behind it, so an Android phone with no Times New Roman still gets a
 *  serif Hebrew rather than falling back to a sans. */
const POSTER_FONT = 'Times New Roman';

/** The Hebrew years to offer the סליחות poster.
 *
 *  Every year a sheet has been generated for, plus the year we are in now and the one
 *  after it, so the poster can be printed before this year's chart exists. סליחות falls in
 *  the first days of a Hebrew year, so the year on the poster is the year it starts. */
function posterYears(state) {
  const now = hebrewDateExtended(excelSerial(new Date())).year;
  const years = new Set([now, now + 1]);
  for (const sheet of state.sheets) if (sheet.hebrewYear) years.add(Number(sheet.hebrewYear));
  return [...years].sort((a, b) => a - b);
}

/** The posters this tab knows how to draw. One entry per poster: what to call it, what it
 *  can be built from, and how to draw it. A source is one option in the picker, carrying
 *  its own build() so this table is the only place that knows what a given poster needs. */
const POSTERS = [
  {
    key: 'shuva',
    label: 'שבת שובה דרשה',
    sourceLabel: 'From',
    empty: 'No generated chart covers שבת שובה yet. Generate the season that holds it and this fills in.',
    sources: (state, settings) =>
      state.sheets.filter((s) => shuvaWeekOf(s)).map((s) => ({
        id: s.id,
        label: `${s.season} ${s.hebrewYear}`,
        build: () => buildShuvaPoster(s, state, settings),
      })),
    render: renderShuvaPoster,
  },
  {
    key: 'slichos',
    label: 'סליחות',
    sourceLabel: 'Year',
    empty: 'No year to build from.',
    sources: (state) =>
      posterYears(state).map((y) => ({
        id: String(y),
        label: `${hebrewYear(y)} (${y})`,
        build: () => buildSlichosPoster(y),
      })),
    render: renderSlichosPoster,
  },
];

function esc(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/** One time as the boards write it: plain is the main בית מדרש, underlined is למטה, a
 *  trailing * is בעזרת נשים and ** is באולם השמחות. The same marks as the chart, so
 *  somebody holding a poster and a board is reading one system. */
function timeHtml(t) {
  const body = t.underlined ? `<u>${esc(t.text)}</u>` : esc(t.text);
  return `${body}${esc(t.mark || '')}`;
}

/** The page every poster is drawn on: the letterhead, the rabbi's line under it, whatever
 *  the poster itself puts in the middle, and the key to the marks at the foot.
 *
 *  Shared so the two posters cannot drift apart on the parts that are the shul rather than
 *  the occasion. */
function posterShell(settings, body, legend = []) {
  const rabbi = String(settings.headerRabbiLine || '').split('\n').filter(Boolean);
  return `<div class="poster" dir="rtl" style="--poster-font-family: ${esc(fontStackFor(POSTER_FONT))}">
    <img class="poster-wordmark" src="assets/logo-text.png"
         alt="${esc(settings.shulName)}"${hebrewLang(settings.shulName)} width="1776" height="237">
    <div class="poster-subtitle"${hebrewLang(settings.headerSubtitle)}>${esc(settings.headerSubtitle)}</div>
    <img class="poster-rule" src="assets/poster-rule.png" alt="" width="1897" height="85">
    <div class="poster-rabbi">${rabbi.map((l) => `<div${hebrewLang(l)}>${esc(l)}</div>`).join('')}</div>
    ${body}
    ${legend.length
      ? `<div class="poster-legend">${legend
          .map((l) => `<div dir="${l.dir}"${hebrewLang(l.text)}>${esc(l.text)}</div>`).join('')}</div>`
      : ''}
  </div>`;
}

function renderShuvaPoster(poster, settings) {
  const body = `
    <h2 class="poster-title" lang="he">${esc(SHUVA_TEXT.title)}</h2>
    ${SHUVA_TEXT.lines.map((l) => `<p class="poster-line" lang="he">${esc(l)}</p>`).join('')}
    ${poster.drasha ? `<p class="poster-at" lang="he">${esc(SHUVA_TEXT.at)} <bdi>${esc(poster.drasha)}</bdi></p>` : ''}
    <p class="poster-mincha" lang="he">${esc(SHUVA_TEXT.minchaLabel)}
      <bdi>${poster.mincha.map(timeHtml).join(', ')}</bdi></p>`;
  return posterShell(settings, body, poster.legend);
}

/** The סליחות sheet: one line per part of the yomim noraim, each a label and its מנינים.
 *
 *  The times run left to right inside a right-to-left line, so each list is its own <bdi>.
 *  So is the note in brackets, which is Hebrew with a time inside it: without the isolate
 *  the bracket and the time swap ends. Measured rather than reasoned about, the same as
 *  every other bidi decision in this project. */
function renderSlichosPoster(poster, settings) {
  const rows = poster.rows.map((r) => `
    <p class="poster-row" lang="he">
      <span class="poster-row-label">${esc(r.label)}</span>
      <bdi class="poster-row-times">${r.times.map(timeHtml).join(', ')}</bdi>
      ${r.note ? `<bdi class="poster-row-note">${esc(r.note)}</bdi>` : ''}
    </p>`).join('');
  const body = `<h2 class="poster-title" lang="he">${esc(SLICHOS_TEXT.title)}</h2>
    <div class="poster-rows">${rows}</div>`;
  return posterShell(settings, body, poster.legend);
}

let chosen = POSTERS[0].key;
let chosenSourceId = null;
let fitHandler = null;

/** Shrinks the poster until it fits across the screen, which on a phone it does not: the
 *  page is a real 8.5in and a 375px display is less than half of that, so without this the
 *  tab opens onto a strip of the sheet with the rest off the side.
 *
 *  Same mechanism as the charts' Fit to screen, and for the same reason: `zoom` shrinks the
 *  box as well as the paint, while `transform: scale` only paints smaller and leaves the
 *  full-size footprint behind, which is the overflow all over again. print.css forces
 *  `zoom: 1` back on, so what is on paper is always the full 8.5in.
 *
 *  No button beside it, unlike the charts. There is one page and nothing to choose. */
function fitPoster(container) {
  const el = container.querySelector('.poster');
  if (!el) return;
  const decide = () => {
    el.style.zoom = ''; // always measure unscaled
    const box = el.parentElement;
    const cs = getComputedStyle(box);
    const avail = box.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
    const wide = el.getBoundingClientRect().width;
    if (avail > 0 && wide > avail) el.style.zoom = Math.max(0.15, avail / wide);
  };
  decide();
  // Rotating a phone changes what fits. One listener, replaced each render so it always
  // points at the poster currently on screen.
  if (fitHandler) window.removeEventListener('resize', fitHandler);
  fitHandler = () => { if (document.body.contains(el)) decide(); };
  window.addEventListener('resize', fitHandler);
}

function renderPosters(container, state) {
  const settings = resolveSettings(state.settings);
  const poster = POSTERS.find((p) => p.key === chosen) || POSTERS[0];
  const sources = poster.sources(state, settings);
  const source = sources.find((s) => s.id === chosenSourceId) || sources[0] || null;
  const built = source ? source.build() : null;

  container.className = 'is-sheet-view';
  container.innerHTML = `
    <h2 class="no-print">Posters</h2>
    <p class="hint no-print">The sheets the shul hangs that are not the zmanim board. What changes with the year is worked out rather than typed, so a poster is right the year it is printed and every year after.</p>
    <div class="poster-bar no-print">
      <label>Poster
        <select id="poster-pick">
          ${POSTERS.map((p) => `<option value="${p.key}" ${p.key === poster.key ? 'selected' : ''}>${esc(p.label)}</option>`).join('')}
        </select>
      </label>
      ${sources.length > 1
        ? `<label>${esc(poster.sourceLabel)}
             <select id="poster-source">
               ${sources.map((s) => `<option value="${esc(s.id)}" ${source && s.id === source.id ? 'selected' : ''}>${esc(s.label)}</option>`).join('')}
             </select>
           </label>`
        : ''}
      ${built ? printButtonHtml() : ''}
    </div>
    ${built ? poster.render(built, settings) : `<p class="hint no-print">${esc(poster.empty)}</p>`}`;

  container.querySelector('#poster-pick')?.addEventListener('change', (e) => {
    chosen = e.target.value;
    chosenSourceId = null;
    renderPosters(container, state);
  });
  container.querySelector('#poster-source')?.addEventListener('change', (e) => {
    chosenSourceId = e.target.value;
    renderPosters(container, state);
  });
  if (built) {
    wirePrintButton(container);
    fitPoster(container);
  }
}

// ==== ui/program-view.js ====
// The "download the program" page. The same boards and the same numbers as this site, as a
// program that runs on its own with no browser and nothing to install.
//
// The files are Release assets on the repository rather than files served from this site.
// Two reasons: a 40MB program per platform does not belong in a repository that GitHub Pages
// serves, and the `latest` link means a new build reaches people without this page being
// edited. The names are fixed for the same reason.

const RELEASES = 'https://github.com/cheskyshain-stack/zmanim-tool/releases';
const LATEST = `${RELEASES}/latest/download`;
// The browser copy, built by build-offline.py and zipped by the release workflow.
const OFFLINE_FILE = 'Zmanim-offline.zip';

const DOWNLOADS = [
  {
    key: 'windows',
    file: 'Zmanim.exe',
    label: 'Windows',
    detail: 'Any Windows 10 or 11 computer, 64 bit.',
  },
  {
    key: 'mac-apple',
    file: 'Zmanim-mac-apple.zip',
    label: 'Mac, Apple silicon',
    detail: 'A Mac from late 2020 onwards: M1, M2, M3, M4.',
  },
  {
    key: 'mac-intel',
    file: 'Zmanim-mac-intel.zip',
    label: 'Mac, Intel',
    detail: 'An older Mac, before Apple silicon.',
  },
];

/** Which of the three to put first.
 *
 *  Windows and Mac are told apart reliably. Which *kind* of Mac is not: every browser on an
 *  Apple silicon Mac still reports "Intel Mac OS X" for compatibility, so guessing would send
 *  half of them to a build that cannot run. A Mac gets both, and is told where to look.
 *
 *  A phone is detected so it can be told plainly that there is nothing here for it, rather
 *  than being handed a Windows program it will download and be unable to open.
 */
function detectPlatform(ua = navigator.userAgent, touchPoints = navigator.maxTouchPoints || 0) {
  if (/Android/i.test(ua)) return 'phone';
  // An iPad in its default mode reports the same user agent as a Mac. The touch points are
  // what separate them: a Mac reports 0.
  if (/iPhone|iPod|iPad/i.test(ua) || (/Macintosh/i.test(ua) && touchPoints > 1)) return 'phone';
  if (/Macintosh|Mac OS X/i.test(ua)) return 'mac';
  if (/Windows/i.test(ua)) return 'windows';
  return 'other';
}

function downloadRow(item, isLead) {
  return `
    <a class="dl-row ${isLead ? 'is-lead' : ''}" href="${LATEST}/${item.file}" download>
      <span class="dl-what">
        <strong>${item.label}</strong>
        <span class="hint">${item.detail}</span>
      </span>
      <span class="dl-go">Download</span>
    </a>`;
}

function renderProgram(container, platform = detectPlatform()) {
  // A Mac leads with both of its own, in the order most Macs now are.
  const order = {
    windows: ['windows', 'mac-apple', 'mac-intel'],
    mac: ['mac-apple', 'mac-intel', 'windows'],
    phone: ['windows', 'mac-apple', 'mac-intel'],
    other: ['windows', 'mac-apple', 'mac-intel'],
  }[platform];
  const leads = platform === 'mac' ? 2 : platform === 'windows' ? 1 : 0;
  const rows = order
    .map((key) => DOWNLOADS.find((d) => d.key === key))
    .map((item, i) => downloadRow(item, i < leads))
    .join('');

  const phoneNote =
    platform === 'phone'
      ? `<p class="dl-warn"><strong>You are on a phone or tablet.</strong> Everything here is meant for a computer: the programs below cannot run on a phone at all, and tapping a link downloads a file it can do little with. Open this page on the computer you want it on.</p>`
      : '';

  container.innerHTML = `
    <h2>Get the program</h2>
    <p class="hint">The same boards, to keep on a computer of your own.</p>

    <div class="guide-lede">
      <!-- Each Hebrew name in its own bdi. Written plainly, the comma between the two is a
           neutral character, so it is swallowed into one right to left run and the pair comes
           out reversed: measured, חורף landed at x=865 and קיץ at x=944, the wrong way round. -->
      <p>Everything on this site, to keep on a computer of your own: the same <bdi>שבת קיץ</bdi>, <bdi>שבת חורף</bdi> and Weekday charts, the same week cards, the same rules and the same numbers, worked out by the same calculations.</p>
      <p>Both ways below need <strong>no internet and nothing installed</strong>, and both carry the whole thing on a USB stick. Worth having for a computer where this site is blocked, and for making a board somewhere with no signal.</p>
    </div>

    ${phoneNote}

    <h3 class="dl-heading dl-heading-first">Opens in a browser</h3>
    <p class="hint">A folder you open in whatever browser is already on the computer. The simplest of the two: nothing to get past on the first run, a quarter of the size, and it works on any computer at all, including one with no build of its own below and one where you are not allowed to run a program you downloaded.</p>
    <div class="dl-list">
      <a class="dl-row" href="${LATEST}/${OFFLINE_FILE}" download>
        <span class="dl-what">
          <strong>Any computer, in a browser</strong>
          <span class="hint">About 260 KB. Unzip it, then open <code>index.html</code>.</span>
        </span>
        <span class="dl-go">Download</span>
      </a>
    </div>
    <p class="hint">It is the whole thing, not a cut down one: generating, typing over cells, rules, printing, backups. It keeps its work in the browser it is opened in, so the same folder on the same stick opens with your boards on the computer you last used it on and empty on a new one. Move work between them with <strong>Settings, Backup, Export</strong>. Publishing to the congregation's page needs the internet, so it does not work with none.</p>

    <details class="panel dl-programs">
      <summary>Or the program, which needs no browser either</summary>
      <div class="panel-body">
        <p class="hint">A single file that opens on its own, like any other program on the computer. Worth it over the browser copy for two things: it keeps its boards beside itself, so a USB stick carries your work and not just the program, and it opens like anything else on the machine. The cost is that it is built for one kind of computer at a time and the machine will refuse it the first time.</p>
        <div class="dl-list">${rows}</div>
        <p class="hint">Not sure which Mac: <strong>Apple menu, then About This Mac</strong>. If it names an M1, M2, M3 or M4, take the Apple silicon one. An Apple silicon Mac will also run the Intel build, but an Intel Mac cannot run the Apple silicon one.</p>
      </div>
    </details>

    <details class="panel" ${platform === 'windows' || platform === 'mac' ? 'open' : ''}>
      <summary>The program will refuse to open the first time. Here is why, and what to press</summary>
      <div class="panel-body">
        <p>None of the three programs is signed with a paid developer certificate, so the computer does not recognise who made it and says so the first time. Nothing is wrong with the file. It is <strong>once per computer</strong>, not every time. The browser copy has nothing to get past.</p>
        <p><strong>Windows.</strong> A blue box says "Windows protected your PC". Press <strong>More info</strong>, then <strong>Run anyway</strong>. If it will not start at all, right click the file, choose Properties, tick <strong>Unblock</strong>, then OK.</p>
        <p><strong>Mac.</strong> Unzip it, then open <code>Zmanim.app</code>. macOS refuses the first time. Go to <strong>System Settings</strong>, then <strong>Privacy &amp; Security</strong>, scroll down to the line naming Zmanim, and press <strong>Open Anyway</strong>. Then open it again.</p>
        <p>Antivirus software sometimes flags programs packed this way. It may need allowing through.</p>
      </div>
    </details>

    <details class="panel">
      <summary>On a USB stick, and where your work is kept</summary>
      <div class="panel-body">
        <p><strong>The program</strong> keeps its boards, rules and settings on the stick, beside itself, so the same stick opens with all your work on any computer you carry it to. Otherwise it keeps them in the usual per-user place on that computer.</p>
        <p><strong>The browser copy</strong> does not. A browser keeps its storage per computer, so carrying that folder carries the program but not the boards: it opens with your work on the computer you last used it on, and empty on a new one. That is the one real difference between the two.</p>
        <p>Its backup file is the same one this site's <strong>Settings, Backup, Export</strong> writes, so work moves either way: a backup made here opens there, and one made there opens here.</p>
        <p>Emailing the program does not work. Gmail refuses <code>.exe</code> attachments and looks inside zips, and most other mail does the same. Use the stick, or a shared link.</p>
      </div>
    </details>

    <details class="panel">
      <summary>What it can do, and what it cannot</summary>
      <div class="panel-body">
        <p>Everything this site does: generate a season, type over any cell, rules, undo and redo, the week's two cards, printing and saving a PDF, backups, and publishing to the congregation's page. It publishes to the same place this site does, so the two can be used side by side.</p>
        <p>It is checked hard before it is handed over. Every build runs the full test suite on the machine that builds it, against the reference output of this site's own engine, and then <strong>starts the program it just made</strong> and has it draw a board, write a PDF and write its save file. A build that cannot do that is not offered here.</p>
        <p>What it does not have: this site is what the congregation sees, and it is the one that stays up to date by itself.</p>
      </div>
    </details>

    <p class="hint"><a href="${RELEASES}" target="_blank" rel="noopener">Every version, with what changed</a>. The links above always fetch the newest.</p>
  `;
}

// ==== publish.js ====
// Publishing a season for the congregation.
//
// Everything in this app lives in one browser's localStorage, so a visitor's browser has
// nothing to show. Publishing writes the season into a file that ships with the site, at
// data/published.json, which the luach (index.html?luach) reads instead of
// localStorage. That is the whole mechanism: no backend, no login, no database.
//
// A season is published once. The luach then advances by itself every week, because the
// week it shows is worked out from today's date against the weeks in the file.

/** What the luach needs, and nothing else.
 *
 *  The sheets are carried whole (weeks and overrides included) rather than as
 *  pre-rendered times, so the luach runs the same code the app does and a manual edit or
 *  a rule shows up there exactly as it does here. Rules travel too, for the same reason.
 *  Settings are trimmed to what the card actually prints: no location maths is redone on
 *  the luach, but the header, footer and שחרית schedules are all read from here. */
function buildPublishedPayload(state, sheets) {
  return {
    version: 1,
    publishedAt: new Date().toISOString(),
    settings: state.settings,
    rules: state.rules,
    sheets: sheets.map((s) => ({
      id: s.id,
      season: s.season,
      hebrewYear: s.hebrewYear,
      // Carried across because the luach sorts on it: where two published sheets both
      // cover a week, the most recently generated one wins. Left out, every sheet sorted
      // as undefined and the winner came down to the order they happened to be published
      // in, which is not a rule anyone could predict.
      createdAt: s.createdAt,
      linkedSheetId: s.linkedSheetId,
      weeks: s.weeks,
      pageSizes: s.pageSizes,
      overrides: s.overrides || {},
    })),
  };
}

/** The Shabbos sheets worth publishing, newest first, each with its weekday companion. */
function publishableGroups(state) {
  return state.sheets
    .filter((s) => s.season !== 'weekday')
    .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)))
    .map((sheet) => ({
      sheet,
      weekday: state.sheets.find((s) => s.season === 'weekday' && s.linkedSheetId === sheet.id) || null,
    }));
}

function downloadPublished(payload) {
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'published.json';
  a.click();
  URL.revokeObjectURL(url);
}

/** Reads what is currently published, or null when nothing is. A 404 is the normal state
 *  before the first publish, not an error worth shouting about. */
async function loadPublished() {
  try {
    const res = await fetch('/data/published.json', { cache: 'no-cache' });
    if (!res.ok) return null;
    const data = await res.json();
    return data && Array.isArray(data.sheets) && data.sheets.length ? data : null;
  } catch {
    return null;
  }
}

// --- Publishing straight to the site ------------------------------------------------
//
// The site is static files in a GitHub repository, so "publish" means committing
// data/published.json to that repository. A browser can do that through GitHub's own
// API, which needs a token to prove it is allowed to.
//
// The token is kept under its own localStorage key rather than inside the app state, so
// it can never ride along in an exported backup. A backup gets shared; a write token
// must not.

const REPO_OWNER = 'cheskyshain-stack';
const REPO_NAME = 'zmanim-tool';
const REPO_BRANCH = 'main';
const PUBLISH_PATH = 'data/published.json';
const TOKEN_KEY = 'zmanim-publish-token';

function getPublishToken() {
  try {
    return localStorage.getItem(TOKEN_KEY) || '';
  } catch {
    // A browser that refuses storage has no token to give. The admin app is the only
    // thing that asks, and it will say the token is missing rather than fall over.
    return '';
  }
}

function setPublishToken(token) {
  try {
    if (token) localStorage.setItem(TOKEN_KEY, token.trim());
    else localStorage.removeItem(TOKEN_KEY);
  } catch {
    // Nothing to do: publishing this session still works, the token just will not be
    // remembered for the next one.
  }
}

/** UTF-8 safe base64, which is what the API wants the file contents as. btoa alone
 *  throws on any Hebrew character, and this file is full of them. */
function toBase64(text) {
  const bytes = new TextEncoder().encode(text);
  let binary = '';
  // In chunks: apply() on a 100KB array overflows the argument limit.
  for (let i = 0; i < bytes.length; i += 8192) binary += String.fromCharCode(...bytes.subarray(i, i + 8192));
  return btoa(binary);
}

async function api(path, token, options = {}) {
  return fetch(`https://api.github.com/repos/${REPO_OWNER}/${REPO_NAME}/${path}`, {
    ...options,
    headers: {
      Accept: 'application/vnd.github+json',
      Authorization: `Bearer ${token}`,
      'X-GitHub-Api-Version': '2022-11-28',
      ...(options.headers || {}),
    },
  });
}

/** Whatever is published right now, straight from the repository rather than from the
 *  deployed site, so it is accurate the moment after a publish instead of a minute
 *  later. Returns { data, sha } with data null when nothing is published yet. */
async function fetchPublished(token) {
  const res = await api(`contents/${PUBLISH_PATH}?ref=${REPO_BRANCH}`, token);
  if (res.status === 404) return { data: null, sha: undefined };
  if (res.status === 401) throw new Error('That token was refused. It may be wrong, expired, or revoked.');
  if (res.status === 403) throw new Error('That token is not allowed to read this repository.');
  if (!res.ok) throw new Error(`GitHub replied ${res.status} when reading what is published.`);
  const body = await res.json();
  // The API returns base64 wrapped across lines, which atob will not accept as-is.
  const text = new TextDecoder().decode(Uint8Array.from(atob(body.content.replace(/\s/g, '')), (c) => c.charCodeAt(0)));
  return { data: JSON.parse(text), sha: body.sha };
}

async function commit(json, sha, message, token) {
  const res = await api(`contents/${PUBLISH_PATH}`, token, {
    method: 'PUT',
    body: JSON.stringify({ message, content: toBase64(json), branch: REPO_BRANCH, ...(sha ? { sha } : {}) }),
  });
  if (res.status === 401 || res.status === 403) throw new Error('That token is not allowed to write to this repository.');
  if (!res.ok) {
    let detail = '';
    try {
      detail = (await res.json()).message || '';
    } catch {
      /* the body is not always JSON */
    }
    throw new Error(`GitHub refused the change (${res.status})${detail ? ': ' + detail : ''}.`);
  }
}

/** Two sheets are the same season in the same year, and so replace each other. */
const sameSeason = (a, b) => a.season === b.season && a.hebrewYear === b.hebrewYear;

/** Publishes a season, keeping every other season already published.
 *
 *  A year needs both קיץ and חורף, so publishing one must not remove the other: this
 *  replaces only the entry for the same season and year, which is what makes a corrected
 *  chart supersede the one before it. Settings and rules come from this publish, since
 *  they are shul-wide rather than per season. */
async function publishToSite(payload, token) {
  if (!token) throw new Error('No publishing token set. Add one in Settings, under Publishing.');
  const { data, sha } = await fetchPublished(token);
  const existing = data?.sheets || [];

  // Only Shabbos sheets identify a season. Every weekday chart carries season 'weekday',
  // so comparing those by season and year matched קיץ's weekday against חורף's and
  // quietly deleted one: a weekday chart belongs to whichever Shabbos sheet it was
  // generated with, and is replaced only when that sheet is.
  const incomingSeasons = payload.sheets.filter((s) => s.season !== 'weekday');
  const replacedIds = new Set(
    existing.filter((s) => s.season !== 'weekday' && incomingSeasons.some((i) => sameSeason(i, s))).map((s) => s.id)
  );
  const keep = existing.filter((s) =>
    s.season === 'weekday' ? !replacedIds.has(s.linkedSheetId) : !incomingSeasons.some((i) => sameSeason(i, s))
  );

  const merged = { ...payload, sheets: [...keep, ...payload.sheets] };
  const label = incomingSeasons[0];
  await commit(JSON.stringify(merged, null, 2), sha, `Publish ${label?.season || 'season'} ${label?.hebrewYear || ''}`, token);
  return data ? 'updated' : 'created';
}

/** Takes one season back off the congregation's page, leaving the others published. */
async function unpublishFromSite(sheet, token) {
  if (!token) throw new Error('No publishing token set. Add one in Settings, under Publishing.');
  const { data, sha } = await fetchPublished(token);
  if (!data) throw new Error('Nothing is published.');
  const remaining = data.sheets.filter((s) => !sameSeason(s, sheet) && !(s.season === 'weekday' && s.linkedSheetId === sheet.id));
  await commit(JSON.stringify({ ...data, sheets: remaining }, null, 2), sha, `Unpublish ${sheet.season} ${sheet.hebrewYear}`, token);
  return remaining.length;
}

// ==== ui/saved-sheets-view.js ====
const NEW_FOLDER = '__new__';
const NO_FOLDER = '__none__';

/** Pairs each Shabbos sheet with the Weekday chart generated alongside it.
 *
 *  They're two sheets because they're two printed charts with different columns, but
 *  nobody ever wants one without the other: they're generated together, they print
 *  interleaved, and each has a button to the other. Listing them as two rows just made
 *  the list twice as long and invited locking one while deleting the other. One row per
 *  pair, and lock / folder / delete act on both.
 *
 *  A Weekday chart whose partner was deleted (or that came from an older version with no
 *  link recorded) still gets its own row rather than vanishing from the list. */
function groupSheets(sheets) {
  const byId = new Map(sheets.map((s) => [s.id, s]));
  const companionOf = new Map();
  for (const s of sheets) {
    if (s.season === 'weekday' && byId.has(s.linkedSheetId)) companionOf.set(s.linkedSheetId, s);
  }
  const paired = new Set([...companionOf.values()].map((s) => s.id));
  return sheets.filter((s) => !paired.has(s.id)).map((s) => ({ primary: s, companion: companionOf.get(s.id) || null }));
}

function renderSavedSheets(container, state, onOpen, onDelete, onChange, onOpenPublish = null) {
  const groups = groupSheets(state.sheets);
  // Folders are just a name stored on each sheet - there's no separate folder list, so a
  // folder exists exactly as long as something is in it and disappears when the last
  // sheet leaves. Nothing to create, rename or tidy up separately. A pair is filed by
  // its Shabbos sheet; the Weekday chart follows it.
  const folders = [...new Set(groups.map((g) => g.primary.folder).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  const inFolder = (name) => groups.filter((g) => (g.primary.folder || '') === name);
  const unfiled = inFolder('');

  const rowsHtml = (list) =>
    [...list]
      // Newest first - the one you just generated is the one you want. Copied before
      // sorting so the stored order (which nothing else depends on) is left alone.
      .sort((a, b) => String(b.primary.createdAt).localeCompare(String(a.primary.createdAt)))
      .map(
        ({ primary: s, companion }) => `
        <tr data-id="${s.id}">
          <td data-label="Sheet">${s.locked ? '<span class="lock-mark" title="Locked">🔒</span> ' : ''}${SEASON_LABELS[s.season] || s.season}${
            companion ? ' <span class="pair-chip" title="Generated together; opening one gets you to the other">+ Weekday</span>' : ''
          }<span class="live-chip" data-live-for="${s.id}" hidden>Live</span></td>
          <td data-label="Hebrew year">${s.hebrewYear}</td>
          <td data-label="Weeks">${s.weeks.length}${companion ? ` <span class="hint">+ ${companion.weeks.length}</span>` : ''}</td>
          <td data-label="Created">${created(s.createdAt)}</td>
          <td data-label="Folder">
            <select class="folder-select" title="Move this sheet to a folder">
              <option value="${NO_FOLDER}" ${!s.folder ? 'selected' : ''}>No folder</option>
              ${folders.map((f) => `<option value="${esc(f)}" ${s.folder === f ? 'selected' : ''}>${esc(f)}</option>`).join('')}
              <option value="${NEW_FOLDER}">New folder…</option>
            </select>
          </td>
          <td>
            <button class="open-btn btn-primary">Open</button>
            ${
              s.season !== 'weekday' && getPublishToken()
                ? `<button class="publish-btn" title="Put this season on the congregation's page. Any other published season stays where it is.">Publish</button>`
                : ''
            }
            <button class="lock-btn" title="${s.locked ? 'Allow this sheet to be deleted again' : 'Protect this sheet from being deleted'}">${s.locked ? 'Unlock' : 'Lock'}</button>
            <button class="delete-btn btn-danger" ${s.locked ? 'disabled title="Unlock this sheet before deleting it"' : ''}>Delete</button>
          </td>
        </tr>`
      )
      .join('');

  const tableHtml = (list) => `<table class="saved-list"><thead><tr>
      <th>Sheet</th><th>Hebrew year</th><th>Weeks</th><th>Created</th><th>Folder</th><th></th>
    </tr></thead><tbody>${rowsHtml(list)}</tbody></table>`;

  container.innerHTML = `
    <h2>Saved sheets</h2>
    <p class="hint">Every sheet you've generated. Open one to edit or print it, lock it so it can't be deleted, or file it into a folder to keep the list tidy. A folder appears as soon as a sheet is put in one and goes away when the last sheet leaves it. A Shabbos sheet and the Weekday chart made with it count as one entry. Open either from the same row, and locking, filing or deleting covers both.</p>
    ${
      // The row's own Publish button puts one season up and nothing else. This goes to the
      // publishing panel, which is the place that shows what the congregation is looking
      // at right now and can take a season back down - and the place that tells you about
      // the token when there is no token, which is why it shows either way.
      onOpenPublish
        ? `<div class="actions"><button type="button" id="saved-publishing">Publishing${getPublishToken() ? '' : ' (no token set)'}</button></div>`
        : ''
    }
    ${
      state.sheets.length
        ? `
      ${unfiled.length ? tableHtml(unfiled) : ''}
      ${folders
        .map(
          (f) => `
        <details class="panel" open>
          <summary>📁 ${esc(f)} <span class="hint">(${inFolder(f).length} sheet${inFolder(f).length === 1 ? '' : 's'})</span></summary>
          <div class="panel-body">${tableHtml(inFolder(f))}</div>
        </details>`
        )
        .join('')}`
        : '<p class="hint">No saved sheets yet. Use Generate to create one.</p>'
    }
  `;

  // Which of these the congregation is actually looking at. Asked of the repository
  // rather than assumed, because a sheet can be published from another browser and a
  // stale badge on the wrong row is worse than no badge. Silent on failure: this is a
  // nice-to-know, not a reason to break the list.
  const refreshLive = async () => {
    if (!getPublishToken()) return;
    try {
      const { data } = await fetchPublished(getPublishToken());
      const live = data?.sheets || [];
      container.querySelectorAll('[data-live-for]').forEach((chip) => {
        const sheet = state.sheets.find((x) => x.id === chip.dataset.liveFor);
        if (!sheet) return;
        const seasonLive = live.some((p) => p.season === sheet.season && p.hebrewYear === sheet.hebrewYear);
        const thisOneLive = live.some((p) => p.id === sheet.id);
        chip.hidden = !seasonLive;
        chip.classList.toggle('is-superseded', seasonLive && !thisOneLive);
        chip.title = thisOneLive
          ? "This exact sheet is on the congregation's page"
          : 'This season is published, but from a different sheet than this one';
      });
    } catch {
      /* no badge rather than an error: the list itself is fine */
    }
  };
  refreshLive();

  // A row is a pair, so every action here works on the sheets in it, not just the one
  // the row is keyed by.
  const groupOf = (e) => groups.find((g) => g.primary.id === e.target.closest('tr').dataset.id);
  const sheetsOf = (e) => [groupOf(e).primary, groupOf(e).companion].filter(Boolean);

  container.querySelectorAll('.open-btn').forEach((btn) => {
    btn.addEventListener('click', (e) => onOpen(e.target.closest('tr').dataset.id));
  });
  // Publishing from the list, so any saved season can go up without first paging This
  // week around to a date inside it. One season per press, but pressing it on a second
  // season leaves the first alone: the published file holds them all.
  container.querySelectorAll('.publish-btn').forEach((btn) => {
    btn.addEventListener('click', async (e) => {
      const { primary, companion } = groupOf(e);
      const label = `${SEASON_LABELS[primary.season] || primary.season} ${primary.hebrewYear}`;
      if (!confirm(`Put ${label} on the congregation's page?`)) return;
      const was = btn.textContent;
      btn.disabled = true;
      btn.textContent = 'Publishing…';
      try {
        await publishToSite(buildPublishedPayload(state, [primary, companion].filter(Boolean)), getPublishToken());
        btn.textContent = 'Published';
        await refreshLive();
      } catch (err) {
        alert(err.message);
        btn.textContent = was;
      } finally {
        btn.disabled = false;
        setTimeout(() => (btn.textContent = was), 4000);
      }
    });
  });
  container.querySelector('#saved-publishing')?.addEventListener('click', () => onOpenPublish());
  container.querySelectorAll('.lock-btn').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      const locked = !groupOf(e).primary.locked;
      sheetsOf(e).forEach((s) => (s.locked = locked));
      onChange(); // persists and re-renders, so the row's buttons reflect the new state
    });
  });
  container.querySelectorAll('.folder-select').forEach((sel) => {
    sel.addEventListener('change', (e) => {
      const value = e.target.value;
      let folder;
      if (value === NEW_FOLDER) {
        folder = (prompt('Name for the new folder:') || '').trim();
        if (!folder) return onChange(); // cancelled - redraw so the select snaps back
      } else {
        folder = value === NO_FOLDER ? undefined : value;
      }
      sheetsOf(e).forEach((s) => (s.folder = folder));
      onChange();
    });
  });
  container.querySelectorAll('.delete-btn').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      const { primary, companion } = groupOf(e);
      if (primary.locked) return; // the button is disabled too; this is the belt-and-braces half
      const what = companion ? 'this sheet and its Weekday chart' : 'this saved sheet';
      if (confirm(`Delete ${what}?`)) onDelete(sheetsOf(e).map((s) => s.id));
    });
  });
}

/** "12 Aug 2026, 12:34 AM". toLocaleString() gives "8/12/2026, 12:34:30 AM", which is
 *  wide enough to wrap mid-date, and the seconds are noise: two sheets generated in the
 *  same minute are the pair from one run. */
function created(iso) {
  const d = new Date(iso);
  const date = d.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' });
  const time = d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
  return `${date}, ${time}`;
}

function esc(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// ==== ui/image-crop.js ====
// Basic pan-&-zoom image cropper for the header photo. No external library (this is a
// static, build-step-free app) - just a fixed-aspect viewport, a drag-to-reposition
// image, and a zoom slider, rendered onto a canvas at a fixed output size on save.
//
// renderImageCropper(container, currentDataUrl, onSave):
//   currentDataUrl - the saved custom photo (a data: URL) or null (using the default).
//   onSave(dataUrl | null) - called with a new cropped data: URL, or null if the user
//   removed the custom photo to go back to the bundled default.
function renderImageCropper(container, currentDataUrl, onSave) {
  // Matches assets/logo-building-icon.png's own aspect ratio, so a freshly cropped
  // photo sits in the header the same shape as the default did.
  const ASPECT = 155 / 90;
  const VIEW_W = 240;
  const VIEW_H = Math.round(VIEW_W / ASPECT);
  const OUT_W = 620; // rendered at ~2.5x the on-screen viewport for a crisp print output
  const OUT_H = Math.round(OUT_W / ASPECT);

  container.innerHTML = `
    <div class="crop-tool">
      <div class="crop-current-row">
        <img class="crop-current" src="${currentDataUrl || 'assets/logo-building-icon.png'}" alt="Current header photo">
        <div>
          <div class="hint">${currentDataUrl ? 'Custom photo' : 'Default photo (assets/logo-building-icon.png)'}</div>
          <label class="file-label">Choose a photo…<input type="file" id="crop-file" accept="image/*" hidden></label>
          ${currentDataUrl ? '<button type="button" id="crop-remove" class="btn-danger">Remove (use default)</button>' : ''}
        </div>
      </div>
      <div id="crop-editor" class="crop-editor" hidden>
        <div class="crop-viewport" id="crop-viewport" style="width:${VIEW_W}px;height:${VIEW_H}px;">
          <img id="crop-image" draggable="false" alt="">
        </div>
        <label class="crop-zoom">Zoom<input type="range" id="crop-zoom" min="1" max="3" step="0.01" value="1"></label>
        <p class="hint">Drag the photo to reposition it.</p>
        <div class="actions">
          <button type="button" id="crop-save" class="btn-primary">Use this photo</button>
          <button type="button" id="crop-cancel">Cancel</button>
        </div>
      </div>
    </div>
  `;

  const fileInput = container.querySelector('#crop-file');
  const editor = container.querySelector('#crop-editor');
  const viewport = container.querySelector('#crop-viewport');
  const imgEl = container.querySelector('#crop-image');
  const zoomInput = container.querySelector('#crop-zoom');

  let img = null;
  let naturalW = 0;
  let naturalH = 0;
  let baseScale = 1;
  let scale = 1;
  let left = 0;
  let top = 0;
  let dragging = false;
  let dragStartX = 0;
  let dragStartY = 0;
  let startLeft = 0;
  let startTop = 0;

  function clamp() {
    const dispW = naturalW * scale;
    const dispH = naturalH * scale;
    left = Math.min(0, Math.max(VIEW_W - dispW, left));
    top = Math.min(0, Math.max(VIEW_H - dispH, top));
  }
  function apply() {
    clamp();
    imgEl.style.width = naturalW * scale + 'px';
    imgEl.style.height = naturalH * scale + 'px';
    imgEl.style.left = left + 'px';
    imgEl.style.top = top + 'px';
  }
  function startDrag(x, y) {
    dragging = true;
    dragStartX = x;
    dragStartY = y;
    startLeft = left;
    startTop = top;
  }
  function moveDrag(x, y) {
    if (!dragging) return;
    left = startLeft + (x - dragStartX);
    top = startTop + (y - dragStartY);
    apply();
  }

  fileInput.addEventListener('change', () => {
    const file = fileInput.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      img = new Image();
      img.onload = () => {
        naturalW = img.naturalWidth;
        naturalH = img.naturalHeight;
        baseScale = Math.max(VIEW_W / naturalW, VIEW_H / naturalH); // "cover" the viewport
        scale = baseScale;
        left = (VIEW_W - naturalW * scale) / 2;
        top = (VIEW_H - naturalH * scale) / 2;
        imgEl.src = reader.result;
        zoomInput.value = '1';
        editor.hidden = false;
        apply();
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });

  zoomInput.addEventListener('input', () => {
    // Re-anchor on the viewport's center so zooming feels like it zooms "in place"
    // rather than yanking the image toward its top-left corner.
    const cx = VIEW_W / 2;
    const cy = VIEW_H / 2;
    const imgX = (cx - left) / scale;
    const imgY = (cy - top) / scale;
    scale = baseScale * Number(zoomInput.value);
    left = cx - imgX * scale;
    top = cy - imgY * scale;
    apply();
  });

  viewport.addEventListener('mousedown', (e) => startDrag(e.clientX, e.clientY));
  window.addEventListener('mousemove', (e) => moveDrag(e.clientX, e.clientY));
  window.addEventListener('mouseup', () => {
    dragging = false;
  });
  viewport.addEventListener('touchstart', (e) => startDrag(e.touches[0].clientX, e.touches[0].clientY), { passive: true });
  viewport.addEventListener('touchmove', (e) => moveDrag(e.touches[0].clientX, e.touches[0].clientY), { passive: true });
  viewport.addEventListener('touchend', () => {
    dragging = false;
  });

  container.querySelector('#crop-cancel').addEventListener('click', () => {
    editor.hidden = true;
    fileInput.value = '';
  });
  container.querySelector('#crop-save').addEventListener('click', () => {
    const canvas = document.createElement('canvas');
    canvas.width = OUT_W;
    canvas.height = OUT_H;
    const ctx = canvas.getContext('2d');
    const sx = -left / scale;
    const sy = -top / scale;
    const sw = VIEW_W / scale;
    const sh = VIEW_H / scale;
    ctx.drawImage(img, sx, sy, sw, sh, 0, 0, OUT_W, OUT_H);
    onSave(canvas.toDataURL('image/png'));
  });
  container.querySelector('#crop-remove')?.addEventListener('click', () => onSave(null));
}

// ==== ui/rules-view.js ====
/** @param {string|null} editingRuleId  id to edit, or 'new' for a blank Add form.
 *  Null (the default) shows just the list - most visits here are to glance at the
 *  rules, not write one, and the creation form used to sit open below them permanently. */
function renderRules(container, state, onChange, editingRuleId = null) {
  // Editing loads the rule's values into the same form used for adding; submitting
  // then updates that rule in place (keeping its id and enabled state) instead of
  // appending a new one.
  const cloneOf = typeof editingRuleId === 'string' && editingRuleId.startsWith('clone:') ? editingRuleId.slice(6) : null;
  const source = cloneOf ? state.rules.find((r) => r.id === cloneOf) : null;
  const editing = editingRuleId && editingRuleId !== 'new' && !cloneOf ? state.rules.find((r) => r.id === editingRuleId) : null;
  // Editing writes back to an existing rule; cloning only *prefills* from one and saves
  // as a new rule, so the two share every field below but differ on submit.
  const prefill = editing || source;
  const formOpen = editingRuleId !== null;
  container.innerHTML = `
    <h2>Rules</h2>
    <p class="hint">Reusable, recurring overrides. They apply automatically every time a sheet is generated (unlike per-cell overrides on a generated sheet, which are one-off). Match on the special-Shabbos name (e.g. שובה / הגדול), the parsha name, or "always", and replace one or more cells' text. Pick any column from either chart, so a single rule can cover both שבת קיץ and שבת חורף at once.</p>
    <div id="rules-list"></div>
    <div class="actions" id="rule-add-row" ${formOpen ? 'hidden' : ''}><button type="button" id="rule-add" class="btn-primary">+ Add a rule</button></div>
    <h3 id="rule-form-title" ${formOpen ? '' : 'hidden'}>${editing ? `Editing: ${esc(editing.name)}` : source ? `Duplicate of ${esc(source.name)}` : 'Add a rule'}</h3>
    <form id="rule-form" class="form-grid" ${formOpen ? '' : 'hidden'}>
      <label>Name<input name="name" required placeholder="e.g. שבת נחמו: מנחה" value="${editing ? esc(editing.name) : source ? esc(source.name + ' (copy)') : ''}"></label>
      <fieldset>
        <legend>When does this apply?</legend>
        <label><input type="checkbox" name="always" ${prefill?.condition.always ? 'checked' : ''}> Always (every week)</label>
        <label>Special-Shabbos name(s), comma-separated<input name="specialParsha" placeholder="e.g. שובה, הגדול" value="${prefill ? esc((prefill.condition.specialParsha || []).join(', ')) : ''}"></label>
        <label>Or parsha name(s), comma-separated<input name="parsha" placeholder="optional" value="${prefill ? esc((prefill.condition.parsha || []).join(', ')) : ''}"></label>
        <label>Or Hebrew date(s), comma-separated <span class="hint">(month-day, counting Nisan as 1; e.g. 5-9 is ט׳ באב. Recurs every year.)</span><input name="hebrewDate" placeholder="e.g. 5-9" value="${prefill ? esc((prefill.condition.hebrewDate || []).join(', ')) : ''}"></label>
      </fieldset>
      <fieldset>
        <legend>Which cell(s) to replace</legend>
        <p class="hint">Check the equivalent cell on both charts if it's the same real-world minyan (e.g. "Mincha Erev Shabbos" is column L on קיץ and column I on חורף). One rule then covers both, without touching any other cell.</p>
        ${columnChecklist('שבת קיץ', 'kayitz', KAYITZ_COLUMNS, prefill)}
        ${columnChecklist('שבת חורף', 'choref', CHOREF_COLUMNS, prefill)}
      </fieldset>
      <fieldset>
        <legend>What to do to the cell</legend>
        <label><input type="radio" name="mode" value="append" ${!prefill || prefill.mode !== 'replace' ? 'checked' : ''}> Add this text onto the computed value (e.g. add the word "דרשה" without losing the times)</label>
        <label><input type="radio" name="mode" value="replace" ${prefill?.mode === 'replace' ? 'checked' : ''}> Replace the cell's computed value entirely with this text</label>
        <label>Text<textarea name="value" rows="2" placeholder="דרשה" required>${prefill ? esc(prefill.value) : ''}</textarea></label>
      </fieldset>
      <div class="actions">
        <button type="submit" class="btn-primary">${editing ? 'Save changes' : 'Add rule'}</button>
        <button type="button" id="rule-edit-cancel" class="secondary-btn">Cancel</button>
      </div>
    </form>
  `;

  container.querySelector('#rule-edit-cancel').addEventListener('click', () => renderRules(container, state, onChange));
  container.querySelector('#rule-add').addEventListener('click', () => {
    renderRules(container, state, onChange, 'new');
    container.querySelector('#rule-form-title').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  });

  const list = container.querySelector('#rules-list');
  list.innerHTML = state.rules.length
    ? state.rules
        .map(
          (r) => `
      <div class="rule-row" data-id="${r.id}">
        <label><input type="checkbox" class="rule-enabled" ${r.enabled ? 'checked' : ''}></label>
        <div class="rule-summary">
          <strong>${esc(r.name)}</strong>
          <div class="hint">columns ${columnsOf(r)
            .map((c) => `<code><bdi>${esc(prettyColumn(c))}</bdi></code>`)
            .join(' ')} · ${conditionSummary(r.condition)} → ${r.mode === 'replace' ? 'replace with' : 'add'} "${esc(r.value)}"</div>
        </div>
        <div class="rule-actions">
          <button class="rule-edit" title="Edit this rule">Edit</button>
          <button class="rule-clone" title="Make a copy of this rule to adjust">Duplicate</button>
          <button class="rule-delete" title="Delete rule">Delete</button>
        </div>
      </div>`
        )
        .join('')
    : '<p class="hint">No rules yet.</p>';

  list.querySelectorAll('.rule-enabled').forEach((cb) => {
    cb.addEventListener('change', (e) => {
      const id = e.target.closest('.rule-row').dataset.id;
      state.rules.find((r) => r.id === id).enabled = e.target.checked;
      onChange();
    });
  });
  list.querySelectorAll('.rule-edit').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      renderRules(container, state, onChange, e.target.closest('.rule-row').dataset.id);
      container.querySelector('#rule-form-title').scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  });
  list.querySelectorAll('.rule-clone').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      renderRules(container, state, onChange, 'clone:' + e.target.closest('.rule-row').dataset.id);
      container.querySelector('#rule-form-title').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    });
  });
  list.querySelectorAll('.rule-delete').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      const id = e.target.closest('.rule-row').dataset.id;
      if (!confirm('Delete this rule?')) return;
      state.rules = state.rules.filter((r) => r.id !== id);
      onChange();
      renderRules(container, state, onChange);
    });
  });

  container.querySelector('#rule-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const fd = new FormData(e.target);
    const condition = {};
    if (fd.get('always') === 'on') condition.always = true;
    const specialParsha = splitCsv(fd.get('specialParsha'));
    const parsha = splitCsv(fd.get('parsha'));
    const hebrewDate = splitCsv(fd.get('hebrewDate'));
    if (specialParsha.length) condition.specialParsha = specialParsha;
    if (parsha.length) condition.parsha = parsha;
    if (hebrewDate.length) condition.hebrewDate = hebrewDate;
    const columnKeys = fd.getAll('columnKeys');
    if (!columnKeys.length) {
      alert('Pick at least one cell/column for this rule to affect.');
      return;
    }
    const data = {
      name: fd.get('name'),
      condition,
      columnKeys,
      mode: fd.get('mode') || 'append',
      value: fd.get('value'),
    };
    if (editing) {
      Object.assign(editing, data); // id and enabled stay as they were
    } else {
      state.rules.push({ id: newId('rule'), enabled: true, ...data });
    }
    onChange();
    renderRules(container, state, onChange);
  });
}

function columnChecklist(sheetLabel, seasonKey, columns, editing) {
  const checkedKeys = editing ? columnsOf(editing) : [];
  return `
    <div class="col-group">
      <div class="col-group-title">${sheetLabel}</div>
      ${columns
        .map(
          (c) =>
            `<label class="col-check"><input type="checkbox" name="columnKeys" value="${seasonKey}:${c.key}" ${checkedKeys.includes(`${seasonKey}:${c.key}`) ? 'checked' : ''}> ${esc(c.header.replace(/\n/g, ' '))} <span class="hint">(${c.key})</span></label>`
        )
        .join('')}
    </div>
  `;
}
function columnsOf(rule) {
  return Array.isArray(rule.columnKeys) ? rule.columnKeys : rule.columnKey ? [rule.columnKey] : [];
}
function prettyColumn(entry) {
  if (!entry.includes(':')) return entry;
  const [season, key] = entry.split(':');
  return (season === 'kayitz' ? 'קיץ' : 'חורף') + ' ' + key;
}
function splitCsv(str) {
  return (str || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
}
function conditionSummary(c) {
  const parts = [];
  if (c.always) parts.push('always');
  if (c.specialParsha) parts.push('special Shabbos: ' + c.specialParsha.join(', '));
  if (c.parsha) parts.push('parsha: ' + c.parsha.join(', '));
  if (c.dateISO) parts.push('date: ' + c.dateISO.join(', '));
  if (c.hebrewDate) parts.push('Hebrew date: ' + c.hebrewDate.join(', '));
  return parts.join(' or ') || '(no condition, never matches)';
}
function esc(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ==== ui/settings-view.js ====
function renderSettings(container, state, onSave, onStateReplaced, onRulesChange = () => {}) {
  const s = state.settings;
  container.innerHTML = `
    <h2>Settings</h2>
    <p class="hint">Mirrors the workbook's SETTINGS sheet. Saved in this browser.</p>
    <!-- Rules sit outside the form: they are saved as they are made, not by the Save
         button at the bottom, and a nested form is not valid HTML anyway. -->
    <details class="panel" id="rules-panel">
      <summary>Rules</summary>
      <div class="panel-body" id="rules-host"></div>
    </details>
    <form id="settings-form" class="form-grid">
      <details class="panel" open>
        <summary>Header &amp; footer</summary>
        <div class="panel-body">
        <p class="hint">The wordmark (assets/logo-text.png, pulled from the workbook) prints at the top of every page as-is. Replace that file to change it. The photo next to it can be replaced and cropped below without touching any files. Everything else here is plain editable text.</p>
        <div id="header-photo-cropper"></div>
        <label>Shul name (used in the Saved Sheets list)<input name="shulName" value="${esc(s.shulName)}"></label>
        <label>Header subtitle (under the logo)<input name="headerSubtitle" value="${esc(s.headerSubtitle)}"></label>
        <label>Header rabbi line (opposite side of the logo)<textarea name="headerRabbiLine" rows="2">${esc(s.headerRabbiLine)}</textarea></label>
        <label>Footer note<textarea name="footerNote" rows="2">${esc(s.footerNote)}</textarea></label>
        <label>Footer address<input name="footerAddress" value="${esc(s.footerAddress)}"></label>
      </div>
      </details>
      <details class="panel">
        <summary>Weekday chart defaults</summary>
        <div class="panel-body">
        <p class="hint">מנחה and מעריב on the Weekday chart start blank, because those times differ every week, so you type them straight into the cells on the sheet. שחרית is one fixed schedule printed the same on every week's row. The footer note below replaces the regular one above, only on the Weekday chart.</p>
        <p class="hint">This box, and every cell on a sheet, takes times as shorthand: type <strong>1220 130</strong> and it becomes <strong>12:20/1:30</strong> when you click away. Select text first to use the buttons below on it.</p>
        ${richTextToolbarHtml('Selected text:')}
        <div class="rt-field-label">שחרית schedule (every ordinary week)</div>
        <div id="weekday-shacharis-editor" class="cell richtext-field" contenteditable="true" dir="ltr">${s.weekdayShacharis}</div>
        <div class="rt-field-label">שחרית on ר"ח / בה"ב / תענית</div>
        <div id="weekday-shacharis-special-editor" class="cell richtext-field" contenteditable="true" dir="ltr">${s.weekdayShacharisSpecial}</div>
        <p class="hint">The printed chart shows both schedules together, with the ר"ח בה"ב ותענ"צ heading between them, exactly as before. Keeping them apart lets This week show the second one only on the weeks that actually have one of those days, and name which it is.</p>
        <label>Weekday chart footer note<textarea name="weekdayFooterNote" rows="3">${esc(s.weekdayFooterNote)}</textarea></label>
      </div>
      </details>
      <details class="panel">
        <summary>Location</summary>
        <div class="panel-body">
        <label>Location name<input name="locationName" value="${esc(s.locationName)}"></label>
        <label>Latitude<input name="latitude" type="number" step="any" value="${s.latitude}"></label>
        <label>Longitude<input name="longitude" type="number" step="any" value="${s.longitude}"></label>
        <label>Elevation (meters)<input name="elevation" type="number" step="any" value="${s.elevation}"></label>
        <label>Timezone<select name="timezoneId">${TIMEZONES.map((tz) => `<option value="${tz.id}" ${tz.id === s.timezoneId ? 'selected' : ''}>${esc(tz.label)}</option>`).join('')}</select></label>
      </div>
      </details>
      <details class="panel">
        <summary>Display</summary>
        <div class="panel-body">
        <label>Language
          <select name="language">
            <option value="he" ${s.language === 'he' ? 'selected' : ''}>עברית</option>
            <option value="en" ${s.language === 'en' ? 'selected' : ''}>English</option>
          </select>
        </label>
        <label><input type="checkbox" name="inIsrael" ${s.inIsrael ? 'checked' : ''}> Zmanim used in Eretz Yisroel</label>
      </div>
      </details>
      <details class="panel">
        <summary>Advanced zmanim settings (leave alone unless you know what you're doing)</summary>
        <div class="panel-body">
        <label>Horizon (degrees)<input name="horizon" type="number" step="any" value="${s.horizon}"></label>
        <label>Candle lighting (minutes before sunset)<input name="candleLightingMinutes" type="number" step="any" value="${s.candleLightingMinutes}"></label>
        <label>Ateret Torah Tzais offset (minutes)<input name="ateretTorahTzaisOffset" type="number" step="any" value="${s.ateretTorahTzaisOffset}"></label>
        <label><input type="checkbox" name="useAstronomicalChatzos" ${s.useAstronomicalChatzos ? 'checked' : ''}> Use astronomical chatzos for zmanim</label>
        <label><input type="checkbox" name="useElevation" ${s.useElevation ? 'checked' : ''}> Use elevation for zmanim calculation</label>
        <label><input type="checkbox" name="useGregorianBefore1582" ${s.useGregorianBefore1582 ? 'checked' : ''}> Use Gregorian dates before Oct 15, 1582</label>
      </div>
      </details>
      <div class="actions"><button type="submit" class="btn-primary">Save settings</button></div>
    </form>
    <form class="form-grid" id="settings-publish" onsubmit="return false">
      <details class="panel">
        <summary>Publishing</summary>
        <div class="panel-body">
        <p class="hint">Publishing puts the season on the congregation's page at <strong>lczmanim.cjaffa.com</strong>. It writes one file into the site, and GitHub needs a token to allow that.</p>
        <details class="panel">
          <summary>How to make the token</summary>
          <div class="panel-body">
            <ol class="guide-steps">
              <li>Sign in to <strong>github.com</strong>.</li>
              <li>Click your <strong>profile picture</strong>, top right, then <strong>Settings</strong>.</li>
              <li>Scroll to the very bottom of the left sidebar: <strong>Developer settings</strong>.</li>
              <li><strong>Personal access tokens</strong>, then <strong>Fine-grained tokens</strong>.</li>
              <li><strong>Generate new token</strong>.</li>
              <li>Name it anything, for example <code>zmanim publish</code>, and pick an expiry.
                <span class="hint">When it expires, publishing stops until you make a new one and paste it here. A year is reasonable.</span>
              </li>
              <li>Under <strong>Repository access</strong>, choose <strong>Only select repositories</strong> and pick <strong>zmanim-tool</strong>.</li>
              <li>Under <strong>Permissions</strong>, click <strong>+ Add permissions</strong>.
                <span class="hint">This is the step that is easy to miss: the list starts empty and says "No repository permissions added yet".</span>
              </li>
              <li>Search for <strong>Contents</strong>, tick it, and add it.</li>
              <li>Its dropdown will say <em>Read-only</em>. Change it to <strong>Read and write</strong>.
                <span class="hint">Metadata adds itself as Read-only. Leave it, it is required.</span>
              </li>
              <li><strong>Generate token</strong> at the bottom, and copy it straight away.
                <span class="hint">It starts with <code>github_pat_</code> and GitHub never shows it again.</span>
              </li>
              <li>Paste it below and press <strong>Save token</strong>.</li>
            </ol>
            <p class="hint">To check it worked, open <strong>This week</strong> and expand <em>Publish for the congregation</em>. A good token shows the publish button and, underneath, what is currently published. A bad one says so in plain words rather than failing quietly: "not allowed to write to this repository" means Contents was left on Read-only.</p>
          </div>
        </details>
        <p class="hint">The token is stored in this browser only, and deliberately kept out of the backup file, so exporting a backup never carries it. Anyone using this computer could take it and change the site, so do not set it on a shared machine. You can revoke it on GitHub at any time.</p>
        <label>Publishing token<input type="password" id="publish-token" autocomplete="off" placeholder="${getPublishToken() ? '' : 'github_pat_...'}" value="${getPublishToken()}"></label>
        <div class="backup-row">
          <button type="button" id="save-token-btn" class="btn-primary">Save token</button>
          <button type="button" id="clear-token-btn" class="btn-danger">Remove token</button>
        </div>
      </div>
      </details>
    </form>
    <form class="form-grid" id="settings-backup" onsubmit="return false">
      <details class="panel">
        <summary>Backup</summary>
        <div class="panel-body">
        <p class="hint">Everything lives in this browser only: settings, saved sheets, and rules. Export downloads it all as one file; Import restores it (e.g. to move to another computer or your phone). Import also takes a single-sheet file saved with "Save a copy" in Saved sheets, and adds it to what you already have rather than replacing anything.</p>
        <div class="backup-row">
          <button type="button" id="export-btn">Export backup</button>
          <label class="file-label" for="import-input">Import backup</label>
          <input id="import-input" type="file" accept="application/json" hidden>
        </div>
      </div>
      </details>
    </form>
  `;

  container.querySelector('#save-token-btn').addEventListener('click', () => {
    setPublishToken(container.querySelector('#publish-token').value);
    showToast(getPublishToken() ? 'Publishing token saved' : 'Publishing token removed');
  });
  container.querySelector('#clear-token-btn').addEventListener('click', () => {
    setPublishToken('');
    container.querySelector('#publish-token').value = '';
    showToast('Publishing token removed');
  });

  container.querySelector('#export-btn').addEventListener('click', () => exportStateToFile(state));
  container.querySelector('#import-input').addEventListener('change', async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const text = await file.text();
    try {
      // A single-sheet copy is added to what's already here; a full backup replaces it.
      if (isSheetFile(text)) {
        state.sheets.push(importSheetFromText(text));
        onStateReplaced();
        showToast('Sheet added');
      } else {
        Object.assign(state, importStateFromText(text));
        onStateReplaced();
        showToast('Backup restored');
      }
    } catch (err) {
      alert('Could not read that backup file: ' + err.message);
    }
    e.target.value = '';
  });
  renderImageCropper(container.querySelector('#header-photo-cropper'), s.headerIconImage, (headerIconImage) => {
    onSave({ ...s, headerIconImage }); // saves immediately, independent of the "Save settings" button below
  });

  // The Rules screen, whole, inside the first panel. It re-renders into its own host as
  // you add or edit a rule, which leaves the rest of Settings untouched.
  renderRules(container.querySelector('#rules-host'), state, onRulesChange);

  const shacharisEditor = container.querySelector('#weekday-shacharis-editor');
  const shacharisSpecialEditor = container.querySelector('#weekday-shacharis-special-editor');

  // One toolbar serves every rich-text box in the Weekday fieldset, acting on whichever
  // was last focused - tracked on focusin because the toolbar buttons deliberately don't
  // take focus (see wireRichTextToolbar).
  let lastRichField = shacharisEditor;
  container.addEventListener('focusin', (e) => {
    if (e.target.classList?.contains('richtext-field')) lastRichField = e.target;
  });
  wireRichTextToolbar(container, () => lastRichField);

  // Shorthand times settle when you leave a box, and Ctrl/Cmd+U underlines, in every one
  // of these boxes - including option rows added after this point, hence the delegation.
  container.addEventListener(
    'blur',
    (e) => {
      if (e.target.classList?.contains('richtext-field')) applyTimeShorthand(e.target);
    },
    true // blur doesn't bubble; capture is how a delegated listener sees it
  );
  container.addEventListener('keydown', (e) => {
    if (e.target.classList?.contains('richtext-field') && (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'u') {
      e.preventDefault();
      document.execCommand('underline');
    }
  });


  container.querySelector('#settings-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const fd = new FormData(e.target);
    const next = {
      ...s,
      shulName: fd.get('shulName'),
      headerSubtitle: fd.get('headerSubtitle'),
      headerRabbiLine: fd.get('headerRabbiLine'),
      footerNote: fd.get('footerNote'),
      footerAddress: fd.get('footerAddress'),
      weekdayShacharis: normalizeRichText(shacharisEditor.innerHTML),
      weekdayShacharisSpecial: normalizeRichText(shacharisSpecialEditor.innerHTML),
      weekdayFooterNote: fd.get('weekdayFooterNote'),
      locationName: fd.get('locationName'),
      latitude: Number(fd.get('latitude')),
      longitude: Number(fd.get('longitude')),
      elevation: Number(fd.get('elevation')),
      timezoneId: fd.get('timezoneId'),
      language: fd.get('language'),
      inIsrael: fd.get('inIsrael') === 'on',
      horizon: Number(fd.get('horizon')),
      candleLightingMinutes: Number(fd.get('candleLightingMinutes')),
      ateretTorahTzaisOffset: Number(fd.get('ateretTorahTzaisOffset')),
      useAstronomicalChatzos: fd.get('useAstronomicalChatzos') === 'on',
      useElevation: fd.get('useElevation') === 'on',
      useGregorianBefore1582: fd.get('useGregorianBefore1582') === 'on',
    };
    onSave(next);
    showToast('Settings saved');
  });
}

/** Saving re-renders this whole view, so any "saved!" state put on the button itself is
 *  wiped the instant it appears - which is exactly why the button felt like it did
 *  nothing. The confirmation lives on <body> instead, outside the part that re-renders. */
function showToast(message) {
  document.querySelector('.toast')?.remove();
  const el = document.createElement('div');
  el.className = 'toast no-print';
  el.textContent = message;
  document.body.appendChild(el);
  requestAnimationFrame(() => el.classList.add('toast-in'));
  setTimeout(() => {
    el.classList.remove('toast-in');
    setTimeout(() => el.remove(), 300);
  }, 2000);
}

function esc(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// ==== ui/week-view.js ====
// One week on its own page, for the congregation to read rather than for printing a
// season on a wall: the parsha at the top, then a row per minyan with its name on the
// right and its time on the left, running top to bottom.
//
// Nothing here is a new kind of saved sheet. A week card is the corresponding row of an
// already-generated chart, turned on its side: the chart's column headers become the row
// labels and the week's cells become the times. That means every manual edit, rule and
// override already in a sheet shows up here with no extra work, and the two can never
// drift apart.





















/** The ר"ח / בה"ב / תענית days falling in the week leading up to this Shabbos, named and
 *  with the day they fall on.
 *
 *  A week card is anchored on its Shabbos, and the weekday times are for the days before
 *  it, so this walks Sunday through Friday. Yom Kippur and Tisha B'Av are skipped: those
 *  have their own schedule entirely, and listing them beside a regular שחרית time would
 *  be worse than saying nothing. */

function specialDaysInWeek(shabbosSerial, settings) {
  // Grouped by name, so a two-day ראש חודש reads "ראש חדש חשון (Sunday, Monday)" rather
  // than naming the same month twice, and בה״ב lists its Monday and Thursday together.
  const byName = new Map();
  for (let offset = 6; offset >= 1; offset--) {
    const serial = shabbosSerial - offset;
    // offset 6 is the Sunday of that week, offset 1 the Friday.
    const day = DAY_NAMES[6 - offset];
    const names = [hasRoshChodesh(serial, settings), hasBehab(serial, settings), hasTaanis(serial, settings)].filter(Boolean);
    for (const name of names) {
      if (/יום כפור|Yom Kippur|תשעה באב|Tishah/.test(name)) continue;
      if (!byName.has(name)) byName.set(name, []);
      byName.get(name).push(day);
    }
  }
  return [...byName.entries()].map(([name, days]) => ({ name, day: days.join(', ') }));
}

/** Which of a week's two cards comes first: the שבת page or the חול page.
 *
 *  Its own localStorage key rather than a field in the app state, for two reasons. It is
 *  a view preference about how one person prints, not part of the shul's data, so it has
 *  no business travelling to the congregation inside published.json. And the
 *  congregation's page never loads the app state at all - it is built from the published
 *  file - so a setting kept there could not reach the very page this button is on. The
 *  publishing token is kept out on its own for a like reason. */
const CARD_ORDER_KEY = 'zmanim-week-card-order';

/** Reading and writing that one key, wrapped so that a browser refusing storage cannot
 *  take the page down with it.
 *
 *  localStorage is not always readable. Touching it from a page inside someone else's site
 *  throws outright where third party storage is blocked, which is now the default in most
 *  browsers, and it throws in a private window in some of them too. Unguarded, that landed
 *  in the middle of building the week and nothing rendered at all: measured, a week page
 *  in an iframe came up empty with "SecurityError: Failed to read the 'localStorage'
 *  property". Which page comes first is a preference; losing the whole schedule over it is
 *  not a trade worth making, so it falls back to the default and carries on. */
/** Which card a week leads with when nobody has said otherwise: the one whose times are
 *  the next to be used.
 *
 *  Sunday through Thursday that is the weekday card. From Friday it is the שבת card, and
 *  it stays the שבת card until Shabbos is out 72 minutes after שקיעה, at which point the
 *  page has already moved on to the coming week and its weekdays are what is next.
 *
 *  Read off the shul's clock rather than the browser's, the same as everything else that
 *  asks what time it is here. */
function autoCardOrder(state, settings) {
  try {
    const { serial, mins } = shulNow(new Date(), settings);
    const day = dateFromSerial(serial).getUTCDay();
    if (day === 5) return 'shabbos';
    // On Shabbos itself it stays the שבת card until the card is spent, the same moment the
    // page moves on to the next week. Read off the week's own last מנין rather than off a
    // clock, so the two cannot disagree about when Shabbos is done with.
    if (day === 6) return mins < weekEndsMins(serial, state, settings) ? 'shabbos' : 'weekday';
    return 'weekday';
  } catch {
    return 'shabbos';
  }
}

/** The order in force: whatever was picked, until the page has moved on from what it was
 *  picked for.
 *
 *  A pick is remembered against the week it was made on and the automatic answer it was
 *  made against, and it holds only while both still stand. So somebody on a Friday who
 *  wants the weekday times first keeps them for the rest of that Shabbos, and once the
 *  week rolls over the page is choosing for itself again.
 *
 *  Both halves are needed. Against the automatic answer alone a pick never really expires,
 *  because that answer only ever has two values and comes back round to the same one every
 *  Friday: a pick made one Friday would quietly reappear the next. Against the week alone
 *  it would survive Friday's turn from weekday to שבת within the same week, which is the
 *  one moment it most ought to give way.
 *
 *  Expiring at all is the point. This switch sits inside a panel most of the congregation
 *  will never open, and a pick kept for good would silently turn the whole thing off for
 *  anyone who ever touched it once. */
function cardOrder(showing, state, settings) {
  const auto = autoCardOrder(state, settings);
  try {
    const [pick, week, against] = (localStorage.getItem(CARD_ORDER_KEY) || '').split('|');
    if ((pick === 'shabbos' || pick === 'weekday') && week === String(showing) && against === auto) return pick;
  } catch {
    // Storage refused: the automatic answer is the answer.
  }
  return auto;
}

function rememberCardOrder(value, showing, state, settings) {
  try {
    localStorage.setItem(CARD_ORDER_KEY, `${value}|${showing}|${autoCardOrder(state, settings)}`);
  } catch {
    // Nothing to do: the choice still applies to this page, it just will not be
    // remembered next time.
  }
}

/** A setting with two answers, as a switch: both sides on the screen, the chosen one
 *  filled in and the fill sliding across when the other is pressed.
 *
 *  Written once and used for both settings in the panel. A dropdown hides one of two
 *  answers behind a tap, and on a phone opening it throws the system picker up over the
 *  page; a button that toggles hides the other answer behind its own label, so you have to
 *  work out what it will become from what it currently says. A switch shows both and the
 *  state at the same time.
 *
 *  Real radio buttons under the labels, not two <button>s keeping track between them. That
 *  is what a browser already understands as "one of these": the arrow keys move between the
 *  two, a screen reader says "1 of 2", and the checked one is the browser's own state
 *  rather than a class this code has to remember to take off the other one.
 *
 *  Each side is one word where it can be. The label carries the question and the sides
 *  answer it, so the two read as one sentence: writing the whole thing out on both sides
 *  ("שבת, then weekday") is what the dropdown did, and side by side that is the same words
 *  twice. Hebrew goes in a <bdi>: it sits in an otherwise-LTR line and would otherwise be
 *  reordered against what is around it.
 *
 *  `name` is the radio group's name and the stem of every id, so the two switches on the
 *  page cannot capture each other's presses. */
function switchHtml(name, question, sides) {
  const side = ({ value, label, on }) => `
    <input type="radio" name="${name}" id="${name}-${value}" value="${value}"
      class="week-switch-radio"${on ? ' checked' : ''}>
    <label class="week-switch-side" for="${name}-${value}">${label}</label>`;
  // The question and the switch are siblings rather than the switch being wrapped in a row
  // of its own, so that the switches stacked in the panel can share one grid and line their
  // tracks up with each other. aria-labelledby does not care how they are nested.
  return `<span class="week-switch-label" id="${name}-label">${question}</span>
    <div class="week-switch" role="radiogroup" aria-labelledby="${name}-label">
      ${sides.map(side).join('')}
      <span class="week-switch-thumb" aria-hidden="true"></span>
    </div>`;
}

/** Whether the week is being shown as one landscape sheet rather than two pages.
 *
 *  A view, not a print action. It used to build the sheet, hand it to the print dialog and
 *  take it down again inside a second and a half, so the only look anyone got at it was in
 *  the dialog's own preview. Now it stays on the screen and Print prints what is there,
 *  which is what the rest of this page has always done.
 *
 *  Kept here rather than in localStorage: it is how you are looking at this week now, not
 *  a setting, and coming back to the site should open on the ordinary two pages. It has to
 *  outlive a single render, though, since paging to another week re-renders from scratch
 *  and the sheet should still be a sheet afterwards. */
let pairView = false;

/** Whether More options is open, kept for the same reason and in the same way.
 *
 *  Every control in that panel re-renders the week, and the panel was rebuilt closed each
 *  time, so it shut the moment you used anything inside it. With the dropdown that was an
 *  irritation. With the switch it is worse: the thing you just moved goes off the screen
 *  before you can see where it landed, and the keyboard is dropped with it, because focus
 *  cannot stay on a control inside a closed <details> and falls back to the page. Measured:
 *  pressing the right arrow on the switch left document.activeElement as BODY, so a second
 *  arrow press did nothing at all.
 *
 *  Not in localStorage, again like pairView: opening the page fresh should show the panel
 *  closed, the same as it always has. */
let optionsOpen = false;

/** Which season a week belongs to, as something two weeks can be compared by.
 *
 *  The שבת sheet's id where there is one. A week whose Shabbos is Yom Tov has no שבת sheet
 *  at all, since no parsha is read and it has no row on that chart, and it comes through
 *  on its Weekday chart alone: those are the last weeks of the season they close, so they
 *  answer with the sheet that chart was generated beside. Without that, ראש השנה, יום כפור
 *  and סוכות would each read as a season of their own and a run would stop before them. */
function seasonKeyOf(serial, index, state) {
  const sheet = index.get(serial)?.sheet;
  if (sheet) return sheet.id;
  const weekday = weekdayChartFor(null, serial, state);
  return weekday?.linkedSheetId || weekday?.id || null;
}

/** The season that would follow the last week in the list, named. The two alternate, so
 *  it is whichever one the last week is not: a קיץ season ends at Sukkos and חורף picks
 *  up from there. Read off the newest week that belongs to a שבת sheet, since the last
 *  week or two can come from the Weekday chart alone (a Yom Tov week has no parsha and so
 *  no שבת page). */
function nextSeasonLabel(index, serials) {
  for (let i = serials.length - 1; i >= 0; i--) {
    const season = index.get(serials[i])?.sheet?.season;
    if (season) return season === 'kayitz' ? SEASON_LABELS.choref : SEASON_LABELS.kayitz;
  }
  return null;
}

/** "Shabbos, August 22, 2026". Every week here is anchored on its Shabbos, so the day
 *  name is always Saturday and there is no reason to call it that on a shul's own page.
 *  The word is written in rather than formatted, since no locale has it. */
const fmtShabbosDate = (date) =>
  'Shabbos, ' + new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', month: 'long', day: 'numeric', year: 'numeric' }).format(date);

/** The box a node sits in, when that box is one that starts a line of its own, up to but
 *  not including the cell. Everything below has to agree on where a line begins, and a
 *  <br> is only half the answer: a value typed into a cell is rich text, and the browser's
 *  own editor wraps a new line in a <div> rather than writing a <br>. The מנחה cell of one
 *  hand-typed week is "1:40 / 4:45<div>דרשה 5:15<br>6:14 / 6:29</div>", where the <div> is
 *  a line break on the screen but was invisible to the counting - so 1:40, 4:45 and
 *  דרשה 5:15 counted as one line of three, over the cap of two, and 1:40 was pushed onto a
 *  line of its own away from the 4:45 it was typed beside. */
const LINE_BOX_TAGS = new Set(['DIV', 'P', 'LI', 'UL', 'OL', 'BLOCKQUOTE', 'SECTION', 'PRE', 'TABLE', 'TR']);
function lineBoxOf(root, node) {
  let el = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement;
  while (el && el !== root) {
    if (LINE_BOX_TAGS.has(el.tagName)) return el;
    el = el.parentElement;
  }
  return null;
}

/** Tells you, node by node, whether this one has crossed into or out of such a box since
 *  the last one, which is a line break either way: text after a </div> starts a new line
 *  just as text after the matching <div> does. */
function lineBoxTracker(root) {
  let box;
  let seen = false;
  return (node) => {
    const next = lineBoxOf(root, node);
    const crossed = seen && next !== box;
    box = next;
    seen = true;
    return crossed;
  };
}

/** At most three times to a line, applied to the rendered cell rather than to a string.
 *
 *  Two reasons it is done here. A typed מנחה or מעריב is stored as HTML, and splitting
 *  HTML on "/" would cut through the slash in a closing tag; and a hand-typed value
 *  separates times with a plain "/", where the formulas use a padded one, so a string
 *  split had to know which kind it was holding. Walking text nodes sidesteps both: only
 *  real text is touched, whatever produced it.
 *
 *  Counting resets at every existing break, so a value that already comes in two lines
 *  keeps them and only over-long lines are broken further. */
function capTimesPerLine(root, max = 3) {
  // Counting times rather than separators, because there is no one separator to count.
  // The formulas join with "/", the שחרית schedule uses commas, and a typed list is
  // spaced. Splitting on punctuation therefore missed typed times entirely and left the
  // שחרית line at three. A time is recognisable on its own, so that is what is counted,
  // and a break goes in front of the one that would start a line too many.
  const TIME = /\d{1,2}:\d{2}\*{0,3}/g;
  const collectNodes = () => {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
    const found = [];
    while (walker.nextNode()) found.push(walker.currentNode);
    return found;
  };
  let nodes = collectNodes();

  /** Walks the value once, calling onTime for each time and onBreak at each line the
   *  value itself supplies - a <br> put there by weekNl2br, or a \n still inside a text
   *  node (the שחרית schedule is one node holding several lines). Both passes below have
   *  to agree on where a line starts, so they share this rather than repeating it.
   *
   *  A hard break is honoured from where it actually sits, not from the start of the node
   *  it is in: "7:15 7:35**\n8:00" is a single text node, and treating the whole node as
   *  one line left 7:35 sitting beside 7:15 while every other time got a line to itself. */
  const walkTimes = (onTime, onBreak) => {
    const crossedBox = lineBoxTracker(root);
    for (const node of nodes) {
      if (node.nodeType === Node.ELEMENT_NODE) {
        if (node.tagName === 'BR') onBreak();
        continue;
      }
      if (crossedBox(node)) onBreak();
      const text = node.nodeValue;
      let prevEnd = 0;
      let match;
      TIME.lastIndex = 0;
      while ((match = TIME.exec(text))) {
        if (text.slice(prevEnd, match.index).includes('\n')) onBreak();
        prevEnd = match.index + match[0].length;
        onTime(node, match);
      }
      if (text.slice(prevEnd).includes('\n')) onBreak();
    }
  };

  // First pass: how many times each of the value's own lines holds.
  const countLines = () => {
    const counts = [0];
    walkTimes(
      () => counts[counts.length - 1]++,
      () => counts.push(0)
    );
    return counts;
  };
  let counts = countLines();

  // A cell of nothing but times, where the value's own line break falls somewhere that
  // leaves a line over the cap, is re-flowed as one run: the workbook writes מנחה ערב שבת
  // as three times and then four, and honouring that break gave 3, 2, 2 where laying the
  // seven out fresh gives 2, 2, 3. Only when a break is needed anyway, so a cell that
  // already fits keeps the grouping the value asked for - מנחה stays 1:20 above
  // 4:03 / 4:18 rather than being run together. Only when the cell is times and
  // separators, so the שחרית schedule keeps its heading and its blocks, and
  // "שקיעה 4:48" is never joined onto the line above it.
  if (!/\p{L}/u.test(root.textContent) && counts.some((n) => n > max)) {
    root.querySelectorAll('br').forEach((br) => br.replaceWith(document.createTextNode(SLASH)));
    for (const node of nodes) {
      if (node.nodeType === Node.TEXT_NODE && node.nodeValue.includes('\n')) {
        node.nodeValue = node.nodeValue.replace(/\s*\n\s*/g, SLASH);
      }
    }
    nodes = collectNodes();
    counts = countLines();
  }

  /** How to split n times over as few lines as the cap allows, as evenly as those lines
   *  can be. Filling each line to the cap instead leaves whatever is left over sitting
   *  alone: a run of four with a cap of three came out three and then a single 3:00,
   *  which is what a חורף מנחה ערב שבת does every week once the clocks go back. Seven
   *  becomes 2, 2, 3 rather than 3, 3, 1: the fuller line goes last, so the block builds
   *  downwards rather than tailing off. */
  const sizesFor = (n) => {
    const lines = Math.max(1, Math.ceil(n / max));
    const base = Math.floor(n / lines);
    const extra = n % lines;
    return Array.from({ length: lines }, (_, i) => base + (i >= lines - extra ? 1 : 0));
  };
  const plan = counts.map(sizesFor);

  // Second pass: the same walk, breaking where the plan says to. Cuts are collected and
  // applied per node afterwards, since replacing a node mid-walk would invalidate it.
  const cutsByNode = new Map();
  let line = 0;
  let chunk = 0;
  let taken = 0;
  walkTimes(
    (node, match) => {
      taken++;
      const limit = plan[line]?.[chunk] ?? max;
      if (taken <= limit) return;
      if (!cutsByNode.has(node)) cutsByNode.set(node, []);
      cutsByNode.get(node).push(match.index);
      taken = 1;
      chunk++;
    },
    () => {
      line++;
      chunk = 0;
      taken = 0;
    }
  );

  for (const [node, cuts] of cutsByNode) {
    // A cut at the very start of a node breaks before whatever inline element that node
    // opens, rather than inside it: see insertAtLineStart.
    const leading = cuts[0] === 0;
    const rest = leading ? cuts.slice(1) : cuts;
    if (leading) insertAtLineStart(root, node, document.createElement('br'));
    if (!rest.length) continue;
    const text = node.nodeValue;
    const frag = document.createDocumentFragment();
    let from = 0;
    for (const at of rest) {
      // Everything up to this time, with the separator that would have preceded it
      // trimmed away so the next line starts at the time itself.
      frag.append(text.slice(from, at).replace(/[\s,/]+$/, ''));
      frag.append(document.createElement('br'));
      from = at;
    }
    frag.append(text.slice(from));
    node.replaceWith(frag);
  }
  trimSeparatorsBeforeBreaks(root);
}

/** Strips the space a line starts with, so every line starts on the same axis.
 *
 *  underlineTime writes its value as "<u> 6:42</u>": the leading space gives the rule a
 *  lead-in on the wall chart, where the times are centred and it does not show. Set flush
 *  left here it shows as an indent of about half a character, and only on some lines. The
 *  ones capTimesPerLine broke itself already lost it, being trimmed as the separator in
 *  front of the time, so a line beginning at a break the *source* supplied was indented
 *  while its neighbours were not, which is what made the column look crooked. */
function trimSpaceAtLineStart(root) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  const crossedBox = lineBoxTracker(root);
  let atLineStart = true;
  for (const node of nodes) {
    if (node.nodeType === Node.ELEMENT_NODE) {
      if (node.nodeName === 'BR') atLineStart = true;
      continue;
    }
    if (crossedBox(node)) atLineStart = true;
    // [^\S\n] is "whitespace but not a newline", which covers the non-breaking spaces the
    // separators are built from as well as ordinary ones.
    let text = atLineStart ? node.nodeValue.replace(/^[^\S\n]+/, '') : node.nodeValue;
    text = text.replace(/\n[^\S\n]+/g, '\n');
    if (text !== node.nodeValue) node.nodeValue = text;
    // An emptied node leaves the flag alone: the next node is still starting the line.
    if (text.length) atLineStart = text.endsWith('\n');
  }
}

/** Whether this card should stand flush instead of going onto a colon axis.
 *
 *  The axis exists so a column of times does not wobble, and with several long hours in a
 *  block it earns its keep. With exactly one it does the opposite: three lines get pulled in
 *  by a digit and the lone 12:30 reads as though it is sticking out to the left, which is
 *  what it looks like on a חורף שבת card between November and early January.
 *
 *  So: one long hour on the whole card, alone on its line, with the other lines of its own
 *  block carrying two times each. That last part is what separates the שבת card, where the
 *  12:30 sits above three pairs, from a חול card, whose lines carry one time each and whose
 *  מעריב runs 10:00, 10:30, 11:00 together, where the axis is still the right answer. */
const TIME_ON_LINE = /\d{1,2}:\d{2}/g;

function cardShouldStandFlush(cells) {
  const lines = [];
  cells.forEach((cell, block) => {
    // innerText rather than a DOM walk: it is the lines as they actually broke, which is
    // what the question is about, and the pads are not in the document yet.
    cell.innerText.split('\n').forEach((raw) => {
      const line = raw.trim();
      if (line) lines.push({ block, line, times: (line.match(TIME_ON_LINE) || []).length });
    });
  });
  const long = lines.filter((l) => /^\d{2}:\d{2}/.test(l.line));
  if (long.length !== 1) return false;
  const only = long[0];
  if (only.times !== 1) return false;
  const rest = lines.filter((l) => l.block === only.block && l !== only);
  return rest.length > 0 && rest.every((l) => l.times === 2);
}

/** Whether any line in this cell opens with a two-digit hour, which is what decides
 *  whether padding is worth doing. Asked of a whole card rather than one cell: the colons
 *  should line up down the page, so a שחרית block of single-digit hours is padded to sit
 *  on the same axis as a מעריב block that runs past ten, instead of each block finding
 *  its own. Where no row on the card has a long hour, nothing is padded at all: it would
 *  move every line equally and change nothing, except on a row that opens with a word
 *  rather than a time ("6:06" over "פלג 6:21"), where it would shift one and not the
 *  other and pull the two out of line. */
function hasTwoDigitHourAtLineStart(root) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  const crossedBox = lineBoxTracker(root);
  let atLineStart = true;
  let node;
  while ((node = walker.nextNode())) {
    if (node.nodeType === Node.ELEMENT_NODE) {
      if (node.nodeName === 'BR') atLineStart = true;
      continue;
    }
    if (crossedBox(node)) atLineStart = true;
    const segments = node.nodeValue.split('\n');
    for (let i = 0; i < segments.length; i++) {
      if (i === 0 && !atLineStart) continue;
      if (/^\s*\d{2}:\d{2}/.test(segments[i])) return true;
    }
    atLineStart = node.nodeValue.endsWith('\n');
  }
  return false;
}

/** Lines the colons up down a column of times.
 *
 *  Set flush left, "8:45" and "10:00" start at the same place, which puts their colons a
 *  digit apart and makes the column look as though it wobbles. A single-digit hour is
 *  given a figure space (U+2007, defined to be exactly as wide as a digit) so the hour
 *  occupies two digits' width either way and every colon falls on one axis. Only the time
 *  that starts a line is padded: that is the one the column is read down.
 *
 *  Paired with font-variant-numeric: tabular-nums in the stylesheet, without which a font
 *  with proportional figures would put "1" and "8" at different widths and undo it. */
/** A digit's worth of blank at the start of a line, so a 1:35 lines its colon up with a
 *  12:30. An empty element sized in CSS rather than a U+2007 figure space: as a character
 *  it is only as wide as the font says, and a font without it falls back to something
 *  else or to nothing, so the indent was one thing here and another on a phone. An
 *  inline-block also keeps an ancestor's underline from being drawn through it. */
const timePad = () => {
  const pad = document.createElement('span');
  pad.className = 'time-pad';
  return pad;
};

function alignColons(root) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);

  // Where a pad belongs, gathered first and inserted afterwards: putting one in mid-walk
  // splits the very node the walk is reading.
  const inserts = [];
  const crossedBox = lineBoxTracker(root);
  let atLineStart = true;
  for (const node of nodes) {
    if (node.nodeType === Node.ELEMENT_NODE) {
      if (node.nodeName === 'BR') atLineStart = true;
      continue;
    }
    if (crossedBox(node)) atLineStart = true;
    const text = node.nodeValue;
    if (!text.length) continue;
    // Split on the newlines the value carries, because a line can start in the middle of
    // a text node as well as after a <br>: the שחרית block is "…7:35\n8:00 8:20*…" in one
    // node, and looking only at the node's own start left that 8:00 unpadded while every
    // other time in the column was padded.
    const segments = text.split('\n');
    let at = 0;
    for (let i = 0; i < segments.length; i++) {
      const segment = segments[i];
      const startsAt = at;
      at += segment.length + 1; // + the newline it was split on
      if (i === 0 && !atLineStart) continue;
      // The first time on the line, wherever it sits in the string. Matching only a line
      // that *begins* with one skipped "שקיעה 4:48": in the string the Hebrew word comes
      // first, so the line looked like it had no time to align, and its colon sat a digit
      // to the left of every other colon on the card. Padding the line start moves the
      // whole line, colon included, onto the axis. Only a one-digit hour needs it - a
      // 12:30 is what the axis is set by.
      const firstTime = segment.match(/(\d{1,2}):\d{2}/);
      if (!firstTime || firstTime[1].length !== 1) continue;
      inserts.push({ node, offset: startsAt + segment.match(/^\s*/)[0].length });
    }
    atLineStart = text.endsWith('\n');
  }

  // Back to front, so an earlier offset is still an offset into the same text.
  for (const { node, offset } of inserts.reverse()) {
    if (offset === 0) insertAtLineStart(root, node, timePad());
    else {
      const tail = node.splitText(offset);
      tail.parentNode.insertBefore(timePad(), tail);
    }
  }
}

/** Puts an element in front of a node that opens a line, outside whatever inline element
 *  the node happens to open. A pad left inside a <u> is fine to look at but a <br> is not:
 *  an underlined line break paints a rule out to the edge of the line in some engines, and
 *  the markup reads as though the underline spans two lines when it does not.
 *
 *  It stops at a box that starts a line of its own: climbing out of a <div> would put the
 *  pad or the break in front of the whole block rather than at the head of its first line,
 *  which is a line the value never asked for. */
function insertAtLineStart(root, node, el) {
  let target = node;
  while (
    target.parentNode &&
    target.parentNode !== root &&
    !LINE_BOX_TAGS.has(target.parentNode.tagName) &&
    target.parentNode.firstChild === target
  ) {
    target = target.parentNode;
  }
  target.parentNode.insertBefore(el, target);
}

/** Hangs the location stars off the end of a time instead of letting them widen it.
 *
 *  A star says which room a מנין is in, not what time it is, so it should not move the
 *  time. Centred with the star counted, 7:20* sat a couple of characters left of 7:00
 *  above it and the column read as though it had been nudged. Each run of stars goes into
 *  a box of no width, so it still prints exactly where it was but the line measures as
 *  the digits alone and every time centres on the same axis. */
function hangTimeMarkers(root) {
  const MARKED = /(\d{1,2}:\d{2})(\*{1,3})/g;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) {
    const text = node.nodeValue;
    if (!MARKED.test(text)) continue;
    MARKED.lastIndex = 0;
    const frag = document.createDocumentFragment();
    let cut = 0;
    let match;
    while ((match = MARKED.exec(text))) {
      frag.append(text.slice(cut, match.index) + match[1]);
      const mark = document.createElement('span');
      mark.className = 'time-mark';
      mark.textContent = match[2];
      frag.append(mark);
      cut = match.index + match[0].length;
    }
    frag.append(text.slice(cut));
    node.replaceWith(frag);
  }
}

/** The text node immediately before `node` in reading order, without crossing a line
 *  break or leaving `root`. Returns null at either boundary. */
function previousTextNode(from, root) {
  let node = from;
  while (node && node !== root) {
    if (!node.previousSibling) {
      node = node.parentNode;
      continue;
    }
    node = node.previousSibling;
    while (node.lastChild) node = node.lastChild;
    if (node.nodeType === Node.TEXT_NODE) return node;
    if (node.nodeName === 'BR') return null; // a line already ends here, nothing to tidy
  }
  return null;
}

/** Removes the separator stranded at the end of a line by a break inserted above.
 *
 *  The in-node trim can only reach text it is already holding. An underlined time is its
 *  own <u>, so the "/" in front of it lives in the text node *outside* that element and
 *  survives, leaving lines ending in a bare "10:30 /". Every underlined column hits this,
 *  which is most of them, so the tidy-up walks back out of the element and strips it. */
function trimSeparatorsBeforeBreaks(root) {
  for (const br of root.querySelectorAll('br')) {
    let node = previousTextNode(br, root);
    while (node) {
      // No early-out on "nothing changed": the break is usually preceded by an empty
      // text node (the trim above leaves one behind when the whole slice was separator),
      // and stopping there would never reach the real separator further back.
      node.nodeValue = node.nodeValue.replace(/[\s,/]+$/, '');
      if (node.nodeValue) break; // ends in real content now
      node = previousTextNode(node, root); // nothing left here, keep walking back
    }
  }
}

/** The key to the symbols, carrying only the lines the card actually uses.
 *
 *  A card is a page on its own, so it has to say what its own marks mean, but saying all
 *  three every time would explain marks that are not on it: a week whose מנינים are all
 *  in the main בית מדרש has no underline to explain, and באולם השמחות only appears on a
 *  week that has a second שחרית. Each line is added only if its mark is on the card.
 *
 *  The star lines are set right to left so the star sits at the right-hand end, against
 *  the Hebrew it belongs to, the same way round as the footer of the printed chart. The
 *  first line is mostly English and is set the other way. Measured, not assumed: stored
 *  order is not display order for either of them. */
function fillLegend(card) {
  const legend = card.querySelector('.week-legend');
  if (!legend) return;
  const marks = [...card.querySelectorAll('.week-lines .time-mark')].map((m) => m.textContent.trim());
  const lines = [];
  if (card.querySelector('.week-lines u')) lines.push({ dir: 'ltr', text: 'All underlined מנינים will be בבית מדרש למטה' });
  // The two star notes share a line, in the order the printed chart's footer has them,
  // and either can appear on its own if only its mark is on the card.
  const stars = [];
  if (marks.includes('*')) stars.push('*בעזרת נשים');
  if (marks.includes('**')) stars.push('**באולם השמחות');
  if (stars.length) lines.push({ dir: 'rtl', text: stars.join(' ') });
  legend.innerHTML = lines.map((l) => `<div class="week-legend-line" dir="${l.dir}">${weekEsc(l.text)}</div>`).join('');
}

/** A row's name, taken from the chart's column header.
 *
 *  A header is written to wrap inside a narrow chart column, so its own breaks mean
 *  nothing on a card and are flattened away. Two are exceptions, and for the same reason:
 *  the name is two things and run onto one line it reads as neither.
 *
 *  A פלג row keeps a break in front of פלג, which is what separates "מנחה (למטה)" from
 *  "פלג מ״א". And ס״ז קר״ש keeps one after it, separating the zman from the two opinions
 *  it is given by, "גר״א / מ״א". Both breaks are already in the chart's own headers; this
 *  puts back the two that are worth keeping.
 *
 *  No other header wants one: "הדלקת נרות" and "מנחה ערב שבת" are single names that only
 *  wrapped because the chart column was narrow. */
function formatLabel(label) {
  return markHeaderRoom(weekEsc(label.replace(/\s+/g, ' ').trim()))
    .replace(/ (פלג )/, '<br>$1')
    // Matched after escaping, so the gershayim may be a real ״ or the &quot; that a plain
    // double quote in the header turns into.
    .replace(/(קר(?:&quot;|״|")ש) /, '$1<br>');
}

/** A label/time line. */
function line(label, value, isHtml = false, keepEmpty = false, labelHtml = '') {
  const text = String(value ?? '').trim();
  if (!text && !keepEmpty) return '';
  return `<div class="week-line">
    <span class="week-label"${hebrewLang(labelHtml || formatLabel(label))}>${labelHtml || formatLabel(label)}</span>
    <span class="week-time"${hebrewLang(isHtml ? text : weekNl2br(text))}>${isHtml ? text : weekNl2br(text)}</span>
  </div>`;
}

/** The publish step, explained where the thing being published is on screen.
 *
 *  Publishing commits one file to the site, so it takes effect on its own: no file
 *  changes hands. Deliberately a button rather than something automatic, because
 *  publishing is the moment the congregation sees a change and that should be a
 *  decision, not a side effect of editing a cell. */
function publishPanelHtml(sheet, state, open = false) {
  const hasToken = Boolean(getPublishToken());
  const groups = publishableGroups(state);
  const label = (s) => SEASON_LABELS[s.season] || s.season;
  // A row here is a season that exists to be published. With only one generated there is
  // only one row, which reads as "there is no way to publish a second chart" - so say
  // where the second one comes from instead of leaving an empty space to interpret.
  const missing = ['kayitz', 'choref'].filter((season) => !groups.some((g) => g.sheet.season === season));
  const rows = groups
    .map(
      (g) =>
        `<div class="published-row">
          <span><bdi${hebrewLang(label(g.sheet))}>${weekEsc(label(g.sheet))}</bdi> ${g.sheet.hebrewYear} <span class="hint">(${g.sheet.weeks.length} weeks${g.sheet.id === sheet?.id ? ', the week you are on' : ''})</span></span>
          <button type="button" class="btn-primary publish-btn" data-id="${g.sheet.id}">Publish</button>
        </div>`
    )
    .join('');
  return `<details class="panel no-print" id="publish-panel" ${open ? 'open' : ''}>
    <summary>Publish for the congregation</summary>
    <div class="panel-body">
      <p class="hint">The congregation's page is <strong>lczmanim.cjaffa.com</strong>. It shows one week at a time and moves on by itself once Shabbos is over, for the whole season.</p>
      ${
        hasToken
          ? `${rows || '<p class="hint">No season has been generated yet.</p>'}
             ${
               groups.length && missing.length
                 ? `<p class="hint">Only ${missing.length === 1 ? `<bdi${hebrewLang(SEASON_LABELS[missing[0] === 'kayitz' ? 'choref' : 'kayitz'])}>${weekEsc(SEASON_LABELS[missing[0] === 'kayitz' ? 'choref' : 'kayitz'])}</bdi> is here` : 'these are here'}. A second chart gets its own row: generate <bdi${hebrewLang(SEASON_LABELS[missing[0]])}>${weekEsc(SEASON_LABELS[missing[0]])}</bdi> on the Generate tab and it turns up above, with its own Publish button.</p>`
                 : ''
             }
             <p class="hint">Publishing a season leaves any other published season in place, so קיץ and חורף can both be live. Publishing the same season again replaces it, which is how a correction reaches the congregation.</p>
             <div id="publish-status" class="hint"></div>
             <div id="published-list"></div>`
          : '<p class="error">No publishing token set. Add one in Settings, under Publishing, and this becomes a single button.</p>'
      }
    </div>
  </details>`;
}

function cardHtml(title, linesHtml, settings, kind = '') {
  // The same header the wall charts carry, markup and all, rather than a second one that
  // looks similar: one header, one place to change it. It is sized in inches off
  // --sheet-header-scale, so on this narrower page it shrinks in proportion instead of
  // being redrawn.
  return `<section class="week-card${kind ? ' ' + kind : ''}">
    <div class="page-header">
      <div class="header-row">
        <img class="header-icon" src="${settings.headerIconImage || 'assets/logo-building-icon.png'}" alt="">
        <div class="header-center">
          <img class="header-logo" src="assets/logo-text.png" alt="${weekEsc(settings.shulName)}"${hebrewLang(settings.shulName)}>
          ${settings.headerSubtitle ? `<div class="header-subtitle"${hebrewLang(settings.headerSubtitle)}>${weekEsc(settings.headerSubtitle)}</div>` : ''}
        </div>
        <div class="header-rabbi"${hebrewLang(settings.headerRabbiLine)}>${weekNl2br(settings.headerRabbiLine)}</div>
      </div>
    </div>
    <h3 class="week-title"${hebrewLang(title)}>${weekEsc(title)}</h3>
    <div class="week-lines"><div class="week-lines-inner">${linesHtml}</div></div>
    <div class="week-legend"></div>
    <div class="week-foot">${weekEsc(settings.footerAddress)}</div>
  </section>`;
}

/** Sizes a week's list of times to the page: down when it would run past the bottom, up
 *  when it would otherwise leave the sheet half empty.
 *
 *  A שבת קיץ week is eleven rows, some of them two lines deep, and at full size that
 *  spills onto a second sheet: the print preview showed "2 sheets of paper" with the page
 *  cut mid-list. Nothing can be shrunk by CSS alone, so the ratio is measured and applied.
 *
 *  The weekday card is the opposite problem. It carries three minyanim, and even with a
 *  time to a line it stopped two thirds down the sheet, which on a wall reads as a page
 *  that failed to finish rather than as a short list. So it grows to meet the footer.
 *
 *  The measurement is taken from the page on screen, because the page on screen *is* the
 *  printed page: same size, same type, same rules. The earlier version had to inject the
 *  print stylesheet and measure against that, which was fragile and got the answer wrong
 *  twice. */
const MAX_GROW = 1.6; // past this the times are billboard-sized rather than well set

function fitLinesToPage(container) {
  container.querySelectorAll('.week-card').forEach((card) => {
    const box = card.querySelector('.week-lines');
    const inner = box?.firstElementChild;
    if (!inner) return;
    card.style.removeProperty('--fit-scale');
    card.style.removeProperty('--fit-width');
    const room = box.clientHeight;
    const needed = inner.scrollHeight;
    if (!room || !needed) return;
    // A hair under, so rounding never pushes the last row over the edge.
    const byHeight = (room / needed) * 0.98;
    if (needed > room) {
      card.style.setProperty('--fit-scale', Math.max(0.5, byHeight).toFixed(3));
      return;
    }
    // Growing must not widen the block. zoom scales the measure along with the type, and
    // the weekday card grew far enough that its rows spanned the whole page while the
    // שבת card's stayed narrow, so a pair of cards meant to match did not. Dividing the
    // measure by the same factor cancels that: the type grows, the block stays put.
    //
    // A constant width and bigger type can push a line into wrapping, which makes the
    // block taller than the growth assumed, so the result is measured and eased back
    // until it really fits rather than trusted first time.
    let grow = Math.min(byHeight, MAX_GROW);
    for (let i = 0; i < 8 && grow > 1.02; i++) {
      card.style.setProperty('--fit-scale', grow.toFixed(3));
      card.style.setProperty('--fit-width', grow.toFixed(3));
      if (inner.scrollHeight * grow <= room) return;
      grow -= 0.05;
    }
    card.style.removeProperty('--fit-scale');
    card.style.removeProperty('--fit-width');
  });
}

/** Sizes the times in each column of the pair sheet.
 *
 *  Its own routine rather than fitLinesToPage, because on this sheet the measure is tied
 *  to the scale: the block is set to 77% of the column divided by the scale, so that what
 *  lands on the paper is 77% whichever way it went. That means the height does not simply
 *  scale with the type the way it does on a card, since a narrower measure wraps more
 *  lines. So the scale is searched for and each try is measured, rather than worked out
 *  from one ratio and trusted.
 *
 *  A halving search: bigger type in a narrower measure is always taller on the paper, so
 *  there is one crossing point to find and nine tries land within a thousandth of it. */
function fitPairColumns(sheet) {
  sheet.querySelectorAll('.week-card').forEach((card) => {
    const box = card.querySelector('.week-lines');
    const inner = box?.firstElementChild;
    if (!inner) return;
    card.style.removeProperty('--fit-width');
    const room = box.clientHeight;
    if (!room) return;
    let fits = 0.5;
    let tooBig = MAX_GROW;
    for (let i = 0; i < 9; i++) {
      const mid = (fits + tooBig) / 2;
      card.style.setProperty('--fit-scale', mid.toFixed(3));
      // scrollHeight is in the block's own space, which zoom then scales onto the paper.
      if (inner.scrollHeight * mid <= room) fits = mid;
      else tooBig = mid;
    }
    card.style.setProperty('--fit-scale', fits.toFixed(3));
  });
}

/** Rebuilds the two cards on screen as one landscape sheet: a single header across the
 *  top, the two lists of times side by side under it, and one address along the bottom.
 *
 *  The cards are moved rather than rebuilt. Everything that was worked out on them, the
 *  legend, the line caps, which times are underlined, the colon axis, comes across
 *  untouched, and there is no second copy of any of that logic to keep in step.
 *
 *  Returns false when there is only one card, which is a week whose Shabbos is Yom Tov:
 *  there is nothing to put beside it and the button is not offered. */
function buildPairSheet(wrap) {
  const cards = [...wrap.querySelectorAll('.week-card')];
  if (cards.length < 2) return false;
  const header = cards[0].querySelector('.page-header');
  const foot = cards[0].querySelector('.week-foot');

  // The parsha, once, in the middle. Read off the שבת card, whose title is the parsha
  // line on its own; the חול card's has "זמני חול · " in front of it and would have to be
  // unpicked. The button is only offered when both cards exist, so there is always one.
  const shabbosCard = cards.find((card) => !card.classList.contains('is-weekday-card'));
  const parsha = shabbosCard?.querySelector('.week-title')?.textContent.trim() || '';

  const sheet = document.createElement('section');
  sheet.className = 'week-pair';
  if (header) sheet.appendChild(header.cloneNode(true));
  if (parsha) {
    const title = document.createElement('h2');
    title.className = 'week-pair-title';
    title.textContent = parsha;
    sheet.appendChild(title);
  }

  const cols = document.createElement('div');
  cols.className = 'week-pair-cols';
  cards.forEach((card) => {
    // With the parsha said once above, each column only has to say which half it is.
    const title = card.querySelector('.week-title');
    if (title) {
      title.textContent = card.classList.contains('is-weekday-card') ? 'זמני חול' : 'זמני שבת';
      title.lang = 'he';
    }
    // appendChild moves them, so wrap is left empty and the sheet takes their place.
    cols.appendChild(card);
  });
  sheet.appendChild(cols);

  // One note under the pair, carrying every line either column needed and each of them
  // once. Both columns explain the same underline, and set out twice on one sheet that
  // reads as two different notes rather than one said twice. The star lines are only on
  // the column that uses them, so a straight merge keeps whatever is relevant and drops
  // nothing: taken in column order, first seen wins.
  const seen = new Set();
  const merged = [];
  cards.forEach((card) => {
    card.querySelectorAll('.week-legend .week-legend-line').forEach((el) => {
      const key = `${el.getAttribute('dir')}|${el.textContent.trim()}`;
      if (seen.has(key)) return;
      seen.add(key);
      merged.push(el.cloneNode(true));
    });
  });
  if (merged.length) {
    const legend = document.createElement('div');
    legend.className = 'week-legend week-pair-legend';
    merged.forEach((el) => legend.appendChild(el));
    sheet.appendChild(legend);
  }

  if (foot) sheet.appendChild(foot.cloneNode(true));
  wrap.appendChild(sheet);
  wrap.classList.add('is-pairing');
  return true;
}

/** Scales the pages down until one fits across the window.
 *
 *  A letter page is 816px wide, which is wider than a phone and wider than this app's
 *  column on most screens. Scaled rather than scrolled sideways, so a whole page is
 *  visible at once, and with `zoom` rather than `transform` so the layout really shrinks
 *  instead of only being painted smaller. Print resets it: paper has no such problem.
 *
 *  Recomputed on resize, since rotating a phone changes what fits. */
let fitPagesHandler = null;

/** Scales the one landscape sheet down until it fits across the window.
 *
 *  The same idea as fitPagesToWindow, but the zoom goes on the sheet rather than on the
 *  cards inside it. On the cards it would land between the sheet and the columns, and a
 *  zoom on a flex item changes the height it resolves to, which is what the times were
 *  sized against. On the sheet itself nothing inside it can tell the difference.
 *
 *  A sheet is 11in wide against a phone's 4in or so, so on a phone this comes out at about
 *  a third size: enough to see the shape of the page and to check it before printing it,
 *  not enough to read the times off. That is the honest cost of looking at a landscape
 *  sheet on a portrait phone, and Back to two pages is right there. */
function fitSheetToWindow(container) {
  const wrap = container.querySelector('.week-cards');
  const sheet = wrap?.querySelector('.week-pair');
  if (!sheet) return;
  const apply = () => {
    if (!document.body.contains(sheet)) return;
    sheet.style.removeProperty('zoom');
    const available = wrap.clientWidth;
    const sheetWidth = sheet.getBoundingClientRect().width;
    if (!available || !sheetWidth || sheetWidth <= available) return;
    sheet.style.zoom = (available / sheetWidth).toFixed(4);
  };
  apply();
  if (fitPagesHandler) window.removeEventListener('resize', fitPagesHandler);
  fitPagesHandler = apply;
  window.addEventListener('resize', fitPagesHandler);
}

function fitPagesToWindow(container) {
  const wrap = container.querySelector('.week-cards');
  const card = wrap?.querySelector('.week-card');
  if (!card) return;
  const apply = () => {
    if (!document.body.contains(wrap)) return;
    wrap.classList.remove('is-scaled');
    wrap.style.removeProperty('--page-zoom');
    const available = wrap.clientWidth;
    const pageWidth = card.getBoundingClientRect().width;
    if (!available || !pageWidth || pageWidth <= available) return;
    wrap.style.setProperty('--page-zoom', (available / pageWidth).toFixed(4));
    wrap.classList.add('is-scaled');
  };
  apply();
  if (fitPagesHandler) window.removeEventListener('resize', fitPagesHandler);
  fitPagesHandler = apply;
  window.addEventListener('resize', fitPagesHandler);
}

/** Everything that has to be done to a card once its markup is in the document: break
 *  the long lines, square the times up, hang the marks, and write the key.
 *
 *  A function rather than inline, because printing the rest of the season replaces the
 *  cards with a whole season's worth and every one of them needs the same treatment. */
function decorateCards(root) {
  root.querySelectorAll('.week-card').forEach((card) => {
    // Two to a line on the שבת card, one on the weekday card. The weekday card carries
    // only three minyanim against a full sheet, so a time to a line is what fills it;
    // the שבת card has eleven rows and would run off the page the same way. Keyed on
    // which card it is rather than where it sits: a Yom Tov week has no שבת card, and
    // going by position gave its חול card the שבת card's own count.
    //
    // It was three. Two makes the pairs plain and, with sizesFor putting the short line
    // first, leaves any odd time at the top of the block rather than trailing off the
    // bottom: seven comes out 1, 2, 2, 2.
    const perLine = card.classList.contains('is-weekday-card') ? 1 : 2;
    card.querySelectorAll('.week-time:not(.is-authored)').forEach((el) => capTimesPerLine(el, perLine));
    const cells = [...card.querySelectorAll('.week-time')];
    cells.forEach((el) => trimSpaceAtLineStart(el));
    // One colon axis for the whole card rather than one per row, except where a single long
    // hour would be the only thing on it: see cardShouldStandFlush.
    if (cells.some((el) => hasTwoDigitHourAtLineStart(el)) && !cardShouldStandFlush(cells)) {
      cells.forEach((el) => alignColons(el));
    }
    cells.forEach((el) => hangTimeMarkers(el));
    // After the marks exist, so the key can be built from what is really on the card.
    fillLegend(card);
  });
}

/** Both cards for one week, as markup, ready to be dropped into a .week-cards container.
 *
 *  Split out of renderWeek so a week other than the one on screen can be built too: that
 *  is what printing the rest of the season does, which lays every remaining week out at
 *  once rather than asking someone to page through and print them one at a time. */
function weekCardsHtml(showing, index, state, settings) {
  const { week, sheet } = index.get(showing);

  // No Shabbos sheet means this week's Shabbos is Yom Tov, which has no parsha and so no
  // row on the chart. The weekday times are still real, so the week shows its חול card
  // alone rather than being dropped.
  const shabbos = sheet ? rowFor(week, sheet, state, settings) : null;
  // Printed order, right to left, so the card lists the minyanim in the same sequence
  // the wall chart does.
  const shabbosLines = shabbos
    ? [...shabbos.columns].reverse().map((c) => line(c.header, shabbos.row[c.key], shabbos.overriddenKeys.has(c.key))).join('')
    : '';

  const weekday = weekdayChartFor(sheet, showing, state);
  const weekdayWeek = weekday?.weeks.find((w) => w.serial === showing);
  let weekdayLines = '';
  if (weekdayWeek) {
    // Built from the formulas and then overridden, exactly like the Shabbos row above.
    // A blank baseline here would print an empty מנחה and מעריב on every week nobody had
    // happened to type over, even though the schedule is computed now.
    const { row: wdRow, overriddenKeys: wdOverridden } = mergeRow(buildWeekdayRow(weekdayWeek, settings), weekday, showing);
    const parts = [...WEEKDAY_COLUMNS]
      .reverse()
      // keepEmpty: מנחה and מעריב should hold their row even on a week that computes to
      // nothing, or the card reads as though the minyan does not exist rather than as
      // though the time is not set yet.
      // isHtml only for an override (already real HTML) and for שחרית (rich text out of
      // Settings). A computed value still carries the underline sentinels, which
      // weekNl2br has to turn into real <u> elements.
      .map((c) =>
        c.key === 'E'
          ? line(c.header, htmlLines(state.settings.weekdayShacharis), true, false, '', true)
          : line(c.header, wdRow[c.key], wdOverridden.has(c.key), true)
      );

    // The second שחרית schedule, only on weeks that actually have one of those days,
    // labelled with which day it is rather than the chart's catch-all heading. It goes
    // directly after the everyday schedule, not before it: most of the week still runs
    // on the regular times, so those are what should be read first.
    const special = specialDaysInWeek(showing, settings);
    if (special.length && state.settings.weekdayShacharisSpecial) {
      // The day names go on their own line, in their own direction. Run together with
      // the Hebrew they came out as "(Monday,)" on one line and "(Thursday" on the next:
      // a bracketed Latin list inside a right-to-left label gets reordered when it wraps.
      const labelHtml = special
        .map((d) => `${weekEsc('שחרית ' + d.name)}<br><span class="week-days" dir="ltr">(${weekEsc(d.day)})</span>`)
        .join('<br>');
      parts.splice(1, 0, line('', htmlLines(state.settings.weekdayShacharisSpecial), true, false, labelHtml, true));
    }
    weekdayLines = parts.join('');
  }

  const parsha = week.parsha + (week.specialParsha ? ' · ' + week.specialParsha : '');
  // A week whose Shabbos is Yom Tov is named for its Yom Tov rather than a parsha, no
  // parsha being read that Shabbos. "פרשת סוכות" would be wrong and "סוכות" on its own
  // reads as though these were the times for Yom Tov, which they are not: they are the
  // ordinary weekdays around it. Named off the label rather than off the missing Shabbos
  // sheet, so the card and the chart say the same thing by the same rule.
  const cardTitle = isYomTovWeekLabel(week.parsha) ? weekOfLabel(week.parsha, false) : 'פרשת ' + parsha;

  const shabbosCard = shabbosLines ? cardHtml(cardTitle, shabbosLines, state.settings) : '';
  const weekdayCard = weekdayLines ? cardHtml('זמני חול · ' + cardTitle, weekdayLines, state.settings, 'is-weekday-card') : '';
  // The two are ordered the same way on screen as on paper, here rather than only in the
  // print run: this page's whole bargain is that what you see is what comes out, so an
  // order that applied to the printer alone would be a surprise waiting to happen.
  return cardOrder(showing, state, settings) === 'weekday' ? weekdayCard + shabbosCard : shabbosCard + weekdayCard;
}


/** Every week the chart covering this one is the chart for, in order.
 *
 *  The stretch a chart page covers, rather than the list of weeks printed on it, and the
 *  difference is the weeks that have no row. A Yom Tov Shabbos has no parsha and so nothing
 *  on the שבת chart, but its weekdays are real and its card is worth reading. Going by the
 *  printed rows dropped them: from האזינו the congregation could not reach סוכות the week
 *  after, and could not reach ראש השנה the week before either, which sits inside the very
 *  dates the chart covers.
 *
 *  So a chart owns from its own first week until the next chart begins, and the last one
 *  owns everything after it. That is the honest span: the summer chart is what is on the
 *  wall through Sukkos, because the winter chart does not start until בראשית.
 *
 *  chartSpreads is the chart browser's own list, already in date order across the seasons,
 *  so the two views cannot disagree about where one chart ends and the next starts. */
function chartStretchSerials(showing, index, state) {
  const spreads = chartSpreads(state);
  if (!spreads.length) return null;
  const starts = spreads.map((s) => Math.min(...s.serials));
  let i = -1;
  for (let n = 0; n < starts.length; n++) if (starts[n] <= showing) i = n;
  if (i === -1) return null; // before the first chart there is: nothing to be held to
  const from = starts[i];
  const until = i + 1 < starts.length ? starts[i + 1] : Infinity;
  const within = [...index.keys()].filter((s) => s >= from && s < until).sort((a, b) => a - b);
  return within.length ? within : null;
}

function renderWeek(container, state, onSerialChange, serial = null, opts = {}) {
  // opts.luach: the congregation-facing view, which has no app chrome around it.
  const luach = Boolean(opts.luach);
  // opts.heading: false where whatever put this on the screen has already written the
  // heading itself. On This week the pages and the wall chart are two sides of one screen,
  // so the title and the buttons that swap them belong to the screen, not to this half.
  const heading = !luach && opts.heading !== false;
  const settings = resolveSettings(state.settings);
  const index = weekIndex(state);
  const allSerials = [...index.keys()].sort((a, b) => a - b);
  let serials = allSerials;

  if (!serials.length) {
    container.innerHTML = luach
      ? '<p class="hint">Nothing has been published yet.</p>'
      : `${heading ? '<h2>This week</h2>' : ''}
      <p class="hint">One week at a time, laid out to read rather than to print. Generate a שבת sheet first and the weeks in it show up here.</p>`;
    return;
  }

  const showing = serials.includes(serial) ? serial : currentSerial(serials, settings, (s) => weekEndsMins(s, state, settings));
  /* On the congregation's site, Previous and Next reach only the weeks printed on the
     chart that is up now, and stop at its first and last. A published sheet is a season,
     but what is on the wall is one page of it, and the weeks on that page are the ones
     worth being able to look at: the rest is either months behind or months ahead.

     "The chart that is up" is the stretch it covers rather than the rows printed on it,
     so a Yom Tov week with no row of its own is still reachable: see chartStretchSerials.

     Three taps on the chart lets the whole season out again (navUnlocked in nav-helpers),
     and the admin app is never held at all. */
  const held = luach && !navUnlocked();
  if (held) serials = chartStretchSerials(showing, index, state) || serials;
  const at = serials.indexOf(showing);
  const { sheet } = index.get(showing);
  const week = index.get(showing).week;
  const cardsHtml = weekCardsHtml(showing, index, state, settings);
  const cardCount = (cardsHtml.match(/class="week-card/g) || []).length;

  container.innerHTML = `
    ${
      heading
        ? // no-print, like the nav and the publish panel below. Left printable, this
          // heading and its explanation are the only things on the page not claiming the
          // "weekcard" named page, so they took a sheet of their own: a landscape one, at
          // the wall chart's @page size, empty apart from two lines of screen furniture.
          `<h2 class="no-print">This week</h2>
    <p class="hint no-print">One week at a time, laid out to read rather than to print. It follows whichever שבת is next and moves on once Shabbos is over.</p>`
        : ''
    }
    <div class="week-nav no-print">
      <div class="week-nav-when">
        ${fmtShabbosDate(week.date)}
        <bdi class="week-nav-hebrew" lang="he">${weekEsc(jewishDateString(week.serial, false, settings.useGregorianBefore1582))}</bdi>
      </div>
      <div class="week-nav-row">
        <button type="button" id="week-prev" ${at <= 0 ? 'disabled' : ''}>
          <span aria-hidden="true">&larr;</span><span class="week-nav-word">Previous</span>
        </button>
        <button type="button" id="week-today">Today</button>
        <button type="button" id="week-next" ${at >= serials.length - 1 ? 'disabled' : ''}>
          <span class="week-nav-word">Next</span><span aria-hidden="true">&rarr;</span>
        </button>
      </div>
      <details class="panel week-print-panel no-print" ${optionsOpen ? 'open' : ''}>
        <summary>More options</summary>
        <div class="panel-body">
          <!-- Print is in here rather than out on the nav row above it. Everything to do
               with paper is then in one place, and the row above stays what it is for:
               moving from week to week. The panel is called More options rather than
               Printing options because Print itself now lives in it. -->
          <div class="week-nav-row week-nav-print-one">${printButtonHtml()}${pdfButtonHtml()}${
            // Only where there is a שבת row to build it from. A week whose Shabbos is Yom
            // Tov has no parsha and no row, and an Erev Shabbos message for it would be
            // an empty one.
            sheet ? '<button type="button" class="copy-btn" id="week-copy-btn">Copy text</button>' : ''
          }</div>
          ${
            // Both switches, or neither. Each of them is a question about two pages, and a
            // week that has only one (a Shabbos that is Yom Tov comes through on its
            // Weekday chart alone) has nothing to lay out beside anything and nothing to
            // put first. "Which page first" used to show anyway and answered a question
            // that week did not raise.
            cardCount > 1
              ? `<div class="week-switches">
                  ${switchHtml('week-pages', 'Pages per sheet', [
                    { value: 'one', label: 'One', on: !pairView },
                    { value: 'two', label: 'Two', on: pairView },
                  ])}
                  ${switchHtml('week-order', 'Which page first', [
                    { value: 'shabbos', label: '<bdi lang="he">שבת</bdi>', on: cardOrder(showing, state, settings) === 'shabbos' },
                    { value: 'weekday', label: 'Weekday', on: cardOrder(showing, state, settings) === 'weekday' },
                  ])}
                </div>`
              : ''
          }
          <div class="week-nav-row week-nav-print">
            <button type="button" id="week-print-rest">Print every week to the end of the season</button>
          </div>
          <!-- There was a note here telling a phone to turn the paper round: the sheet
               used to be landscape and the print dialog opens portrait. It is portrait
               itself now, on the same paper a card uses, so there is nothing to say. -->
        </div>
      </details>
      ${
        // At the end of the list, say why rather than just greying Next out. The weeks
        // here are the published ones, and a season stops where the next season begins:
        // Next runs out at Sukkos because the winter chart is not up, which looks like a
        // broken button unless it says so.
        // Not while the view is held to one page of the chart: running out of that page is
        // not running out of what is published, and saying so would be untrue.
        !held && at >= serials.length - 1 && nextSeasonLabel(index, serials)
          ? `<p class="hint no-print week-end-note">This is the last week published. <bdi${hebrewLang(nextSeasonLabel(index, serials))}>${weekEsc(nextSeasonLabel(index, serials))}</bdi> is not up yet${luach ? '' : ', so generate it and publish it below'}.</p>`
          : ''
      }
    </div>
    <div class="week-cards">${cardsHtml}</div>
    ${luach ? '' : publishPanelHtml(sheet, state, Boolean(opts.openPublish))}
  `;

  // null puts it back on whichever Shabbos is next, rather than a pinned week.
  // Three to a line on the שבת card, one on the weekday card. The weekday card carries
  // only three minyanim against a full sheet, so a time to a line is what fills it;
  // the שבת card has eleven rows and would run off the page the same way. Keyed on which
  // card it is rather than where it sits: a Yom Tov week has no שבת card, and going by
  // position gave its חול card the שבת card's three-to-a-line.
  decorateCards(container);
  fitLinesToPage(container);

  // Either the two pages as they are, or the pair of them rebuilt as one landscape sheet.
  // The sheet is a real thing on the screen from here on, not something assembled for the
  // length of a print run, so what goes to the printer is whatever is being looked at.
  const wrap = container.querySelector('.week-cards');
  const onSheet = pairView && cardCount > 1 && buildPairSheet(wrap);
  if (onSheet) {
    // The columns are a different shape from the cards they came out of, so the times are
    // sized again for them. Before the sheet is scaled to the window, not after: a scale
    // on the sheet changes what the columns measure, and with it left on the same sheet
    // fitted at 1.60 in a 412px window and 0.70 in a 1280px one.
    fitPairColumns(wrap.querySelector('.week-pair'));
    fitSheetToWindow(container);
  } else {
    fitPagesToWindow(container);
  }

  // The one Print button: the whole screen goes to the dialog and the choosing happens
  // there, which is where a person can pick a single page anyway.
  //
  /** The English half of the line above the buttons, which is this week's Shabbos date,
   *  read back off the screen rather than rebuilt: it is already formatted there and there
   *  is no sense in two places deciding what a week is called. The Hebrew half is in its
   *  own bdi and is left out, since a filename is no place to be sorting out which
   *  direction a mixed string runs in. */
  const weekPdfName = (root) => {
    const when = root.querySelector('.week-nav-when');
    const hebrew = when?.querySelector('.week-nav-hebrew');
    const english = when ? when.textContent.replace(hebrew ? hebrew.textContent : '', '') : '';
    const plain = english.replace(/[^A-Za-z0-9 ]+/g, '').replace(/\s+/g, ' ').trim();
    return plain ? `Zmanim ${plain}.pdf` : 'Zmanim week.pdf';
  };
  wirePrintButton(container);

  /* The Erev Shabbos message, onto the clipboard, built off the same row the card is (see
     js/erev-text.js for what every piece of it comes from).

     The tables are loaded for the English parsha name. They are cached after the first
     call, so this is a promise that has already settled by the time anyone can press the
     button, and the await costs nothing.

     The clipboard is asked for twice over: navigator.clipboard is refused outside a secure
     context and on some older phones, and a message nobody can paste is no use, so the old
     hidden-textarea route is kept behind it. The result is said on the button rather than
     in an alert, the way the PDF button does it. */
  const copyBtn = container.querySelector('#week-copy-btn');
  if (copyBtn) {
    copyBtn.addEventListener('click', async () => {
      const said = copyBtn.textContent;
      try {
        const { week: w, sheet: s } = index.get(showing);
        if (!s) throw new Error('this week has no שבת row');
        const { columns, row } = rowFor(w, s, state, settings);
        const tables = await loadTables();
        const text = erevShabbosText(columns, row, erevParshaEnglish(w.parsha, tables.parshaNames));
        if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(text);
        else {
          const box = document.createElement('textarea');
          box.value = text;
          box.setAttribute('readonly', '');
          box.style.position = 'fixed';
          box.style.opacity = '0';
          document.body.appendChild(box);
          box.select();
          document.execCommand('copy');
          box.remove();
        }
        copyBtn.textContent = 'Copied';
      } catch (err) {
        console.error('copy failed', err);
        copyBtn.textContent = 'Copy failed';
      }
      setTimeout(() => { copyBtn.textContent = said; }, 2000);
    });
  }

  // The same PDF as the wall chart offers, for the same reason: an iPhone will not print
  // one of these at the right size either, and a PDF states the paper in the file rather
  // than asking for it. Portrait here, since a card is 8.5in by 11in.
  //
  // What counts as a sheet depends on the view. One-sheet mode puts both cards on a single
  // .week-pair, which is one piece of paper: photographing the .week-cards inside it would
  // put out two pages and undo the very thing that view is for. So the pair is looked for
  // first, and only when there is none is a card a sheet.
  wirePdfButton(container, {
    host: () => container.querySelector('.week-cards'),
    name: () => weekPdfName(container),
    sheet: container.querySelector('.week-pair') ? '.week-pair' : '.week-card',
    orientation: 'portrait',
    size: [8.5, 11],
  });

  // The two switches, wired the same way. Both answers change what the week looks like, so
  // both draw it again rather than rearranging it in place: the cards are decorated after
  // they are built (line caps, colon axis, legend, the fit-to-page pass) and those passes
  // are not safe to run over their own output. It is the same reason the print-rest run
  // below restores from raw markup.
  //
  // The one-sheet view claims a page of its own, portrait like the paper a card uses, so
  // printing it needs nothing asked for in the print dialog.
  const onSwitch = (name, apply) => {
    container.querySelector(`.week-switch[aria-labelledby="${name}-label"]`)
      ?.addEventListener('change', (e) => {
        if (!e.target.matches('.week-switch-radio')) return;
        apply(e.target.value);
        onSerialChange(showing);
        // Put the keyboard back on the side now chosen, or the next arrow press goes
        // nowhere: measured, without this document.activeElement came back as BODY and a
        // second press of the arrow keys did nothing at all. This works because optionsOpen
        // keeps the panel open through the redraw, since nothing inside a closed <details>
        // can hold focus.
        //
        // Off the document, not off `container`. On the congregation site the callback
        // rebuilds the whole page, so the #week-host this closure is holding is a detached
        // node by the time it returns and the radio found inside it is a copy nobody can
        // see. Focusing that is what left the page on BODY even with the panel open.
        //
        // preventScroll because the radio itself is a 1px box tucked under the label:
        // without it the browser is entitled to scroll that speck to the middle of the
        // screen.
        document.querySelector(`.week-switch-radio[name="${name}"]:checked`)
          ?.focus({ preventScroll: true });
      });
  };
  onSwitch('week-pages', (value) => { pairView = value === 'two'; });
  onSwitch('week-order', (value) => rememberCardOrder(value === 'weekday' ? 'weekday' : 'shabbos', showing, state, settings));

  // Every week from this one to the end of the season, in one run. Each week is built and
  // treated exactly as it is when it is on the screen on its own, so a printed run cannot
  // drift from what a week looks like: same markup, same passes, and the one-sheet view if
  // that is what is being looked at.
  //
  // To the end of the season and no further. It used to take every week left in the index,
  // which is every week of every published sheet: pressed in August it ran from there to
  // the end of the following חורף, 33 weeks and 67 pages, rather than the six weeks left
  // of קיץ. A season is a שבת sheet plus the Yom Tov weeks after it that only its Weekday
  // chart covers, so the run stops where that changes.
  container.querySelector('#week-print-rest')?.addEventListener('click', () => {
    const wrap = container.querySelector('.week-cards');
    const key = seasonKeyOf(showing, index, state);
    const rest = [];
    for (let i = at; i < serials.length; i++) {
      if (seasonKeyOf(serials[i], index, state) !== key) break;
      rest.push(serials[i]);
    }

    wrap.innerHTML = '';
    for (const serial of rest) {
      // One host per week, so a week's two cards stay together and the one-sheet build has
      // exactly the pair it expects rather than every card in the run.
      const host = document.createElement('div');
      host.className = 'week-cards';
      wrap.appendChild(host);
      host.innerHTML = weekCardsHtml(serial, index, state, settings);
      decorateCards(host);
      fitLinesToPage(host);
      if (pairView && host.querySelectorAll('.week-card').length > 1) {
        buildPairSheet(host);
        fitPairColumns(host.querySelector('.week-pair'));
      }
    }
    // Put back by re-rendering rather than by rebuilding the cards here. The screen may
    // have been on the one-sheet view when this was pressed, and putting the two cards
    // back by hand would have dropped it.
    let done = false;
    const restore = () => {
      if (done) return;
      done = true;
      window.removeEventListener('afterprint', restore);
      onSerialChange(showing);
    };
    window.addEventListener('afterprint', restore);
    window.print();
    setTimeout(restore, 1500);
  });
  // Remembering it is the whole point (see optionsOpen). toggle fires on open and close
  // alike, and .open is the state it has just reached.
  container.querySelector('.week-print-panel')?.addEventListener('toggle', (e) => {
    optionsOpen = e.target.open;
  });

  container.querySelector('#week-today')?.addEventListener('click', () => onSerialChange(null));
  container.querySelector('#week-prev')?.addEventListener('click', () => onSerialChange(serials[at - 1]));
  container.querySelector('#week-next')?.addEventListener('click', () => onSerialChange(serials[at + 1]));

  // Arriving from "Publishing" on Saved sheets: the panel is already open, but it sits
  // below a full week card, so without this you land on the card with no sign that
  // anything happened.
  if (opts.openPublish) container.querySelector('#publish-panel')?.scrollIntoView({ block: 'start' });

  wireSwipe(
    container,
    () => at > 0 && onSerialChange(serials[at - 1]),
    () => at < serials.length - 1 && onSerialChange(serials[at + 1])
  );

  const status = container.querySelector('#publish-status');
  const say = (message, isError = false) => {
    if (!status) return;
    status.textContent = message;
    status.classList.toggle('error', isError);
  };

  /** What is live right now, with a way to take each one back down. */
  const showPublished = async () => {
    const listEl = container.querySelector('#published-list');
    if (!listEl) return;
    try {
      const { data } = await fetchPublished(getPublishToken());
      const live = (data?.sheets || []).filter((s) => s.season !== 'weekday');
      if (!live.length) {
        listEl.innerHTML = '<p class="hint">Nothing is published yet.</p>';
        return;
      }
      listEl.innerHTML =
        '<p class="hint">Live on the congregation&rsquo;s page now:</p>' +
        live
          .map(
            (s) => `<div class="published-row">
              <span><bdi lang="he">${weekEsc(s.season === 'kayitz' ? 'שבת קיץ' : 'שבת חורף')}</bdi> ${s.hebrewYear} <span class="hint">(${s.weeks.length} weeks)</span></span>
              <button type="button" class="btn-danger unpublish-btn" data-season="${s.season}" data-year="${s.hebrewYear}" data-id="${s.id}">Unpublish</button>
            </div>`
          )
          .join('');
      listEl.querySelectorAll('.unpublish-btn').forEach((btn) => {
        btn.addEventListener('click', async () => {
          if (!confirm("Take this season off the congregation's page?")) return;
          btn.disabled = true;
          say('Unpublishing…');
          try {
            const left = await unpublishFromSite({ season: btn.dataset.season, hebrewYear: Number(btn.dataset.year), id: btn.dataset.id }, getPublishToken());
            say(left ? 'Unpublished. The page updates in about a minute.' : 'Unpublished. Nothing is published now.');
            showPublished();
          } catch (err) {
            say(err.message, true);
            btn.disabled = false;
          }
        });
      });
    } catch (err) {
      listEl.innerHTML = '';
      say(err.message, true);
    }
  };
  showPublished();

  container.querySelectorAll('.publish-btn').forEach((btn) =>
    btn.addEventListener('click', async () => {
    btn.disabled = true;
    say('Publishing…');
    try {
      const group = publishableGroups(state).find((g) => g.sheet.id === btn.dataset.id);
      const toPublish = [group.sheet, group.weekday].filter(Boolean);
      await publishToSite(buildPublishedPayload(state, toPublish), getPublishToken());
      say("Published. The congregation's page updates in about a minute.");
      showPublished();
    } catch (err) {
      say(err.message, true);
    } finally {
      btn.disabled = false;
    }
    })
  );
}

/** Rich text from Settings, kept as HTML but with its own outer whitespace trimmed. */
function htmlLines(html) {
  return String(html ?? '').trim();
}

/** Escapes the text, then turns the UL_START/UL_END sentinels the formula ports leave
 *  behind into real <u> elements, and newlines into breaks. Without this an underlined
 *  alternate time loses its underline here while keeping it on the printed chart, and
 *  the sentinel characters sit in the output as invisible strays. */
function weekNl2br(str) {
  // underlineTime writes its value as "<u> 6:42</u>", a space inside the underline. On
  // the wall chart that lead-in is wanted: the times are centred there and it does not
  // show. Here the times are set flush left in a column, and a rule that starts a space
  // early reads as an underline wider than its own number - measured at 5.5 to 5.75px of
  // painted rule past the first digit, against 0.25 to 2.25px for the ones without it,
  // which is only the side bearing the font itself leaves. Moving the space in front of
  // the sentinel keeps the gap between times and takes it out from under the rule.
  // Dropped, not moved out: the times are already joined by a "&nbsp;/&nbsp;" separator,
  // so an extra space in front of an underlined one only makes the gap before it wider
  // than the gap before a plain one - measured at 19.73px against 14.92px, which is
  // visible in a column of times. Any whitespace, matched rather than written out: the
  // character underlineTime puts there is a non-breaking space, not the plain one it
  // looks like in the source, and splitting on a literal " " matches nothing at all.
  const trimmed = weekEsc(str).replace(new RegExp(UL_START + '\\s+', 'g'), UL_START);
  const escaped = trimmed.split(UL_START).join('<u>').split(UL_END).join('</u>');
  return escaped.replace(/\n/g, '<br>');
}

function weekEsc(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// ==== namespace shims for `import * as X` ====
const Z = { sunrise, sunset, sunriseElev, sunsetElev, solarNoon, dstLocal, minchaGedola, minchaGedola30MinAfterChatzos, minchaGedolaLechumra, minchaKetana, samuchLeminchaKetana, plagHamincha, plagHaminchaCustom, sofZmanShmaGRA, sofZmanShmaMGA72, sofZmanTfilaGRA, alos16_1, misheyakir10_2, tzais50, tzais60, tzais72, tzaisGeonim8_5, alos72 };

// ==== app.js ====
const state = loadState();
let tables = null;
let currentTab = 'generate';
let currentSheetId = null;
// Which week the This week screen is showing. Null follows whichever Shabbos is next;
// the prev/next buttons pin it to one.
let weekSerial = null;
// Set when This week is opened from "Publishing" on Saved sheets, so the panel it wants
// is already open when the screen arrives. Cleared as it is used: it describes one trip.
let openPublish = false;
// Which half of This week is showing: 'week' for the week's two pages, 'chart' for the
// wall chart. The same two things the congregation's site offers from its menu, and one
// at a time here for the same reason: they page by different units (a week against a
// stretch of season), so stacked they gave the screen two sets of buttons doing
// different things.
let weekPane = 'week';

// Chrome hijacks the mouse wheel for any focused <input type=number> (scrolling over it
// changes its value instead of scrolling the page) - on a long form like Generate, that
// makes the page feel "stuck" if the cursor happens to be over a number field like Number
// of pages/Hebrew year when the user tries to scroll back up. Blur the field the moment a
// wheel event reaches it so the page scrolls normally instead; the field is still fully
// editable by typing or clicking its up/down arrows.
document.addEventListener(
  'wheel',
  (e) => {
    if (document.activeElement && document.activeElement.tagName === 'INPUT' && document.activeElement.type === 'number') {
      document.activeElement.blur();
    }
  },
  { passive: true }
);

const main = document.getElementById('main');
const nav = document.getElementById('nav');
// Making a chart first, then the week you are on, then the sheets you already have, then
// the things you set once. Rules is no longer among them - it is the first panel inside
// Settings, being something configured rather than a place you go. Generate leading also
// matches where the app opens.
const tabs = ['generate', 'week', 'posters', 'saved', 'settings', 'calc', 'program', 'guide'];
// "Saved sheets" in sentence case, matching the heading on the page it opens - the nav
// said "Saved Sheets" and the page said "Saved sheets".
const tabLabels = { generate: 'Generate', settings: 'Settings', saved: 'Saved sheets', calc: 'Calculations', program: 'Get the program', guide: 'Guide', week: 'This week', posters: 'Posters' };

// Inline stroke icons, sized in em and drawn in currentColor so they follow the nav's
// own colour and size. Inline rather than a font or sprite file so the offline/USB build
// stays a single self-contained folder with no extra assets to load.
const tabIcons = {
  generate: '<path d="M4 3h9l4 4v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1z"/><path d="M13 3v4h4"/><path d="M10 10v6M7 13h6"/>',
  settings: '<circle cx="10" cy="10" r="3"/><path d="M10 1v2m0 14v2M3.6 3.6l1.4 1.4m10 10 1.4 1.4M1 10h2m14 0h2M3.6 16.4 5 15m10-10 1.4-1.4"/>',
  saved: '<path d="M2 5.5A1.5 1.5 0 0 1 3.5 4h4L9 6h7.5A1.5 1.5 0 0 1 18 7.5v8A1.5 1.5 0 0 1 16.5 17h-13A1.5 1.5 0 0 1 2 15.5z"/>',
  week: '<rect x="3" y="4.5" width="14" height="13" rx="1.5"/><path d="M3 8.5h14M7 3v3M13 3v3"/><circle cx="10" cy="12.5" r="1.4"/>',
  guide: '<circle cx="10" cy="10" r="7.5"/><path d="M7.9 7.7a2.1 2.1 0 1 1 2.6 2.5c-.4.15-.5.4-.5.8v.5"/><path d="M10 14.4v.1"/>',
  program: '<path d="M10 3v9"/><path d="M6.5 8.5 10 12l3.5-3.5"/><path d="M3.5 13v2.5A1.5 1.5 0 0 0 5 17h10a1.5 1.5 0 0 0 1.5-1.5V13"/>',
  calc: '<rect x="4" y="2.5" width="12" height="15" rx="1.5"/><path d="M7 6h6"/><path d="M7 9.5h2M11 9.5h2M7 13h2M11 13h2"/>',
  // A sheet on a wall, with a pin at the top.
  posters: '<rect x="4.5" y="4" width="11" height="13.5" rx="1"/><path d="M10 1.5v2.5"/><circle cx="10" cy="1.6" r="1.1"/><path d="M7.5 8.5h5M7.5 11.5h5M7.5 14.5h3"/>',
};
const icon = (name) =>
  `<svg class="nav-icon" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${tabIcons[name]}</svg>`;

/** A brief confirmation, bottom right. Generating a sheet saves it immediately and then
 *  opens it, which looked like nothing had been saved at all: there is no Save button to
 *  press, so nothing told you the sheet already exists in Saved sheets. */
function toast(message) {
  document.querySelector('.toast')?.remove();
  const el = document.createElement('div');
  el.className = 'toast no-print';
  el.setAttribute('role', 'status');
  el.textContent = message;
  document.body.appendChild(el);
  // Long enough to read a sentence, and it fades rather than vanishing.
  setTimeout(() => el.classList.add('is-leaving'), 4000);
  setTimeout(() => el.remove(), 4600);
}

function persist() {
  saveState(state);
}

function renderNav() {
  nav.innerHTML = tabs
    .map((t) => `<button class="nav-btn ${t === currentTab && !currentSheetId ? 'active' : ''}" data-tab="${t}">${icon(t)}<span>${tabLabels[t]}</span></button>`)
    .join('');
  nav.querySelectorAll('.nav-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      currentTab = btn.dataset.tab;
      currentSheetId = null;
      render();
    });
  });
}

/** This week: the heading, the two buttons that choose what it shows, and whichever of
 *  the two is chosen. The same pair the congregation's site puts on its menu, so the two
 *  screens hold the same things in the same order. */
function renderWeekTab(showPublish) {
  const panes = [
    { key: 'week', label: 'Weekly Zmanim' },
    { key: 'chart', label: 'Zmanim chart' },
  ];
  main.innerHTML = `
    <h2 class="no-print">This week</h2>
    <p class="hint no-print">Everything the congregation can see: the week's two pages, and the wall chart.</p>
    <div class="pane-switch no-print" role="tablist">
      ${panes
        .map(
          (p) =>
            `<button type="button" role="tab" aria-selected="${p.key === weekPane}" class="pane-btn ${
              p.key === weekPane ? 'is-on' : ''
            }" data-pane="${p.key}">${p.label}</button>`
        )
        .join('')}
    </div>
    <div id="week-pane"></div>`;
  main.querySelectorAll('.pane-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      if (btn.dataset.pane === weekPane) return;
      weekPane = btn.dataset.pane;
      render();
    });
  });

  const host = main.querySelector('#week-pane');
  if (weekPane === 'chart') {
    renderChartBrowser(host, state, { empty: 'Generate a שבת sheet and its chart shows up here.' });
    return;
  }
  renderWeek(
    host,
    state,
    (serial) => {
      weekSerial = serial;
      render();
    },
    weekSerial,
    { openPublish: showPublish, heading: false }
  );
}

function render() {
  renderNav();
  // A sheet needs the full width (a page is a fixed 11in); every other screen is held to
  // a column next to the sidebar. Saved sheets gets a wider one: it's a six-column table,
  // and at the standard width every cell in it wrapped. See app.css.
  main.classList.toggle('is-sheet-view', Boolean(currentSheetId));
  main.classList.toggle('is-wide', !currentSheetId && currentTab === 'saved');
  // The nav used to be hidden while a sheet was open (it sat in a top bar that competed
  // with the sheet's own toolbar). In the sidebar it just stays put - a persistent
  // sidebar with its links blanked out reads as broken. Clicking one does exactly what
  // the sheet's Back button does, and a pending cell edit still commits on blur first.
  if (currentSheetId) {
    const sheet = state.sheets.find((s) => s.id === currentSheetId);
    renderSheet(main, state, sheet, (evt) => {
      if (evt.back) {
        currentSheetId = null;
        render();
      } else if (evt.save) {
        persist();
        render(); // re-render so the ✎ overridden-cell flag appears immediately
      } else if (evt.openSheetId) {
        currentSheetId = evt.openSheetId; // e.g. the Weekday chart <-> Shabbos sheet companion link
        render();
      }
    });
    return;
  }
  if (currentTab === 'settings') {
    renderSettings(
      main,
      state,
      (next) => {
        state.settings = next;
        persist();
        render();
      },
      // Called after an Import replaced the whole state object's contents (settings,
      // sheets, and rules together) - persist it and re-render from scratch.
      () => {
        persist();
        currentSheetId = null;
        render();
      },
      // Rules live inside Settings now. They are saved on the same state object but not
      // through the settings form, so they get their own save: a rule is written the
      // moment it is added or edited, with no Save button to press.
      () => persist()
    );
  } else if (currentTab === 'generate') {
    renderGenerate(
      main,
      state,
      tables,
      (sheet) => {
        state.sheets.push(sheet);
        persist();
        currentSheetId = sheet.id;
        render();
        const weekday = state.sheets.find((s) => s.season === 'weekday' && s.linkedSheetId === sheet.id);
        toast(weekday ? 'Saved to Saved sheets, with its Weekday chart.' : 'Saved to Saved sheets.');
      },
      (tab) => {
        currentTab = tab;
        render();
      }
    );
  } else if (currentTab === 'week') {
    const showPublish = openPublish;
    openPublish = false;
    // Coming from "Publishing" on Saved sheets, which is a panel under the week's pages:
    // whichever half was last open, that trip wants this one.
    if (showPublish) weekPane = 'week';
    renderWeekTab(showPublish);
  } else if (currentTab === 'calc') {
    renderCalculations(main, state, (tab) => {
      currentTab = tab;
      render();
    });
  } else if (currentTab === 'posters') {
    renderPosters(main, state);
  } else if (currentTab === 'program') {
    renderProgram(main);
  } else if (currentTab === 'guide') {
    renderGuide(main, (tab) => {
      currentTab = tab;
      render();
    });
  } else if (currentTab === 'saved') {
    renderSavedSheets(
      main,
      state,
      (id) => {
        currentSheetId = id;
        render();
      },
      // An array: a row in Saved sheets is a Shabbos sheet plus the Weekday chart made
      // with it, and Delete takes the pair.
      (ids) => {
        state.sheets = state.sheets.filter((s) => !ids.includes(s.id));
        persist();
        render();
      },
      // Lock/unlock mutates the sheet in place, so this just saves and redraws the list.
      () => {
        persist();
        render();
      },
      // "Publishing" on the list goes to the panel on This week, which is the one place
      // that shows what the congregation has in front of it and can take a season down.
      () => {
        currentTab = 'week';
        openPublish = true;
        render();
      }
    );
  }
}


// The way back to the congregation's site: three taps on the name at the top of the navy
// sidebar. The same gesture the congregation's page carries in its own navy cap, in the
// other direction. Wired once, since the sidebar is in the page rather than rendered.
wireSecretDoor(document.querySelector('.sidebar-brand'), '/');

loadTables()
  .then((t) => {
    tables = t;
    render();
  })
  .catch((err) => {
    main.innerHTML = `<p class="error">Failed to load Hebrew-calendar data files: ${err.message}. Make sure you're serving this folder over http:// (not opening index.html directly) so the data/*.json files can load.</p>`;
  });